#!/usr/bin/env python3
"""Build one self-contained three-tab HRA lung comparison website.

This single Python file contains the three validated builders used for:

1. CTann v9 reference supertree
2. HRApop v1.1 lung Azimuth versus Pan-human Azimuth population comparison
3. HLCA exact-node comparison across paired lung partitions

The generated website embeds all three child HTML documents into one page and
writes ``docs/index.html`` by default. Each tab is loaded lazily into an iframe,
which keeps the three visualizations isolated while still producing one HTML
artifact suitable for GitHub Pages.

Expected project structure::

    project/
    ├── build_lung_azimuth_three_tab_site.py
    ├── data/
    │   ├── ctann-v9.csv
    │   ├── cell-types-in-anatomical-structurescts-per-as.csv
    │   └── <HLCA aggregate comparison>.csv
    └── docs/

Run without arguments::

    python3 build_lung_azimuth_three_tab_site.py
"""

from __future__ import annotations

import argparse
import html
import json
import types
from pathlib import Path
from typing import Any

BUILD_VERSION = "1.0"
SCRIPT_DIR = Path(__file__).resolve().parent
DEFAULT_TREE = SCRIPT_DIR / "data" / "ctann-v9.csv"
DEFAULT_HRAPOP = (
    SCRIPT_DIR
    / "data"
    / "cell-types-in-anatomical-structurescts-per-as.csv"
)
DEFAULT_OUTPUT = SCRIPT_DIR / "docs" / "index.html"

REFERENCE_BUILDER_SOURCE = 'from __future__ import annotations\n\nimport argparse\nimport csv\nimport html\nimport json\nimport re\nfrom collections import Counter, defaultdict, deque\nfrom pathlib import Path\nfrom typing import Any\n\nCYTOSCAPE_CDN = (\n    "https://cdn.jsdelivr.net/npm/cytoscape@3.33.1/dist/cytoscape.min.js"\n)\n\nBUILD_VERSION = "3.0"\nSCRIPT_DIR = Path(__file__).resolve().parent\nDEFAULT_INPUT = SCRIPT_DIR / "data" / "ctann-v9.csv"\nDEFAULT_OUTPUT = SCRIPT_DIR / "output_htmls" / "reference-supertree-v9.html"\n\nMAX_PATH_LEVEL = 12\nCOLUMN_DX = 292.5\nROW_DY = 8.5\nLEAF_STEP = 3.0\nROOT_GAP = 2.0\n\nCOLORS = {\n    "neutral": "#7A7B78",\n    "martin": "#1E90FF",\n    "chenchen": "#E31A1C",\n    "search": "#00A651",\n}\n\n\ndef normalize_ontology_id(value: str | None) -> str:\n    """Normalize common OBO URI, underscore, and CURIE identifiers."""\n    raw = (value or "").strip()\n    if not raw:\n        return ""\n\n    for prefix in (\n        "https://purl.obolibrary.org/obo/",\n        "http://purl.obolibrary.org/obo/",\n    ):\n        if raw.startswith(prefix):\n            raw = raw[len(prefix) :]\n            break\n\n    match = re.fullmatch(\n        r"([A-Za-z][A-Za-z0-9-]*)[_:]([A-Za-z0-9_.-]+)",\n        raw,\n    )\n    if match:\n        return f"{match.group(1).upper()}:{match.group(2)}"\n\n    # Preserve identifiers that are not standard OBO CURIEs.\n    return raw\n\n\ndef detect_delimiter(path: Path) -> str:\n    """Detect comma- versus tab-delimited input."""\n    if path.suffix.lower() in {".tsv", ".tab"}:\n        return "\\t"\n\n    with path.open("r", encoding="utf-8-sig", newline="") as handle:\n        sample = handle.read(65536)\n\n    try:\n        return csv.Sniffer().sniff(sample, delimiters=",\\t;").delimiter\n    except csv.Error:\n        return ","\n\n\ndef read_supertree(path: Path) -> dict[str, Any]:\n    delimiter = detect_delimiter(path)\n\n    with path.open(newline="", encoding="utf-8-sig") as handle:\n        reader = csv.DictReader(handle, delimiter=delimiter)\n        fieldnames = set(reader.fieldnames or [])\n\n        required = {"CT/1 - Sources", "AS/1/ID", "AS/1/LABEL"}\n        missing = required - fieldnames\n        if missing:\n            raise ValueError(\n                f"Missing required columns in {path}: {sorted(missing)}"\n            )\n\n        rows = list(reader)\n\n    # Every node appearing anywhere along a source path.\n    node_sources: dict[str, set[str]] = defaultdict(set)\n    node_source_displays: dict[str, set[str]] = defaultdict(set)\n\n    # Only the final, most-specific node in each row\'s path.\n    terminal_sources: dict[str, set[str]] = defaultdict(set)\n    terminal_source_displays: dict[str, set[str]] = defaultdict(set)\n\n    labels: dict[str, str] = {}\n    label_variants: dict[str, set[str]] = defaultdict(set)\n\n    parents: dict[str, set[str]] = defaultdict(set)\n    children: dict[str, set[str]] = defaultdict(set)\n    edge_counts: Counter[tuple[str, str]] = Counter()\n    source_counts: Counter[str] = Counter()\n\n    valid_row_count = 0\n    empty_path_row_count = 0\n\n    for row in rows:\n        source_raw = (row.get("CT/1 - Sources") or "").strip()\n        source_display = source_raw or "(blank)"\n        source_norm = source_display.casefold()\n        source_counts[source_display] += 1\n\n        path_nodes: list[tuple[str, str]] = []\n\n        for level in range(1, MAX_PATH_LEVEL + 1):\n            node_id = normalize_ontology_id(row.get(f"AS/{level}/ID"))\n            node_label = (row.get(f"AS/{level}/LABEL") or "").strip()\n\n            if node_id:\n                path_nodes.append((node_id, node_label or node_id))\n\n        if not path_nodes:\n            empty_path_row_count += 1\n            continue\n\n        valid_row_count += 1\n\n        terminal_id = path_nodes[-1][0]\n        terminal_sources[terminal_id].add(source_norm)\n        terminal_source_displays[terminal_id].add(source_display)\n\n        previous: str | None = None\n\n        for node_id, node_label in path_nodes:\n            # This mirrors the original script: later rows may update the\n            # preferred display label for the same ontology ID.\n            labels[node_id] = node_label\n            label_variants[node_id].add(node_label)\n\n            node_sources[node_id].add(source_norm)\n            node_source_displays[node_id].add(source_display)\n\n            if previous and previous != node_id:\n                parents[node_id].add(previous)\n                children[previous].add(node_id)\n                edge_counts[(previous, node_id)] += 1\n\n            previous = node_id\n\n    all_nodes = set(labels)\n    if not all_nodes:\n        raise ValueError(f"No supertree nodes were found in {path}.")\n\n    indegree = {node: len(parents.get(node, set())) for node in all_nodes}\n    roots = sorted(\n        [node for node, degree in indegree.items() if degree == 0],\n        key=lambda node: (labels.get(node, ""), node),\n    )\n\n    if not roots:\n        roots = [min(all_nodes)]\n\n    # Shortest distance from any root, matching the original layout logic.\n    depth: dict[str, int] = {}\n    queue: deque[str] = deque()\n\n    for root in roots:\n        depth[root] = 0\n        queue.append(root)\n\n    while queue:\n        node = queue.popleft()\n\n        ordered_children = sorted(\n            children.get(node, set()),\n            key=lambda child: (\n                -edge_counts[(node, child)],\n                labels.get(child, ""),\n                child,\n            ),\n        )\n\n        for child in ordered_children:\n            candidate = depth[node] + 1\n            if child not in depth or candidate < depth[child]:\n                depth[child] = candidate\n                queue.append(child)\n\n    # Any disconnected nodes are retained, as in the original fallback.\n    for node in all_nodes:\n        depth.setdefault(node, 0)\n\n    # Choose one primary parent solely for stable layout. All original\n    # parent-child edges remain visible in the final Cytoscape graph.\n    primary_parent: dict[str, str] = {}\n\n    for node in all_nodes:\n        node_parents = parents.get(node, set())\n        if not node_parents:\n            continue\n\n        ranked = sorted(\n            node_parents,\n            key=lambda parent: (\n                -edge_counts[(parent, node)],\n                depth.get(parent, 999),\n                labels.get(parent, ""),\n                parent,\n            ),\n        )\n        primary_parent[node] = ranked[0]\n\n    primary_children: dict[str, list[str]] = defaultdict(list)\n    for child, parent in primary_parent.items():\n        primary_children[parent].append(child)\n\n    for parent in primary_children:\n        primary_children[parent].sort(\n            key=lambda child: (\n                depth.get(child, 999),\n                -len(children.get(child, set())),\n                labels.get(child, ""),\n                child,\n            )\n        )\n\n    # Keep the same recursive leaf-order layout used by the Matplotlib script.\n    y_position: dict[str, float] = {}\n    cursor = 0.0\n    active_stack: set[str] = set()\n\n    def assign_y(node: str) -> None:\n        nonlocal cursor\n\n        if node in y_position:\n            return\n        if node in active_stack:\n            raise ValueError(\n                "A cycle was encountered in the primary-parent layout at "\n                f"{node}."\n            )\n\n        active_stack.add(node)\n        child_list = primary_children.get(node, [])\n\n        if not child_list:\n            y_position[node] = cursor\n            cursor += LEAF_STEP\n        else:\n            for child in child_list:\n                assign_y(child)\n            y_position[node] = sum(\n                y_position[child] for child in child_list\n            ) / len(child_list)\n\n        active_stack.remove(node)\n\n    for index, root in enumerate(roots):\n        assign_y(root)\n        if index < len(roots) - 1:\n            cursor += ROOT_GAP\n\n    for node in sorted(\n        all_nodes,\n        key=lambda value: (\n            depth.get(value, 999),\n            labels.get(value, ""),\n            value,\n        ),\n    ):\n        if node not in y_position:\n            y_position[node] = cursor\n            cursor += LEAF_STEP\n\n    def primary_path(node_id: str) -> list[str]:\n        result = [node_id]\n        seen = {node_id}\n        current = node_id\n\n        while current in primary_parent:\n            current = primary_parent[current]\n            if current in seen:\n                break\n            seen.add(current)\n            result.append(current)\n\n        result.reverse()\n        return result\n\n    nodes: list[dict[str, Any]] = []\n\n    martin_only_count = 0\n    chenchen_only_count = 0\n    shared_terminal_count = 0\n\n    for node_id in sorted(\n        all_nodes,\n        key=lambda value: (\n            depth.get(value, 999),\n            labels.get(value, ""),\n            value,\n        ),\n    ):\n        node_terminal_sources = terminal_sources.get(node_id, set())\n        is_martin_terminal = "martin" in node_terminal_sources\n        is_chenchen_terminal = "chenchen" in node_terminal_sources\n\n        if is_martin_terminal and is_chenchen_terminal:\n            terminal_status = "shared"\n            classes = "shared-terminal"\n            shared_terminal_count += 1\n        elif is_martin_terminal:\n            terminal_status = "martin"\n            classes = "martin-terminal"\n            martin_only_count += 1\n        elif is_chenchen_terminal:\n            terminal_status = "chenchen"\n            classes = "chenchen-terminal"\n            chenchen_only_count += 1\n        else:\n            terminal_status = "neutral"\n            classes = "neutral-node"\n\n        path_ids = primary_path(node_id)\n        path_labels = [labels.get(value, value) for value in path_ids]\n\n        parent_ids = sorted(\n            parents.get(node_id, set()),\n            key=lambda value: (labels.get(value, ""), value),\n        )\n        child_ids = sorted(\n            children.get(node_id, set()),\n            key=lambda value: (labels.get(value, ""), value),\n        )\n\n        nodes.append(\n            {\n                "data": {\n                    "id": node_id,\n                    "label": labels.get(node_id, node_id),\n                    "labelVariants": sorted(\n                        label_variants.get(node_id, set()),\n                        key=str.casefold,\n                    ),\n                    "depth": depth.get(node_id, 0),\n                    "parentIds": parent_ids,\n                    "parentLabels": [\n                        labels.get(value, value) for value in parent_ids\n                    ],\n                    "childIds": child_ids,\n                    "childLabels": [\n                        labels.get(value, value) for value in child_ids\n                    ],\n                    "parentCount": len(parent_ids),\n                    "childCount": len(child_ids),\n                    "isRoot": node_id in roots,\n                    "isPrimaryParentTarget": node_id in primary_parent,\n                    "primaryParentId": primary_parent.get(node_id, ""),\n                    "primaryParentLabel": labels.get(\n                        primary_parent.get(node_id, ""), ""\n                    ),\n                    "primaryPathIds": path_ids,\n                    "primaryPathLabels": path_labels,\n                    "primaryPathText": " → ".join(path_labels),\n                    "sources": sorted(\n                        node_source_displays.get(node_id, set()),\n                        key=str.casefold,\n                    ),\n                    "terminalSources": sorted(\n                        terminal_source_displays.get(node_id, set()),\n                        key=str.casefold,\n                    ),\n                    "terminalStatus": terminal_status,\n                },\n                "classes": classes,\n                "position": {\n                    "x": depth.get(node_id, 0) * COLUMN_DX,\n                    "y": y_position[node_id] * ROW_DY,\n                },\n            }\n        )\n\n    edges: list[dict[str, Any]] = []\n\n    for index, (parent, child) in enumerate(\n        sorted(\n            edge_counts,\n            key=lambda pair: (\n                depth.get(pair[0], 999),\n                labels.get(pair[0], ""),\n                labels.get(pair[1], ""),\n                pair,\n            ),\n        )\n    ):\n        is_primary = primary_parent.get(child) == parent\n\n        edges.append(\n            {\n                "data": {\n                    "id": f"edge-{index}",\n                    "source": parent,\n                    "target": child,\n                    "rowCount": edge_counts[(parent, child)],\n                    "isPrimary": is_primary,\n                },\n                "classes": "primary-edge" if is_primary else "secondary-edge",\n            }\n        )\n\n    summary = {\n        "inputFile": path.name,\n        "rowCount": len(rows),\n        "validPathRowCount": valid_row_count,\n        "emptyPathRowCount": empty_path_row_count,\n        "nodeCount": len(nodes),\n        "edgeCount": len(edges),\n        "rootCount": len(roots),\n        "multiParentNodeCount": sum(\n            1 for node in all_nodes if len(parents.get(node, set())) > 1\n        ),\n        "martinTerminalCount": martin_only_count,\n        "chenchenTerminalCount": chenchen_only_count,\n        "sharedTerminalCount": shared_terminal_count,\n        "otherNodeCount": (\n            len(nodes)\n            - martin_only_count\n            - chenchen_only_count\n            - shared_terminal_count\n        ),\n        "sourceCounts": [\n            {"source": source, "rowCount": count}\n            for source, count in sorted(\n                source_counts.items(), key=lambda item: item[0].casefold()\n            )\n        ],\n    }\n\n    return {\n        "nodes": nodes,\n        "edges": edges,\n        "summary": summary,\n    }\n\n\ndef cytoscape_script_tag(local_js: Path | None) -> str:\n    if local_js is None:\n        return f\'<script src="{CYTOSCAPE_CDN}"></script>\'\n\n    if not local_js.exists():\n        raise FileNotFoundError(f"Cytoscape.js file not found: {local_js}")\n\n    code = local_js.read_text(encoding="utf-8")\n    return f"<script>\\n{code}\\n</script>"\n\n\ndef render_html(\n    payload: dict[str, Any],\n    title: str,\n    local_cytoscape_js: Path | None,\n) -> str:\n    graph_json = json.dumps(\n        payload,\n        ensure_ascii=False,\n        separators=(",", ":"),\n    ).replace("</", "<\\\\/")\n\n    template = r\'\'\'<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1" />\n<title>__TITLE__</title>\n__CYTOSCAPE_SCRIPT__\n<style>\n:root {\n    --bg: #eef2f7;\n    --panel: #ffffff;\n    --border: #d8dee8;\n    --text: #18212f;\n    --muted: #657287;\n    --blue: __MARTIN_COLOR__;\n    --red: __CHENCHEN_COLOR__;\n    --gray: __NEUTRAL_COLOR__;\n    --green: __SEARCH_COLOR__;\n    --details-width: 390px;\n    --toolbar-height: 76px;\n}\n\n* { box-sizing: border-box; }\n\nhtml,\nbody {\n    width: 100%;\n    height: 100%;\n    margin: 0;\n    overflow: hidden;\n}\n\nbody {\n    font-family: Inter, ui-sans-serif, system-ui, -apple-system,\n        BlinkMacSystemFont, "Segoe UI", sans-serif;\n    color: var(--text);\n    background: var(--bg);\n}\n\nbutton,\ninput { font: inherit; }\n\n#app {\n    width: 100%;\n    height: 100%;\n    display: grid;\n    grid-template-rows: var(--toolbar-height) 1fr;\n}\n\nheader {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 10px 16px;\n    background: var(--panel);\n    border-bottom: 1px solid var(--border);\n    z-index: 10;\n}\n\n.brand { min-width: 330px; }\n.brand h1 {\n    margin: 0 0 3px;\n    font-size: 18px;\n    line-height: 1.2;\n}\n.brand p {\n    margin: 0;\n    color: var(--muted);\n    font-size: 12px;\n}\n\n.search-wrap {\n    position: relative;\n    flex: 1;\n    max-width: 540px;\n}\n\n#searchInput {\n    width: 100%;\n    height: 40px;\n    padding: 0 44px 0 13px;\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    outline: none;\n    background: #fbfcfe;\n}\n\n#searchInput:focus {\n    border-color: #8ca9fb;\n    box-shadow: 0 0 0 3px rgba(21, 94, 239, 0.12);\n}\n\n#searchButton {\n    position: absolute;\n    top: 4px;\n    right: 4px;\n    width: 34px;\n    height: 32px;\n    border: 0;\n    border-radius: 8px;\n    background: transparent;\n    cursor: pointer;\n}\n\n.controls {\n    display: flex;\n    align-items: center;\n    gap: 7px;\n    margin-left: auto;\n}\n\n.control {\n    height: 38px;\n    padding: 0 11px;\n    border: 1px solid var(--border);\n    border-radius: 9px;\n    background: #fff;\n    color: #253246;\n    cursor: pointer;\n}\n.control:hover { background: #f4f7fb; }\n.control.active {\n    color: #1049b8;\n    border-color: #a6baf2;\n    background: #edf2ff;\n}\n\nmain {\n    min-height: 0;\n    display: grid;\n    grid-template-columns: 1fr var(--details-width);\n}\n\n#graphWrap {\n    position: relative;\n    min-width: 0;\n    overflow: hidden;\n    background:\n        radial-gradient(circle at 35% 20%, #ffffff 0, #f7f9fc 42%, #eef2f7 100%);\n}\n\n#cy {\n    position: absolute;\n    inset: 0;\n}\n\n#legend {\n    position: absolute;\n\n    /* Center the legend along the bottom of the graph canvas */\n    left: 50%;\n    bottom: 14px;\n    top: auto;\n    transform: translateX(-50%);\n\n    /* Use 90% of the Cytoscape canvas width */\n    width: 90%;\n    padding: 10px 14px;\n\n    display: grid;\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n    column-gap: 18px;\n    row-gap: 3px;\n\n    border: 1px solid rgba(204, 212, 224, 0.95);\n    border-radius: 12px;\n    background: rgba(255, 255, 255, 0.94);\n    box-shadow: 0 8px 30px rgba(49, 67, 92, 0.10);\n    backdrop-filter: blur(7px);\n    z-index: 6;\n}\n\n.legend-title {\n    grid-column: 1 / -1;\n    margin-bottom: 4px;\n    font-size: 13px;\n    font-weight: 700;\n}\n\n.legend-row {\n    display: flex;\n    align-items: center;\n    gap: 9px;\n    margin: 3px 0;\n    color: #364258;\n    font-size: 12px;\n    line-height: 1.25;\n}\n\n.legend-note {\n    grid-column: 1 / -1;\n    margin-top: 5px;\n    padding-top: 7px;\n    border-top: 1px solid #e3e7ee;\n    color: var(--muted);\n    font-size: 11px;\n    line-height: 1.35;\n}\n\n.dot {\n    flex: 0 0 auto;\n    width: 14px;\n    height: 14px;\n    border-radius: 50%;\n}\n.dot.gray { background: var(--gray); }\n.dot.blue { background: var(--blue); }\n.dot.red { background: var(--red); }\n.dot.shared {\n    background: linear-gradient(90deg, var(--blue) 0 50%, var(--red) 50% 100%);\n}\n\n.line-sample {\n    width: 26px;\n    height: 0;\n    border-top: 2px solid #4a4a4a;\n}\n.line-sample.secondary {\n    border-top-style: dashed;\n    opacity: 0.35;\n}\n.line-sample.hover-root {\n    border-top-width: 3px;\n    border-top-color: #111827;\n}\n.line-sample.hover-subtree {\n    border-top-width: 3px;\n    border-top-style: dotted;\n    border-top-color: #657084;\n}\n\n.legend-note {\n    margin-top: 9px;\n    padding-top: 8px;\n    border-top: 1px solid #e3e7ee;\n    color: var(--muted);\n    font-size: 11px;\n    line-height: 1.35;\n}\n\n#statusBadge {\n    position: absolute;\n    left: 14px;\n    top: 14px;\n    bottom: auto;\n    max-width: 520px;\n    padding: 8px 10px;\n    border: 1px solid rgba(204, 212, 224, 0.95);\n    border-radius: 9px;\n    background: rgba(255, 255, 255, 0.94);\n    color: #445168;\n    font-size: 12px;\n    z-index: 6;\n}\n\n#tooltip {\n    position: fixed;\n    display: none;\n    max-width: 360px;\n    padding: 9px 11px;\n    border: 1px solid #cfd6e2;\n    border-radius: 9px;\n    background: rgba(20, 28, 40, 0.96);\n    color: #fff;\n    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.22);\n    font-size: 12px;\n    line-height: 1.35;\n    pointer-events: none;\n    z-index: 30;\n}\n.tooltip-title { font-weight: 700; margin-bottom: 3px; }\n.tooltip-muted { color: #c7d0dc; }\n\naside {\n    min-width: 0;\n    overflow-y: auto;\n    padding: 16px;\n    background: var(--panel);\n    border-left: 1px solid var(--border);\n}\n\naside h2 {\n    margin: 0 0 4px;\n    font-size: 17px;\n}\n\n.aside-subtitle {\n    margin: 0 0 14px;\n    color: var(--muted);\n    font-size: 12px;\n    line-height: 1.4;\n}\n\n.card {\n    margin-bottom: 12px;\n    padding: 12px;\n    border: 1px solid var(--border);\n    border-radius: 11px;\n    background: #fff;\n}\n\n.card-title {\n    margin: 0 0 9px;\n    color: #4f5b70;\n    font-size: 12px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.045em;\n}\n\n.kpi-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 8px;\n}\n\n.kpi {\n    padding: 9px;\n    border-radius: 9px;\n    background: #f4f7fb;\n}\n.kpi-value {\n    font-size: 19px;\n    font-weight: 750;\n}\n.kpi-label {\n    margin-top: 2px;\n    color: var(--muted);\n    font-size: 11px;\n}\n\n.detail-grid {\n    display: grid;\n    grid-template-columns: 112px minmax(0, 1fr);\n    gap: 7px 9px;\n    font-size: 12px;\n}\n.detail-key { color: var(--muted); }\n.detail-value {\n    overflow-wrap: anywhere;\n    color: #263247;\n}\n\n.path-box,\n.list-box {\n    margin-top: 8px;\n    padding: 8px 9px;\n    border-radius: 8px;\n    background: #f6f8fb;\n    color: #334057;\n    font-size: 11px;\n    line-height: 1.45;\n    overflow-wrap: anywhere;\n}\n\n.source-list {\n    margin: 0;\n    padding-left: 18px;\n    color: #334057;\n    font-size: 12px;\n}\n.source-list li { margin: 4px 0; }\n\n.empty-state {\n    padding: 18px 12px;\n    border: 1px dashed #ccd4e0;\n    border-radius: 10px;\n    color: var(--muted);\n    font-size: 13px;\n    line-height: 1.5;\n    text-align: center;\n}\n</style>\n</head>\n<body>\n<div id="app">\n    <header>\n        <div class="brand">\n            <h1>__TITLE__</h1>\n            <p>Interactive Cytoscape rendering of the CTann v9 reference supertree</p>\n        </div>\n\n        <div class="search-wrap">\n            <input\n                id="searchInput"\n                type="search"\n                placeholder="Search by cell type label, ontology ID, or source"\n                autocomplete="off"\n            />\n            <button id="searchButton" title="Search">⌕</button>\n        </div>\n\n        <div class="controls">\n            <button id="fitButton" class="control">Fit graph</button>\n            <button id="labelsButton" class="control active">Labels</button>\n            <button id="clearButton" class="control">Clear</button>\n            <button id="pngButton" class="control">Export PNG</button>\n        </div>\n    </header>\n\n    <main>\n        <section id="graphWrap">\n            <div id="cy"></div>\n\n            <div id="legend">\n                <div class="legend-title">Reference supertree legend</div>\n                <div class="legend-row">\n                    <span class="dot gray"></span>\n                    <span>All other hierarchy nodes</span>\n                </div>\n                <div class="legend-row">\n                    <span class="dot blue"></span>\n                    <span>Martin terminal node</span>\n                </div>\n                <div class="legend-row">\n                    <span class="dot red"></span>\n                    <span>Chenchen terminal node</span>\n                </div>\n                <div class="legend-row">\n                    <span class="dot shared"></span>\n                    <span>Terminal node in both sources</span>\n                </div>\n                <div class="legend-row">\n                    <span class="line-sample"></span>\n                    <span>Primary layout edge</span>\n                </div>\n                <div class="legend-row">\n                    <span class="line-sample secondary"></span>\n                    <span>Additional parent edge</span>\n                </div>\n                <div class="legend-row">\n                    <span class="line-sample hover-root"></span>\n                    <span>Hover: primary path to root</span>\n                </div>\n                <div class="legend-row">\n                    <span class="line-sample hover-subtree"></span>\n                    <span>Hover: all descendant branches</span>\n                </div>\n                <div class="legend-note">\n                    Hover over a node to trace its primary root path with solid lines and every reachable descendant branch with dotted lines. “Terminal” means the final, most-specific ontology node in at least one source row.\n                </div>\n            </div>\n\n            <div id="statusBadge"></div>\n        </section>\n\n        <aside>\n            <h2>Reference supertree</h2>\n            <p class="aside-subtitle">\n                Click a node for ontology, hierarchy, and source details. Hover to trace its root path and descendant subtrees.\n            </p>\n\n            <div id="summaryPanel"></div>\n            <div id="detailsPanel" class="empty-state">\n                Select a node to inspect its details.\n            </div>\n        </aside>\n    </main>\n</div>\n\n<div id="tooltip"></div>\n\n<script>\nconst GRAPH = __GRAPH_JSON__;\nconst summary = GRAPH.summary;\n\nconst cy = cytoscape({\n    container: document.getElementById("cy"),\n    elements: [...GRAPH.nodes, ...GRAPH.edges],\n    layout: {\n        name: "preset",\n        fit: true,\n        padding: 72\n    },\n    minZoom: 0.03,\n    maxZoom: 5,\n    wheelSensitivity: 0.18,\n    pixelRatio: "auto",\n    style: [\n        {\n            selector: "node",\n            style: {\n                "width": 14,\n                "height": 14,\n                "background-color": "__NEUTRAL_COLOR__",\n                "border-width": 0,\n                "label": "data(label)",\n                "font-size": 10,\n                "font-family": "Inter, system-ui, sans-serif",\n                "color": "#111111",\n                "text-valign": "bottom",\n                "text-halign": "center",\n                "text-margin-y": 4,\n                "text-wrap": "wrap",\n                "text-max-width": 200,\n                "min-zoomed-font-size": 4,\n                "z-index": 3\n            }\n        },\n        {\n            selector: "node.martin-terminal",\n            style: {\n                "background-color": "__MARTIN_COLOR__"\n            }\n        },\n        {\n            selector: "node.chenchen-terminal",\n            style: {\n                "background-color": "__CHENCHEN_COLOR__"\n            }\n        },\n        {\n            selector: "node.shared-terminal",\n            style: {\n                "background-color": "#ffffff",\n                "pie-size": "100%",\n                "pie-1-background-color": "__MARTIN_COLOR__",\n                "pie-1-background-size": "50%",\n                "pie-2-background-color": "__CHENCHEN_COLOR__",\n                "pie-2-background-size": "50%"\n            }\n        },\n        {\n            selector: "edge",\n            style: {\n                "curve-style": "straight",\n                "line-color": "#4a4a4a",\n                "width": 0.8,\n                "opacity": 0.22,\n                "z-index": 1\n            }\n        },\n        {\n            selector: "edge.primary-edge",\n            style: {\n                "width": 1.0,\n                "opacity": 0.56\n            }\n        },\n        {\n            selector: "edge.secondary-edge",\n            style: {\n                "line-style": "dashed",\n                "opacity": 0.22\n            }\n        },\n        {\n            selector: ".dimmed",\n            style: {\n                "opacity": 0.07,\n                "text-opacity": 0.03\n            }\n        },\n        {\n            selector: "node.search-hit",\n            style: {\n                "width": 22,\n                "height": 22,\n                "border-width": 4,\n                "border-color": "__SEARCH_COLOR__",\n                "border-opacity": 1,\n                "z-index": 20,\n                "font-size": 12,\n                "font-weight": 700,\n                "text-background-color": "#ffffff",\n                "text-background-opacity": 0.9,\n                "text-background-padding": 3,\n                "text-background-shape": "roundrectangle"\n            }\n        },\n        {\n            selector: "node:selected",\n            style: {\n                "width": 22,\n                "height": 22,\n                "border-width": 4,\n                "border-color": "#155eef",\n                "border-opacity": 1,\n                "z-index": 25,\n                "font-size": 12,\n                "font-weight": 700,\n                "text-background-color": "#ffffff",\n                "text-background-opacity": 0.92,\n                "text-background-padding": 3,\n                "text-background-shape": "roundrectangle"\n            }\n        },\n        {\n            selector: "edge.hover-subtree-edge",\n            style: {\n                "line-style": "dotted",\n                "line-color": "#657084",\n                "width": 3.2,\n                "opacity": 0.9,\n                "z-index": 35\n            }\n        },\n        {\n            selector: "edge.hover-root-path-edge",\n            style: {\n                "line-style": "solid",\n                "line-color": "#111827",\n                "width": 3.2,\n                "opacity": 1,\n                "z-index": 40\n            }\n        },\n        {\n            selector: "node.hover-subtree-node",\n            style: {\n                "border-width": 2,\n                "border-style": "dotted",\n                "border-color": "#657084",\n                "border-opacity": 0.95,\n                "z-index": 34\n            }\n        },\n        {\n            selector: "node.hover-root-path-node",\n            style: {\n                "width": 18,\n                "height": 18,\n                "border-width": 3,\n                "border-style": "solid",\n                "border-color": "#111827",\n                "border-opacity": 1,\n                "z-index": 41\n            }\n        },\n        {\n            selector: "node.hover-focus-node",\n            style: {\n                "width": 26,\n                "height": 26,\n                "border-width": 5,\n                "border-style": "solid",\n                "border-color": "#111827",\n                "border-opacity": 1,\n                "font-size": 10,\n                "font-weight": 700,\n                "text-background-color": "#ffffff",\n                "text-background-opacity": 0.94,\n                "text-background-padding": 3,\n                "text-background-shape": "roundrectangle",\n                "z-index": 50\n            }\n        }\n    ]\n});\n\nconst summaryPanel = document.getElementById("summaryPanel");\nconst detailsPanel = document.getElementById("detailsPanel");\nconst statusBadge = document.getElementById("statusBadge");\nconst tooltip = document.getElementById("tooltip");\nconst searchInput = document.getElementById("searchInput");\n\nfunction formatNumber(value) {\n    return Number(value || 0).toLocaleString();\n}\n\nfunction escapeHtml(value) {\n    return String(value ?? "")\n        .replaceAll("&", "&amp;")\n        .replaceAll("<", "&lt;")\n        .replaceAll(">", "&gt;")\n        .replaceAll(\'"\', "&quot;")\n        .replaceAll("\'", "&#039;");\n}\n\nfunction statusLabel(status) {\n    if (status === "martin") return "Martin terminal node";\n    if (status === "chenchen") return "Chenchen terminal node";\n    if (status === "shared") return "Martin + Chenchen terminal node";\n    return "Other hierarchy node";\n}\n\nfunction listText(values, limit = 12) {\n    const clean = Array.isArray(values) ? values : [];\n    if (!clean.length) return "None";\n    if (clean.length <= limit) return clean.join(", ");\n    return `${clean.slice(0, limit).join(", ")} … (+${clean.length - limit} more)`;\n}\n\nfunction renderSummary() {\n    const sourceRows = summary.sourceCounts\n        .map(item => `<li>${escapeHtml(item.source)}: ${formatNumber(item.rowCount)} rows</li>`)\n        .join("");\n\n    summaryPanel.innerHTML = `\n        <div class="card">\n            <div class="card-title">Graph summary</div>\n            <div class="kpi-grid">\n                <div class="kpi">\n                    <div class="kpi-value">${formatNumber(summary.nodeCount)}</div>\n                    <div class="kpi-label">Nodes</div>\n                </div>\n                <div class="kpi">\n                    <div class="kpi-value">${formatNumber(summary.edgeCount)}</div>\n                    <div class="kpi-label">Edges</div>\n                </div>\n                <div class="kpi">\n                    <div class="kpi-value">${formatNumber(summary.rootCount)}</div>\n                    <div class="kpi-label">Roots</div>\n                </div>\n                <div class="kpi">\n                    <div class="kpi-value">${formatNumber(summary.multiParentNodeCount)}</div>\n                    <div class="kpi-label">Multi-parent nodes</div>\n                </div>\n            </div>\n        </div>\n\n        <div class="card">\n            <div class="card-title">Terminal-source nodes</div>\n            <div class="detail-grid">\n                <div class="detail-key">Martin only</div>\n                <div class="detail-value">${formatNumber(summary.martinTerminalCount)}</div>\n                <div class="detail-key">Chenchen only</div>\n                <div class="detail-value">${formatNumber(summary.chenchenTerminalCount)}</div>\n                <div class="detail-key">Both sources</div>\n                <div class="detail-value">${formatNumber(summary.sharedTerminalCount)}</div>\n                <div class="detail-key">All other nodes</div>\n                <div class="detail-value">${formatNumber(summary.otherNodeCount)}</div>\n            </div>\n        </div>\n\n        <div class="card">\n            <div class="card-title">Included CT/1 sources</div>\n            <ul class="source-list">${sourceRows}</ul>\n        </div>\n    `;\n\n    statusBadge.textContent =\n        `${summary.inputFile} • ${formatNumber(summary.rowCount)} rows • ` +\n        `${formatNumber(summary.nodeCount)} nodes • ${formatNumber(summary.edgeCount)} edges`;\n}\n\nfunction renderNodeDetails(node) {\n    const data = node.data();\n\n    detailsPanel.className = "";\n    detailsPanel.innerHTML = `\n        <div class="card">\n            <div class="card-title">Selected node</div>\n            <div class="detail-grid">\n                <div class="detail-key">Label</div>\n                <div class="detail-value"><strong>${escapeHtml(data.label)}</strong></div>\n                <div class="detail-key">Ontology ID</div>\n                <div class="detail-value">${escapeHtml(data.id)}</div>\n                <div class="detail-key">Status</div>\n                <div class="detail-value">${escapeHtml(statusLabel(data.terminalStatus))}</div>\n                <div class="detail-key">Depth</div>\n                <div class="detail-value">${formatNumber(data.depth)}</div>\n                <div class="detail-key">Parents</div>\n                <div class="detail-value">${formatNumber(data.parentCount)}</div>\n                <div class="detail-key">Children</div>\n                <div class="detail-value">${formatNumber(data.childCount)}</div>\n            </div>\n\n            <div class="path-box">\n                <strong>Primary layout path</strong><br />\n                ${escapeHtml(data.primaryPathText || data.label)}\n            </div>\n        </div>\n\n        <div class="card">\n            <div class="card-title">Hierarchy relationships</div>\n            <div class="detail-key">Parent nodes</div>\n            <div class="list-box">${escapeHtml(listText(data.parentLabels))}</div>\n            <div class="detail-key" style="margin-top:9px;">Child nodes</div>\n            <div class="list-box">${escapeHtml(listText(data.childLabels))}</div>\n        </div>\n\n        <div class="card">\n            <div class="card-title">Source provenance</div>\n            <div class="detail-key">Appears anywhere in paths from</div>\n            <div class="list-box">${escapeHtml(listText(data.sources))}</div>\n            <div class="detail-key" style="margin-top:9px;">Is terminal in rows from</div>\n            <div class="list-box">${escapeHtml(listText(data.terminalSources))}</div>\n        </div>\n\n        <div class="card">\n            <div class="card-title">Label variants</div>\n            <div class="list-box">${escapeHtml(listText(data.labelVariants))}</div>\n        </div>\n    `;\n}\n\nfunction clearSearch() {\n    cy.elements().removeClass("dimmed search-hit");\n    searchInput.value = "";\n    cy.$(":selected").unselect();\n    statusBadge.textContent =\n        `${summary.inputFile} • ${formatNumber(summary.rowCount)} rows • ` +\n        `${formatNumber(summary.nodeCount)} nodes • ${formatNumber(summary.edgeCount)} edges`;\n}\n\nfunction runSearch() {\n    const query = searchInput.value.trim().toLocaleLowerCase();\n    cy.elements().removeClass("dimmed search-hit");\n\n    if (!query) {\n        clearSearch();\n        cy.fit(cy.elements(), 72);\n        return;\n    }\n\n    const matches = cy.nodes().filter(node => {\n        const data = node.data();\n        const haystack = [\n            data.id,\n            data.label,\n            ...(data.labelVariants || []),\n            ...(data.sources || []),\n            ...(data.terminalSources || [])\n        ].join(" ").toLocaleLowerCase();\n        return haystack.includes(query);\n    });\n\n    if (!matches.length) {\n        statusBadge.textContent = `No nodes matched “${searchInput.value.trim()}”.`;\n        return;\n    }\n\n    const context = matches\n        .union(matches.predecessors())\n        .union(matches.connectedEdges())\n        .union(matches.predecessors().connectedEdges());\n\n    cy.elements().addClass("dimmed");\n    context.removeClass("dimmed");\n    matches.removeClass("dimmed").addClass("search-hit");\n    cy.fit(context, 90);\n\n    statusBadge.textContent =\n        `${formatNumber(matches.length)} matching node${matches.length === 1 ? "" : "s"} ` +\n        `for “${searchInput.value.trim()}”.`;\n}\n\ncy.on("tap", "node", event => {\n    renderNodeDetails(event.target);\n});\n\ncy.on("tap", event => {\n    if (event.target === cy) {\n        cy.$(":selected").unselect();\n        detailsPanel.className = "empty-state";\n        detailsPanel.textContent = "Select a node to inspect its details.";\n    }\n});\n\nconst HOVER_CLASSES = [\n    "hover-root-path-node",\n    "hover-root-path-edge",\n    "hover-subtree-node",\n    "hover-subtree-edge",\n    "hover-focus-node"\n];\n\nfunction clearHoverTrace() {\n    for (const className of HOVER_CLASSES) {\n        cy.elements(`.${className}`).removeClass(className);\n    }\n}\n\nfunction tracePrimaryRootPath(node) {\n    const pathIds = node.data("primaryPathIds") || [];\n\n    for (const nodeId of pathIds) {\n        const pathNode = cy.getElementById(nodeId);\n        if (pathNode.nonempty()) {\n            pathNode.addClass("hover-root-path-node");\n        }\n    }\n\n    for (let index = 0; index < pathIds.length - 1; index += 1) {\n        const sourceId = pathIds[index];\n        const targetId = pathIds[index + 1];\n\n        cy.edges().filter(edge => (\n            edge.data("source") === sourceId &&\n            edge.data("target") === targetId\n        )).addClass("hover-root-path-edge");\n    }\n}\n\nfunction traceDescendantSubtrees(node) {\n    // successors() follows every directed outgoing edge, so this includes\n    // all primary and additional-parent descendant branches below the node.\n    const successors = node.successors();\n    successors.nodes().addClass("hover-subtree-node");\n    successors.edges().addClass("hover-subtree-edge");\n}\n\ncy.on("mouseover", "node", event => {\n    const node = event.target;\n    const data = node.data();\n\n    clearHoverTrace();\n    traceDescendantSubtrees(node);\n    tracePrimaryRootPath(node);\n    node.addClass("hover-focus-node");\n\n    const descendantNodeCount = node.successors("node").length;\n    const descendantEdgeCount = node.successors("edge").length;\n\n    tooltip.innerHTML = `\n        <div class="tooltip-title">${escapeHtml(data.label)}</div>\n        <div>${escapeHtml(data.id)}</div>\n        <div class="tooltip-muted">${escapeHtml(statusLabel(data.terminalStatus))}</div>\n        <div class="tooltip-muted">Root path: ${formatNumber((data.primaryPathIds || []).length)} nodes</div>\n        <div class="tooltip-muted">Descendants: ${formatNumber(descendantNodeCount)} nodes • ${formatNumber(descendantEdgeCount)} edges</div>\n    `;\n    tooltip.style.display = "block";\n});\n\ncy.on("mousemove", "node", event => {\n    const original = event.originalEvent;\n    if (!original) return;\n    tooltip.style.left = `${original.clientX + 14}px`;\n    tooltip.style.top = `${original.clientY + 14}px`;\n});\n\ncy.on("mouseout", "node", () => {\n    clearHoverTrace();\n    tooltip.style.display = "none";\n});\n\ndocument.getElementById("fitButton").addEventListener("click", () => {\n    cy.fit(cy.elements(":visible"), 72);\n});\n\ndocument.getElementById("labelsButton").addEventListener("click", event => {\n    const button = event.currentTarget;\n    const labelsVisible = button.classList.toggle("active");\n    cy.style()\n        .selector("node")\n        .style("label", labelsVisible ? "data(label)" : "")\n        .update();\n});\n\ndocument.getElementById("clearButton").addEventListener("click", () => {\n    clearSearch();\n    cy.fit(cy.elements(), 72);\n});\n\ndocument.getElementById("searchButton").addEventListener("click", runSearch);\nsearchInput.addEventListener("keydown", event => {\n    if (event.key === "Enter") runSearch();\n    if (event.key === "Escape") {\n        clearSearch();\n        cy.fit(cy.elements(), 72);\n    }\n});\n\ndocument.getElementById("pngButton").addEventListener("click", () => {\n    const dataUrl = cy.png({\n        full: true,\n        scale: 2,\n        bg: "#ffffff"\n    });\n\n    const link = document.createElement("a");\n    link.href = dataUrl;\n    link.download = "reference-supertree-v9.png";\n    document.body.appendChild(link);\n    link.click();\n    link.remove();\n});\n\nrenderSummary();\n</script>\n</body>\n</html>\n\'\'\'\n\n    replacements = {\n        "__TITLE__": html.escape(title),\n        "__CYTOSCAPE_SCRIPT__": cytoscape_script_tag(local_cytoscape_js),\n        "__GRAPH_JSON__": graph_json,\n        "__MARTIN_COLOR__": COLORS["martin"],\n        "__CHENCHEN_COLOR__": COLORS["chenchen"],\n        "__NEUTRAL_COLOR__": COLORS["neutral"],\n        "__SEARCH_COLOR__": COLORS["search"],\n    }\n\n    for marker, value in replacements.items():\n        template = template.replace(marker, value)\n\n    return template\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(\n        description=(\n            "Build an interactive Cytoscape reference supertree from the "\n            "CTann v9 hierarchy CSV/TSV."\n        )\n    )\n    parser.add_argument(\n        "--input",\n        type=Path,\n        default=DEFAULT_INPUT,\n        help="Input CTann hierarchy file. Default: data/ctann-v9.csv",\n    )\n    parser.add_argument(\n        "--output",\n        type=Path,\n        default=DEFAULT_OUTPUT,\n        help=(\n            "Output HTML file. Default: "\n            "output_htmls/reference-supertree-v9.html"\n        ),\n    )\n    parser.add_argument(\n        "--title",\n        default="Reference Cell Ontology Supertree — CTann v9",\n        help="Title displayed in the generated HTML.",\n    )\n    parser.add_argument(\n        "--cytoscape-js",\n        type=Path,\n        default=None,\n        help=(\n            "Optional local cytoscape.min.js file for a fully offline HTML. "\n            "Without it, the HTML loads Cytoscape.js from jsDelivr."\n        ),\n    )\n    return parser.parse_args()\n\n\ndef main() -> None:\n    args = parse_args()\n\n    print(f"Reference supertree builder v{BUILD_VERSION}")\n    print(f"Input:  {args.input.resolve()}")\n    print(f"Output: {args.output.resolve()}")\n\n    if not args.input.exists():\n        raise FileNotFoundError(f"Input file not found: {args.input}")\n\n    payload = read_supertree(args.input)\n    output_html = render_html(\n        payload=payload,\n        title=args.title,\n        local_cytoscape_js=args.cytoscape_js,\n    )\n\n    args.output.parent.mkdir(parents=True, exist_ok=True)\n    args.output.write_text(output_html, encoding="utf-8")\n\n    summary = payload["summary"]\n    print(f"Saved: {args.output.resolve()}")\n    print(\n        "Reference supertree: "\n        f"{summary[\'nodeCount\']} nodes, "\n        f"{summary[\'edgeCount\']} edges, "\n        f"{summary[\'rootCount\']} roots"\n    )\n    print(\n        "Terminal source nodes: "\n        f"Martin only={summary[\'martinTerminalCount\']}, "\n        f"Chenchen only={summary[\'chenchenTerminalCount\']}, "\n        f"shared={summary[\'sharedTerminalCount\']}"\n    )\n\n\nif __name__ == "__main__":\n    main()'

POPULATION_BUILDER_SOURCE = '"""Build Task 2: HRApop v1.1 lung Azimuth vs Pan-human Azimuth.\n\nThe generated HTML overlays direct Cell Ontology outputs on the v9 reference\nsupertree:\n- red: organ-specific Azimuth only\n- blue: Pan-human Azimuth only\n- purple: exact Cell Ontology ID in both\n- gray: not directly output by either\n\nHovering a node draws its primary path to a root as a solid line and all\navailable descendant branches as equally thick dotted lines. Clicking a node\nopens hierarchy and provenance details. The comparison drawer reports exact\nnode and inclusive node-plus-descendants population values by anatomical\nstructure and sex.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport html\nimport json\nimport re\nfrom collections import Counter, defaultdict, deque\nfrom pathlib import Path\nfrom typing import Any\n\nROOT_ID = "CL:0000000"\nMAX_PATH_LEVEL = 12\nCOLUMN_DX = 292.5\nROW_DY = 8.5\nLEAF_STEP = 3.0\nROOT_GAP = 2.0\n\nSCRIPT_DIR = Path(__file__).resolve().parent\nDEFAULT_SUPERTREE = SCRIPT_DIR / "data" / "ctann-v9.csv"\nDEFAULT_HRAPOP = (\n    SCRIPT_DIR\n    / "data"\n    / "cell-types-in-anatomical-structurescts-per-as.csv"\n)\nDEFAULT_OUTPUT = (\n    SCRIPT_DIR\n    / "output_htmls"\n    / "hrapop-v1.1-lung-azimuth-pan-human-comparison.html"\n)\n\nCOLORS = {\n    "neutral": "#8A8F98",\n    "lung_only": "#E53935",\n    "pan_only": "#1565C0",\n    "shared": "#7B1FA2",\n}\n\n\ndef normalize_ontology_id(value: str | None) -> str:\n    """Normalize common OBO URI, underscore, and CURIE identifiers."""\n    raw = (value or "").strip()\n    if not raw:\n        return ""\n\n    for prefix in (\n        "https://purl.obolibrary.org/obo/",\n        "http://purl.obolibrary.org/obo/",\n    ):\n        if raw.startswith(prefix):\n            raw = raw[len(prefix) :]\n            break\n\n    match = re.fullmatch(\n        r"([A-Za-z][A-Za-z0-9-]*)[_:]([A-Za-z0-9_.-]+)",\n        raw,\n    )\n    if match:\n        return f"{match.group(1).upper()}:{match.group(2)}"\n\n    return raw\n\n\ndef detect_delimiter(path: Path) -> str:\n    if path.suffix.lower() in {".tsv", ".tab"}:\n        return "\\t"\n\n    with path.open("r", encoding="utf-8-sig", newline="") as handle:\n        sample = handle.read(65536)\n\n    try:\n        return csv.Sniffer().sniff(sample, delimiters=",\\t;").delimiter\n    except csv.Error:\n        return ","\n\n\ndef read_supertree(path: Path) -> dict[str, Any]:\n    delimiter = detect_delimiter(path)\n\n    with path.open(newline="", encoding="utf-8-sig") as handle:\n        reader = csv.DictReader(handle, delimiter=delimiter)\n        fieldnames = set(reader.fieldnames or [])\n        required = {"AS/1/ID", "AS/1/LABEL"}\n        missing = required - fieldnames\n        if missing:\n            raise ValueError(\n                f"Missing required supertree columns in {path}: "\n                f"{sorted(missing)}"\n            )\n        rows = list(reader)\n\n    labels: dict[str, str] = {}\n    label_variants: dict[str, set[str]] = defaultdict(set)\n    node_sources: dict[str, set[str]] = defaultdict(set)\n    terminal_sources: dict[str, set[str]] = defaultdict(set)\n    parents: dict[str, set[str]] = defaultdict(set)\n    children: dict[str, set[str]] = defaultdict(set)\n    edge_counts: Counter[tuple[str, str]] = Counter()\n\n    valid_rows = 0\n    empty_rows = 0\n\n    for row in rows:\n        source = (row.get("CT/1 - Sources") or "").strip() or "(blank)"\n        path_nodes: list[tuple[str, str]] = []\n\n        for level in range(1, MAX_PATH_LEVEL + 1):\n            node_id = normalize_ontology_id(row.get(f"AS/{level}/ID"))\n            node_label = (row.get(f"AS/{level}/LABEL") or "").strip()\n            if node_id:\n                path_nodes.append((node_id, node_label or node_id))\n\n        if not path_nodes:\n            empty_rows += 1\n            continue\n\n        valid_rows += 1\n        terminal_sources[path_nodes[-1][0]].add(source)\n\n        previous: str | None = None\n        for node_id, node_label in path_nodes:\n            labels[node_id] = node_label\n            label_variants[node_id].add(node_label)\n            node_sources[node_id].add(source)\n\n            if previous and previous != node_id:\n                parents[node_id].add(previous)\n                children[previous].add(node_id)\n                edge_counts[(previous, node_id)] += 1\n            previous = node_id\n\n    all_nodes = set(labels)\n    if not all_nodes:\n        raise ValueError(f"No hierarchy nodes were found in {path}.")\n\n    roots = sorted(\n        [node for node in all_nodes if not parents.get(node)],\n        key=lambda node: (labels.get(node, ""), node),\n    )\n    if not roots:\n        roots = [min(all_nodes)]\n\n    depth: dict[str, int] = {}\n    queue: deque[str] = deque()\n    for root in roots:\n        depth[root] = 0\n        queue.append(root)\n\n    while queue:\n        node = queue.popleft()\n        ordered = sorted(\n            children.get(node, set()),\n            key=lambda child: (\n                -edge_counts[(node, child)],\n                labels.get(child, ""),\n                child,\n            ),\n        )\n        for child in ordered:\n            candidate = depth[node] + 1\n            if child not in depth or candidate < depth[child]:\n                depth[child] = candidate\n                queue.append(child)\n\n    for node in all_nodes:\n        depth.setdefault(node, 0)\n\n    # A single primary parent is used only for stable layout and the solid\n    # root path. Every original parent-child edge remains in the graph.\n    primary_parent: dict[str, str] = {}\n    for node in all_nodes:\n        node_parents = parents.get(node, set())\n        if not node_parents:\n            continue\n        primary_parent[node] = sorted(\n            node_parents,\n            key=lambda parent: (\n                -edge_counts[(parent, node)],\n                depth.get(parent, 999),\n                labels.get(parent, ""),\n                parent,\n            ),\n        )[0]\n\n    primary_children: dict[str, list[str]] = defaultdict(list)\n    for child, parent in primary_parent.items():\n        primary_children[parent].append(child)\n\n    for parent in primary_children:\n        primary_children[parent].sort(\n            key=lambda child: (\n                depth.get(child, 999),\n                -len(children.get(child, set())),\n                labels.get(child, ""),\n                child,\n            )\n        )\n\n    y_position: dict[str, float] = {}\n    cursor = 0.0\n    active: set[str] = set()\n\n    def assign_y(node: str) -> None:\n        nonlocal cursor\n        if node in y_position:\n            return\n        if node in active:\n            raise ValueError(\n                f"Cycle encountered in primary-parent layout at {node}."\n            )\n\n        active.add(node)\n        child_list = primary_children.get(node, [])\n        if not child_list:\n            y_position[node] = cursor\n            cursor += LEAF_STEP\n        else:\n            for child in child_list:\n                assign_y(child)\n            y_position[node] = sum(\n                y_position[child] for child in child_list\n            ) / len(child_list)\n        active.remove(node)\n\n    for index, root in enumerate(roots):\n        assign_y(root)\n        if index < len(roots) - 1:\n            cursor += ROOT_GAP\n\n    for node in sorted(\n        all_nodes,\n        key=lambda value: (\n            depth.get(value, 999),\n            labels.get(value, ""),\n            value,\n        ),\n    ):\n        if node not in y_position:\n            y_position[node] = cursor\n            cursor += LEAF_STEP\n\n    def primary_path(node_id: str) -> list[str]:\n        result = [node_id]\n        seen = {node_id}\n        current = node_id\n        while current in primary_parent:\n            current = primary_parent[current]\n            if current in seen:\n                break\n            seen.add(current)\n            result.append(current)\n        result.reverse()\n        return result\n\n    ordered_children = {\n        node: sorted(\n            children.get(node, set()),\n            key=lambda child: (labels.get(child, ""), child),\n        )\n        for node in all_nodes\n    }\n\n    return {\n        "labels": labels,\n        "label_variants": label_variants,\n        "node_sources": node_sources,\n        "terminal_sources": terminal_sources,\n        "parents": parents,\n        "children": ordered_children,\n        "edge_counts": edge_counts,\n        "depth": depth,\n        "primary_parent": primary_parent,\n        "primary_path": primary_path,\n        "y_position": y_position,\n        "roots": roots,\n        "nodes": all_nodes,\n        "row_count": len(rows),\n        "valid_row_count": valid_rows,\n        "empty_row_count": empty_rows,\n    }\n\n\ndef parse_float(value: str | None, field: str) -> float:\n    raw = (value or "").strip()\n    if not raw:\n        return 0.0\n    try:\n        return float(raw)\n    except ValueError as exc:\n        raise ValueError(f"Invalid numeric value for {field}: {value!r}") from exc\n\n\ndef read_hrapop(\n    path: Path,\n    organ: str,\n    lung_tool: str,\n    pan_tool: str,\n    modality: str,\n) -> dict[str, Any]:\n    with path.open(newline="", encoding="utf-8-sig") as handle:\n        reader = csv.DictReader(handle)\n        required = {\n            "organ",\n            "as",\n            "as_label",\n            "sex",\n            "tool",\n            "modality",\n            "cell_id",\n            "cell_label",\n            "cell_count",\n            "cell_percentage",\n            "dataset_count",\n        }\n        missing = required - set(reader.fieldnames or [])\n        if missing:\n            raise ValueError(\n                f"Missing required HRApop columns in {path}: {sorted(missing)}"\n            )\n        rows = list(reader)\n\n    organ_key = organ.strip().casefold()\n    lung_tool_key = lung_tool.strip().casefold()\n    pan_tool_key = pan_tool.strip().casefold()\n    modality_key = modality.strip().casefold()\n\n    metadata: dict[str, dict[str, dict[str, Any]]] = {\n        "lung": defaultdict(\n            lambda: {\n                "labels": set(),\n                "sexes": set(),\n                "as_labels": set(),\n                "dataset_counts": set(),\n            }\n        ),\n        "pan": defaultdict(\n            lambda: {\n                "labels": set(),\n                "sexes": set(),\n                "as_labels": set(),\n                "dataset_counts": set(),\n            }\n        ),\n    }\n    groups: dict[str, dict[tuple[str, str], dict[str, Any]]] = {\n        "lung": {},\n        "pan": {},\n    }\n\n    filtered_row_count = 0\n    blank_id_row_count = 0\n\n    for row in rows:\n        row_organ = (row.get("organ") or "").strip().casefold()\n        row_modality = (row.get("modality") or "").strip().casefold()\n        row_tool = (row.get("tool") or "").strip().casefold()\n\n        if row_organ != organ_key or row_modality != modality_key:\n            continue\n        if row_tool not in {lung_tool_key, pan_tool_key}:\n            continue\n\n        filtered_row_count += 1\n        side = "lung" if row_tool == lung_tool_key else "pan"\n\n        as_id = (row.get("as") or "").strip()\n        as_label = (row.get("as_label") or "").strip()\n        sex = (row.get("sex") or "").strip() or "Unknown"\n        as_key = as_id or f"LABEL::{as_label.casefold()}"\n        group_key = (as_key, sex)\n\n        group = groups[side].setdefault(\n            group_key,\n            {\n                "asId": as_id,\n                "asLabels": set(),\n                "sex": sex,\n                "totalCount": 0.0,\n                "sourcePercentageTotal": 0.0,\n                "byCell": {},\n            },\n        )\n        if as_label:\n            group["asLabels"].add(as_label)\n\n        count = parse_float(row.get("cell_count"), "cell_count")\n        percentage = parse_float(\n            row.get("cell_percentage"), "cell_percentage"\n        )\n        group["totalCount"] += count\n        group["sourcePercentageTotal"] += percentage\n\n        cell_id = normalize_ontology_id(row.get("cell_id"))\n        if not cell_id:\n            blank_id_row_count += 1\n            continue\n\n        cell_label = (row.get("cell_label") or "").strip()\n        dataset_count = (row.get("dataset_count") or "").strip()\n\n        item = metadata[side][cell_id]\n        if cell_label:\n            item["labels"].add(cell_label)\n        if as_label:\n            item["as_labels"].add(as_label)\n        if dataset_count:\n            item["dataset_counts"].add(dataset_count)\n        item["sexes"].add(sex)\n\n        cell = group["byCell"].setdefault(\n            cell_id,\n            {"count": 0.0, "percentage": 0.0, "labels": set()},\n        )\n        cell["count"] += count\n        cell["percentage"] += percentage\n        if cell_label:\n            cell["labels"].add(cell_label)\n\n    if filtered_row_count == 0:\n        raise ValueError(\n            f"No HRApop rows matched organ={organ!r}, modality={modality!r}, "\n            f"and tools {lung_tool!r}/{pan_tool!r}."\n        )\n\n    return {\n        "filtered_row_count": filtered_row_count,\n        "blank_id_row_count": blank_id_row_count,\n        "metadata": metadata,\n        "groups": groups,\n        "lung_ids": set(metadata["lung"]),\n        "pan_ids": set(metadata["pan"]),\n    }\n\n\ndef sorted_values(values: set[str]) -> list[str]:\n    return sorted(values, key=lambda value: value.casefold())\n\n\ndef materialize_metadata(item: dict[str, Any] | None) -> dict[str, Any]:\n    if not item:\n        return {\n            "labels": [],\n            "sexes": [],\n            "asLabels": [],\n            "datasetCounts": [],\n        }\n    return {\n        "labels": sorted_values(item["labels"]),\n        "sexes": sorted_values(item["sexes"]),\n        "asLabels": sorted_values(item["as_labels"]),\n        "datasetCounts": sorted_values(item["dataset_counts"]),\n    }\n\n\ndef build_graph_payload(\n    tree: dict[str, Any],\n    hra: dict[str, Any],\n    validation_tolerance: float = 1e-9,\n) -> dict[str, Any]:\n    labels: dict[str, str] = tree["labels"]\n    parents: dict[str, set[str]] = tree["parents"]\n    children: dict[str, list[str]] = tree["children"]\n    depth: dict[str, int] = tree["depth"]\n    y_position: dict[str, float] = tree["y_position"]\n    primary_parent: dict[str, str] = tree["primary_parent"]\n    primary_path = tree["primary_path"]\n    all_nodes: set[str] = tree["nodes"]\n\n    lung_ids: set[str] = hra["lung_ids"]\n    pan_ids: set[str] = hra["pan_ids"]\n    union_ids = lung_ids | pan_ids\n\n    subtree_node_ids: dict[str, set[str]] = {}\n    visiting: set[str] = set()\n\n    def collect_subtree(node: str) -> set[str]:\n        if node in subtree_node_ids:\n            return subtree_node_ids[node]\n        if node in visiting:\n            raise ValueError(f"Cycle encountered in hierarchy at {node}.")\n        visiting.add(node)\n        values = {node}\n        for child in children.get(node, []):\n            values.update(collect_subtree(child))\n        visiting.remove(node)\n        subtree_node_ids[node] = values\n        return values\n\n    for node in all_nodes:\n        collect_subtree(node)\n\n    def group_identity(group_key: tuple[str, str]) -> tuple[str, str]:\n        groups_found = [\n            hra["groups"][side][group_key]\n            for side in ("lung", "pan")\n            if group_key in hra["groups"][side]\n        ]\n        as_ids = [group["asId"] for group in groups_found if group["asId"]]\n        label_values: set[str] = set()\n        for group in groups_found:\n            label_values.update(group["asLabels"])\n        as_id = as_ids[0] if as_ids else ""\n        as_label = (\n            sorted_values(label_values)[0]\n            if label_values\n            else (as_id or group_key[0])\n        )\n        return as_id, as_label\n\n    all_group_keys = sorted(\n        set(hra["groups"]["lung"]) | set(hra["groups"]["pan"]),\n        key=lambda key: (\n            group_identity(key)[1].casefold(),\n            key[1].casefold(),\n            group_identity(key)[0] or key[0],\n        ),\n    )\n\n    validation = {\n        "groupCaseCount": 0,\n        "exactCaseCount": 0,\n        "subtreeCaseCount": 0,\n        "maxGroupPercentageDifference": 0.0,\n        "maxExactDifference": 0.0,\n        "maxSubtreeDifference": 0.0,\n    }\n\n    for side in ("lung", "pan"):\n        for group in hra["groups"][side].values():\n            total_count = group["totalCount"]\n            group_diff = abs(group["sourcePercentageTotal"] - 1.0)\n            validation["groupCaseCount"] += 1\n            validation["maxGroupPercentageDifference"] = max(\n                validation["maxGroupPercentageDifference"], group_diff\n            )\n            if group_diff > validation_tolerance:\n                raise ValueError(\n                    "cell_percentage values do not sum to 1 for "\n                    f"{side} / {sorted_values(group[\'asLabels\'])[0] if group[\'asLabels\'] else group[\'asId\']} / "\n                    f"{group[\'sex\']}: difference={group_diff:.3g}"\n                )\n\n            for cell_id, cell in group["byCell"].items():\n                derived = cell["count"] / total_count if total_count > 0 else 0.0\n                diff = abs(cell["percentage"] - derived)\n                validation["exactCaseCount"] += 1\n                validation["maxExactDifference"] = max(\n                    validation["maxExactDifference"], diff\n                )\n                if diff > validation_tolerance:\n                    raise ValueError(\n                        "Exact percentage validation failed for "\n                        f"{cell_id} / {side} / {group[\'sex\']}: "\n                        f"difference={diff:.3g}"\n                    )\n\n    def values_for_side(\n        side: str,\n        group_key: tuple[str, str],\n        included_ids: set[str],\n        exact: bool,\n    ) -> dict[str, Any]:\n        group = hra["groups"][side].get(group_key)\n        if group is None:\n            return {"available": False, "count": None, "percentage": None}\n\n        count = 0.0\n        source_percentage = 0.0\n        for cell_id in included_ids:\n            cell = group["byCell"].get(cell_id)\n            if cell is None:\n                continue\n            count += cell["count"]\n            source_percentage += cell["percentage"]\n\n        if exact:\n            percentage = source_percentage\n        else:\n            percentage = count / group["totalCount"] if group["totalCount"] > 0 else 0.0\n            diff = abs(source_percentage - percentage)\n            validation["subtreeCaseCount"] += 1\n            validation["maxSubtreeDifference"] = max(\n                validation["maxSubtreeDifference"], diff\n            )\n            if diff > validation_tolerance:\n                raise ValueError(\n                    "Subtree percentage validation failed for "\n                    f"{side} / {group[\'sex\']}: difference={diff:.3g}"\n                )\n\n        return {"available": True, "count": count, "percentage": percentage}\n\n    def comparison_rows(\n        included_ids: set[str], exact: bool\n    ) -> list[dict[str, Any]]:\n        output: list[dict[str, Any]] = []\n        for group_key in all_group_keys:\n            _, sex = group_key\n            as_id, as_label = group_identity(group_key)\n            lung = values_for_side("lung", group_key, included_ids, exact)\n            pan = values_for_side("pan", group_key, included_ids, exact)\n            both = lung["available"] and pan["available"]\n            output.append(\n                {\n                    "asId": as_id,\n                    "asLabel": as_label,\n                    "sex": sex,\n                    "lungAvailable": lung["available"],\n                    "panAvailable": pan["available"],\n                    "lungCount": lung["count"],\n                    "panCount": pan["count"],\n                    "absCountDifference": (\n                        abs(lung["count"] - pan["count"]) if both else None\n                    ),\n                    "lungPercentage": lung["percentage"],\n                    "panPercentage": pan["percentage"],\n                    "absPercentageDifference": (\n                        abs(lung["percentage"] - pan["percentage"])\n                        if both\n                        else None\n                    ),\n                }\n            )\n        return output\n\n    edge_pairs = sorted(\n        tree["edge_counts"],\n        key=lambda pair: (\n            depth.get(pair[0], 999),\n            labels.get(pair[0], ""),\n            labels.get(pair[1], ""),\n            pair,\n        ),\n    )\n    edge_id_by_pair: dict[tuple[str, str], str] = {}\n    edges: list[dict[str, Any]] = []\n    for index, (parent, child) in enumerate(edge_pairs):\n        edge_id = f"edge-{index}"\n        edge_id_by_pair[(parent, child)] = edge_id\n        edges.append(\n            {\n                "data": {\n                    "id": edge_id,\n                    "source": parent,\n                    "target": child,\n                    "rowCount": tree["edge_counts"][(parent, child)],\n                    "isPrimary": primary_parent.get(child) == parent,\n                }\n            }\n        )\n\n    nodes: list[dict[str, Any]] = []\n    comparisons: dict[str, dict[str, list[dict[str, Any]]]] = {}\n\n    for node_id in sorted(\n        all_nodes,\n        key=lambda value: (\n            depth.get(value, 999), labels.get(value, ""), value\n        ),\n    ):\n        in_lung = node_id in lung_ids\n        in_pan = node_id in pan_ids\n        if in_lung and in_pan:\n            status = "shared"\n        elif in_lung:\n            status = "lung_only"\n        elif in_pan:\n            status = "pan_only"\n        else:\n            status = "neutral"\n\n        path_ids = primary_path(node_id)\n        path_labels = [labels.get(value, value) for value in path_ids]\n        path_edge_ids = [\n            edge_id_by_pair[(source, target)]\n            for source, target in zip(path_ids, path_ids[1:])\n            if (source, target) in edge_id_by_pair\n        ]\n\n        node_subtree = subtree_node_ids[node_id]\n        lung_subtree = node_subtree & lung_ids\n        pan_subtree = node_subtree & pan_ids\n        is_leaf = len(children.get(node_id, [])) == 0\n\n        comparisons[node_id] = {\n            "exactRows": comparison_rows({node_id}, exact=True),\n            "subtreeRows": (\n                [] if is_leaf else comparison_rows(node_subtree, exact=False)\n            ),\n        }\n\n        parent_ids = sorted(\n            parents.get(node_id, set()),\n            key=lambda value: (labels.get(value, ""), value),\n        )\n        child_ids = children.get(node_id, [])\n\n        nodes.append(\n            {\n                "data": {\n                    "id": node_id,\n                    "label": labels.get(node_id, node_id),\n                    "displayLabel": labels.get(node_id, node_id),\n                    "status": status,\n                    "fillColor": COLORS[status],\n                    "isCompared": status != "neutral",\n                    "inLung": in_lung,\n                    "inPan": in_pan,\n                    "depth": depth.get(node_id, 0),\n                    "parentId": primary_parent.get(node_id, ""),\n                    "parentLabel": labels.get(primary_parent.get(node_id, ""), ""),\n                    "parentIds": parent_ids,\n                    "parentLabels": [labels.get(value, value) for value in parent_ids],\n                    "childIds": child_ids,\n                    "childCount": len(child_ids),\n                    "isLeaf": is_leaf,\n                    "descendantCount": len(node_subtree) - 1,\n                    "pathIds": path_ids,\n                    "pathEdgeIds": path_edge_ids,\n                    "pathText": " → ".join(path_labels),\n                    "sources": sorted_values(tree["node_sources"].get(node_id, set())),\n                    "terminalSources": sorted_values(tree["terminal_sources"].get(node_id, set())),\n                    "lungMeta": materialize_metadata(hra["metadata"]["lung"].get(node_id)),\n                    "panMeta": materialize_metadata(hra["metadata"]["pan"].get(node_id)),\n                    "subtreeLungCount": len(lung_subtree),\n                    "subtreePanCount": len(pan_subtree),\n                    "subtreeSharedCount": len(lung_subtree & pan_subtree),\n                    "subtreeDifferenceCount": len(lung_subtree ^ pan_subtree),\n                },\n                "position": {\n                    "x": depth.get(node_id, 0) * COLUMN_DX,\n                    "y": y_position[node_id] * ROW_DY,\n                },\n            }\n        )\n\n    unmapped: list[dict[str, Any]] = []\n    for cell_id in sorted(union_ids - all_nodes):\n        in_lung = cell_id in lung_ids\n        in_pan = cell_id in pan_ids\n        if in_lung and in_pan:\n            tool_status = "Azimuth and Pan-human Azimuth"\n        elif in_lung:\n            tool_status = "Azimuth only"\n        else:\n            tool_status = "Pan-human Azimuth only"\n        labels_found = sorted(\n            set(materialize_metadata(hra["metadata"]["lung"].get(cell_id))["labels"])\n            | set(materialize_metadata(hra["metadata"]["pan"].get(cell_id))["labels"]),\n            key=str.casefold,\n        )\n        unmapped.append(\n            {"id": cell_id, "labels": labels_found, "toolStatus": tool_status}\n        )\n\n    summary = {\n        "treeNodeCount": len(all_nodes),\n        "treeEdgeCount": len(edges),\n        "rootCount": len(tree["roots"]),\n        "multiParentNodeCount": sum(\n            1 for node in all_nodes if len(parents.get(node, set())) > 1\n        ),\n        "filteredRowCount": hra["filtered_row_count"],\n        "blankIdRowCount": hra["blank_id_row_count"],\n        "lungCount": len(lung_ids),\n        "panCount": len(pan_ids),\n        "sharedCount": len(lung_ids & pan_ids),\n        "lungOnlyCount": len(lung_ids - pan_ids),\n        "panOnlyCount": len(pan_ids - lung_ids),\n        "mappedComparisonCount": len(union_ids & all_nodes),\n        "unmappedComparisonCount": len(union_ids - all_nodes),\n        "validation": validation,\n    }\n\n    return {\n        "nodes": nodes,\n        "edges": edges,\n        "comparisons": comparisons,\n        "unmapped": unmapped,\n        "summary": summary,\n    }\n\n\ndef display_tool_name(value: str) -> str:\n    normalized = value.strip().casefold().replace("_", "-")\n    if normalized == "azimuth":\n        return "Azimuth"\n    if normalized == "pan-human-azimuth":\n        return "Pan-human Azimuth"\n    return " ".join(part.capitalize() for part in normalized.split("-"))\n\n\nHTML_TEMPLATE = r\'\'\'<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1" />\n<title>HRApop __ORGAN_TITLE__ Population View — Azimuth Comparison</title>\n<style>\n:root {\n    --bg: #eef2f7;\n    --panel: #ffffff;\n    --border: #d7dde7;\n    --text: #18212f;\n    --muted: #647084;\n    --accent: #155eef;\n    --red: #E53935;\n    --blue: #1565C0;\n    --purple: #7B1FA2;\n    --gray: #8A8F98;\n    --details-width: 390px;\n    --toolbar-height: 76px;\n}\n* { box-sizing: border-box; }\nhtml, body { height: 100%; margin: 0; overflow: hidden; }\nbody {\n    font-family: Inter, ui-sans-serif, system-ui, -apple-system,\n        BlinkMacSystemFont, "Segoe UI", sans-serif;\n    color: var(--text);\n    background: var(--bg);\n}\nbutton, input, select { font: inherit; }\n#app {\n    height: 100%;\n    display: grid;\n    grid-template-rows: var(--toolbar-height) 1fr;\n}\nheader {\n    height: var(--toolbar-height);\n    display: flex;\n    align-items: center;\n    gap: 13px;\n    padding: 10px 16px;\n    background: var(--panel);\n    border-bottom: 1px solid var(--border);\n    z-index: 10;\n}\n.brand { min-width: 275px; }\n.brand h1 { margin: 0 0 3px; font-size: 18px; line-height: 1.2; }\n.brand p { margin: 0; color: var(--muted); font-size: 12px; }\n.search-wrap { flex: 1; max-width: 520px; position: relative; }\n#search {\n    width: 100%; height: 40px; padding: 0 42px 0 13px;\n    border: 1px solid var(--border); border-radius: 10px;\n    outline: none; background: #fbfcfe;\n}\n#search:focus {\n    border-color: #8ca9fb;\n    box-shadow: 0 0 0 3px rgba(21, 94, 239, 0.12);\n}\n#searchButton {\n    position: absolute; top: 4px; right: 4px; width: 34px; height: 32px;\n    border: 0; border-radius: 8px; background: transparent; cursor: pointer;\n}\n.controls { display: flex; align-items: center; gap: 7px; margin-left: auto; }\n.control {\n    height: 38px; border: 1px solid var(--border); border-radius: 9px;\n    background: #fff; color: #253246; cursor: pointer; padding: 0 10px;\n}\n.control:hover { background: #f4f7fb; }\n.control.active { color: #1049b8; border-color: #a6baf2; background: #edf2ff; }\nmain {\n    min-height: 0;\n    display: grid;\n    grid-template-columns: 1fr var(--details-width);\n}\n#graphWrap {\n    position: relative; overflow: hidden; min-width: 0;\n    background: radial-gradient(circle at 40% 35%, #fff 0, #f7f9fc 44%, #edf1f6 100%);\n}\n#cy { position: absolute; inset: 0; }\n#details {\n    background: var(--panel); border-left: 1px solid var(--border);\n    padding: 18px; overflow: auto;\n}\n#details h2 { font-size: 18px; margin: 0 0 4px; overflow-wrap: anywhere; }\n.node-id {\n    font: 12px ui-monospace, SFMono-Regular, Menlo, monospace;\n    color: var(--muted); margin-bottom: 14px; overflow-wrap: anywhere;\n}\n.placeholder { color: var(--muted); font-size: 14px; line-height: 1.55; }\n.section { border-top: 1px solid #edf0f4; padding: 11px 0; }\n.section:first-of-type { border-top: 0; }\n.section-title {\n    text-transform: uppercase; letter-spacing: 0.055em; font-size: 11px;\n    font-weight: 750; color: var(--muted); margin-bottom: 6px;\n}\n.section-value { font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }\n.pill {\n    display: inline-flex; border: 1px solid #dce3ed; border-radius: 999px;\n    background: #f8fafc; padding: 4px 8px; margin: 3px 4px 0 0; font-size: 12px;\n}\n.status-pill { color: #fff; border: 0; font-weight: 700; }\n.tool-row {\n    display: grid; grid-template-columns: 1fr auto; gap: 8px;\n    padding: 7px 0; border-bottom: 1px solid #f0f2f5; font-size: 13px;\n}\n.tool-row:last-child { border-bottom: 0; }\n.tool-name { font-weight: 720; }\n.direct-yes { color: #11734b; font-weight: 750; }\n.direct-no { color: var(--muted); font-weight: 650; }\n.open-comparison {\n    width: 100%; min-height: 42px; border: 0; border-radius: 9px;\n    background: var(--accent); color: white; font-weight: 760; cursor: pointer;\n    padding: 10px 14px;\n}\n.open-comparison:hover { background: #0d4ed1; }\n.summary {\n    position: absolute; top: 13px; left: 14px; z-index: 4; max-width: 500px;\n    background: rgba(255,255,255,.95); border: 1px solid var(--border);\n    border-radius: 10px; padding: 8px 10px;\n    box-shadow: 0 3px 14px rgba(20,30,45,.08); font-size: 12px;\n}\n.summary strong { font-weight: 760; }\n.legend {\n    position: absolute;\n    left: 50%;\n    bottom: 14px;\n    transform: translateX(-50%);\n    width: 90%;\n    z-index: 4;\n    display: grid;\n    grid-template-columns: repeat(6, minmax(0, 1fr));\n    column-gap: 14px;\n    row-gap: 4px;\n    align-items: center;\n    background: rgba(255,255,255,.95);\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 8px 12px;\n    box-shadow: 0 3px 14px rgba(20,30,45,.08);\n    font-size: 11px;\n}\n.legend-title {\n    grid-column: 1 / -1;\n    font-weight: 760;\n    margin-bottom: 1px;\n}\n.legend-row {\n    display: flex;\n    align-items: center;\n    gap: 7px;\n    min-width: 0;\n    line-height: 1.25;\n}\n.dot { width: 12px; height: 12px; border-radius: 50%; flex: none; }\n.line-sample {\n    width: 27px;\n    height: 0;\n    border-top: 4px solid #111827;\n    flex: none;\n}\n.line-sample.subtree {\n    border-top-style: dotted;\n    border-top-color: #4B5563;\n}\n#tooltip {\n    position: fixed; z-index: 999; display: none; max-width: 380px;\n    background: rgba(17,24,39,.96); color: #fff; border-radius: 9px;\n    padding: 10px 11px; font-size: 12px; line-height: 1.45;\n    pointer-events: none; box-shadow: 0 8px 28px rgba(0,0,0,.22);\n}\n#tooltip .title { font-weight: 760; font-size: 13px; }\n#tooltip .id { color: #cbd5e1; font-family: ui-monospace, monospace; margin: 2px 0 7px; }\n#tooltip .path { color: #dbe4f0; margin-top: 7px; }\n#toast {\n    position: fixed; left: 50%; bottom: 22px; transform: translateX(-50%) translateY(20px);\n    opacity: 0; pointer-events: none; background: #111827; color: #fff;\n    padding: 9px 13px; border-radius: 8px; font-size: 13px; z-index: 1200;\n    transition: .18s ease;\n}\n#toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n.drawer-backdrop {\n    position: fixed; inset: 0; background: rgba(15,23,42,.28); z-index: 1000;\n    opacity: 0; pointer-events: none; transition: opacity .18s ease;\n}\n.drawer-backdrop.open { opacity: 1; pointer-events: auto; }\n#comparisonDrawer {\n    position: fixed; z-index: 1001; left: 4vw; right: 4vw; bottom: 0;\n    height: min(78vh, 790px); background: #fff;\n    border: 1px solid var(--border); border-bottom: 0;\n    border-radius: 16px 16px 0 0;\n    box-shadow: 0 -12px 38px rgba(15,23,42,.18);\n    transform: translateY(105%); transition: transform .22s ease;\n    display: grid; grid-template-rows: auto auto auto 1fr;\n    overflow: hidden;\n}\n#comparisonDrawer.open { transform: translateY(0); }\n.drawer-header {\n    display: flex; align-items: start; gap: 14px; padding: 14px 18px 11px;\n    border-bottom: 1px solid var(--border);\n}\n.drawer-title-wrap { min-width: 0; flex: 1; }\n.drawer-title { margin: 0; font-size: 18px; overflow-wrap: anywhere; }\n.drawer-subtitle { margin-top: 3px; font-size: 12px; color: var(--muted); }\n.drawer-close {\n    width: 36px; height: 36px; border: 1px solid var(--border);\n    border-radius: 9px; background: #fff; cursor: pointer; font-size: 20px;\n}\n.tabs { display: flex; gap: 8px; padding: 10px 18px 0; }\n.tab {\n    border: 1px solid var(--border); border-radius: 9px 9px 0 0;\n    background: #f8fafc; color: #435067; padding: 8px 13px; cursor: pointer;\n    font-weight: 700; font-size: 13px;\n}\n.tab.active { color: #1049b8; border-color: #a6baf2; background: #edf2ff; }\n.tab[hidden] { display: none; }\n.drawer-controls {\n    display: flex; align-items: center; flex-wrap: wrap; gap: 9px;\n    padding: 10px 18px; border-bottom: 1px solid var(--border); background: #fbfcfe;\n}\n.drawer-controls input, .drawer-controls select {\n    height: 36px; border: 1px solid var(--border); border-radius: 8px;\n    background: white; padding: 0 10px; color: var(--text);\n}\n.drawer-controls input { min-width: 260px; flex: 1; }\n.drawer-body { overflow: auto; padding: 14px 18px 24px; }\n.metric-strip {\n    display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 10px;\n    margin-bottom: 14px;\n}\n.metric-card { border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px; }\n.metric-label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .04em; }\n.metric-value { margin-top: 4px; font-size: 18px; font-weight: 780; }\n.table-section { margin-top: 18px; }\n.table-section:first-of-type { margin-top: 0; }\n.table-heading { display: flex; align-items: baseline; gap: 8px; margin-bottom: 7px; }\n.table-heading h3 { margin: 0; font-size: 15px; }\n.table-heading span { color: var(--muted); font-size: 12px; }\n.table-wrap {\n    max-height: 280px; overflow: auto; border: 1px solid var(--border);\n    border-radius: 10px; background: white;\n}\ntable { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12px; }\nth, td { padding: 8px 10px; border-bottom: 1px solid #edf0f4; text-align: right; white-space: nowrap; }\nth {\n    position: sticky; top: 0; z-index: 2; background: #f7f9fc;\n    color: #46546b; font-size: 11px; text-transform: uppercase; letter-spacing: .025em;\n}\nth:first-child, td:first-child { text-align: left; }\nth:nth-child(2), td:nth-child(2) { text-align: left; }\ntr:last-child td { border-bottom: 0; }\n.tool-lung { background: rgba(229,57,53,.045); }\n.tool-pan { background: rgba(21,101,192,.045); }\n.diff-cell { font-weight: 740; }\n.na { color: #8b95a5; }\n.method-note {\n    margin-top: 18px; border: 1px solid var(--border); border-radius: 10px;\n    background: #fbfcfe; padding: 0 12px;\n}\n.method-note summary { cursor: pointer; padding: 10px 0; font-weight: 720; font-size: 13px; }\n.method-note-content { padding: 0 0 11px; color: #48566d; font-size: 12px; line-height: 1.55; }\n.method-note-content p { margin: 5px 0; }\n.unmapped-labels { white-space: normal; text-align: left; max-width: 360px; }\n.unmapped-tool { text-align: left; }\n.sidebar-unmapped {\n    margin-top: 14px;\n    border-top: 1px solid #edf0f4;\n    border-bottom: 1px solid #edf0f4;\n}\n.sidebar-unmapped .table-wrap { max-height: 260px; }\n.sidebar-unmapped table { min-width: 560px; }\n.formula { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; color: #24324a; }\n@media (max-width: 900px) {\n    :root { --details-width: 330px; }\n    .metric-strip { grid-template-columns: 1fr; }\n    #comparisonDrawer { left: 1vw; right: 1vw; }\n}\n</style>\n</head>\n<body>\n<div id="app">\n<header>\n    <div class="brand">\n        <h1>HRApop __ORGAN_TITLE__ Population View</h1>\n        <p>Estimated cell counts and shares by anatomical structure and sex</p>\n    </div>\n    <div class="search-wrap">\n        <input id="search" type="search" placeholder="Search cell type or ontology ID" />\n        <button id="searchButton" title="Search">⌕</button>\n    </div>\n    <div class="controls">\n        <button class="control" id="fitButton" title="Fit graph">Fit</button>\n        <button class="control" id="zoomOut" title="Zoom out">−</button>\n        <button class="control" id="zoomIn" title="Zoom in">+</button>\n        <button class="control active" id="inspectToggle" title="Enable or disable hover inspection">Inspect</button>\n        <button class="control active" id="labelsToggle" title="Show or hide labels">Labels</button>\n    </div>\n</header>\n<main>\n    <section id="graphWrap">\n        <div id="cy"></div>\n        <div class="summary" id="summary"></div>\n        <div class="legend">\n            <div class="legend-title">Direct HRApop output and hierarchy tracing</div>\n            <div class="legend-row"><span class="dot" style="background:var(--red)"></span>__LUNG_TOOL_DISPLAY__ only</div>\n            <div class="legend-row"><span class="dot" style="background:var(--blue)"></span>__PAN_TOOL_DISPLAY__ only</div>\n            <div class="legend-row"><span class="dot" style="background:var(--purple)"></span>Exact CT ID in both</div>\n            <div class="legend-row"><span class="dot" style="background:var(--gray)"></span>Not directly output by either</div>\n            <div class="legend-row"><span class="line-sample"></span>Primary path to root</div>\n            <div class="legend-row"><span class="line-sample subtree"></span>All descendant branches</div>\n        </div>\n    </section>\n    <aside id="details"></aside>\n</main>\n</div>\n<div id="tooltip"></div>\n<div id="toast"></div>\n<div class="drawer-backdrop" id="drawerBackdrop"></div>\n<section id="comparisonDrawer" aria-hidden="true">\n    <div class="drawer-header">\n        <div class="drawer-title-wrap">\n            <h2 class="drawer-title" id="drawerTitle">Comparison tables</h2>\n            <div class="drawer-subtitle" id="drawerSubtitle"></div>\n        </div>\n        <button class="drawer-close" id="drawerClose" aria-label="Close comparison tables">×</button>\n    </div>\n    <div class="tabs">\n        <button class="tab active" data-tab="exact" id="exactTab">Exact cell type</button>\n        <button class="tab" data-tab="subtree" id="subtreeTab">Node + descendants</button>\n    </div>\n    <div class="drawer-controls">\n        <input id="asFilter" type="search" placeholder="Filter anatomical structures" />\n        <select id="sexFilter" aria-label="Filter by sex"><option value="all">All sexes</option></select>\n        <select id="sortRows" aria-label="Sort rows">\n            <option value="share-diff">Largest percentage-point difference</option>\n            <option value="count-diff">Largest count difference</option>\n            <option value="as">Anatomical structure</option>\n        </select>\n    </div>\n    <div class="drawer-body">\n        <div class="metric-strip">\n            <div class="metric-card"><div class="metric-label">AS × sex groups compared</div><div class="metric-value" id="metricGroups">—</div></div>\n            <div class="metric-card"><div class="metric-label">Median absolute count difference</div><div class="metric-value" id="metricCount">—</div></div>\n            <div class="metric-card"><div class="metric-label">Median absolute share difference</div><div class="metric-value" id="metricShare">—</div></div>\n        </div>\n        <section class="table-section">\n            <div class="table-heading"><h3 id="countHeading">Estimated cell count</h3><span>by anatomical structure and sex</span></div>\n            <div class="table-wrap"><table><thead><tr><th>Anatomical structure</th><th>Sex</th><th class="tool-lung">__LUNG_TOOL_DISPLAY__</th><th class="tool-pan">__PAN_TOOL_DISPLAY__</th><th>Absolute difference</th></tr></thead><tbody id="countRows"></tbody></table></div>\n        </section>\n        <section class="table-section">\n            <div class="table-heading"><h3 id="percentageHeading">Share of annotated cells</h3><span>absolute difference shown in percentage points</span></div>\n            <div class="table-wrap"><table><thead><tr><th>Anatomical structure</th><th>Sex</th><th class="tool-lung">__LUNG_TOOL_DISPLAY__</th><th class="tool-pan">__PAN_TOOL_DISPLAY__</th><th>Absolute difference</th></tr></thead><tbody id="percentageRows"></tbody></table></div>\n        </section>\n        <details class="method-note">\n            <summary>How these values are calculated</summary>\n            <div class="method-note-content">\n                <p><strong>Exact percentage:</strong> <span class="formula">cell_percentage × 100</span>.</p>\n                <p><strong>Subtree count:</strong> sum of the selected node and all descendants.</p>\n                <p><strong>Subtree percentage:</strong> <span class="formula">subtree count ÷ total cell count</span> for the same AS, sex, and tool.</p>\n                <p><strong>Absolute difference:</strong> unsigned difference; share differences are reported in percentage points (pp).</p>\n                <p><strong>0</strong> means the tool has that AS × sex group but did not output the selected label. <strong>N/A</strong> means that complete tool group is unavailable.</p>\n                <p>Counts are estimated HRApop AS-level populations.</p>\n            </div>\n        </details>\n    </div>\n</section>\n<script src="https://cdn.jsdelivr.net/npm/cytoscape@3.33.1/dist/cytoscape.min.js"></script>\n<script>\n(() => {\n"use strict";\nconst payload = __PAYLOAD_JSON__;\nconst summary = payload.summary;\nconst lungTool = __LUNG_TOOL_JS__;\nconst panTool = __PAN_TOOL_JS__;\nconst rootId = "CL:0000000";\nconst statusText = {\n    neutral: "Not directly output by either tool",\n    lung_only: `${lungTool} only`,\n    pan_only: `${panTool} only`,\n    shared: "Exact CT ID in both tools"\n};\nconst statusColors = {\n    neutral: "#8A8F98",\n    lung_only: "#E53935",\n    pan_only: "#1565C0",\n    shared: "#7B1FA2"\n};\nconst graph = cytoscape({\n    container: document.getElementById("cy"),\n    elements: { nodes: payload.nodes, edges: payload.edges },\n    layout: { name: "preset", fit: true, padding: 75 },\n    minZoom: 0.05, maxZoom: 5, wheelSensitivity: 0.16,\n    boxSelectionEnabled: false, autoungrabify: true,\n    style: [\n        { selector: "node", style: {\n            "background-color": "data(fillColor)", "width": 10, "height": 10,\n            "border-width": 0, "label": "data(displayLabel)", "font-size": 9,\n            "color": "#172033", "text-wrap": "wrap", "text-max-width": 145,\n            "text-valign": "bottom", "text-halign": "center", "text-margin-y": 7,\n            "text-background-color": "#ffffff", "text-background-opacity": .82,\n            "text-background-padding": 2, "z-index": 3\n        }},\n        { selector: "node[isCompared = true]", style: {\n            "width": 19, "height": 19, "border-width": 2,\n            "border-color": "#ffffff", "border-opacity": .95,\n            "font-weight": 700, "z-index": 10\n        }},\n        { selector: `node[id = "${rootId}"]`, style: { "width": 21, "height": 21, "font-weight": 750 }},\n        { selector: "edge", style: {\n            "width": 1, "line-color": "#667085", "opacity": .32,\n            "curve-style": "straight", "z-index": 1\n        }},\n        { selector: ".path-node", style: { "border-width": 4, "border-color": "#111827", "border-opacity": 1, "z-index": 30 }},\n        { selector: ".path-edge", style: { "width": 4, "line-color": "#111827", "line-style": "solid", "opacity": .95, "z-index": 25 }},\n        { selector: ".subtree-node", style: { "border-width": 3, "border-color": "#4B5563", "border-style": "dotted", "border-opacity": .95, "z-index": 28 }},\n        { selector: ".subtree-edge", style: { "width": 4, "line-color": "#4B5563", "line-style": "dotted", "opacity": .88, "z-index": 24 }},\n        { selector: ".faded", style: { "opacity": .08 }},\n        { selector: "node:selected", style: { "border-width": 5, "border-color": "#111827", "border-opacity": 1 }}\n    ]\n});\nconst tooltip = document.getElementById("tooltip");\nconst details = document.getElementById("details");\nconst searchInput = document.getElementById("search");\nconst inspectToggle = document.getElementById("inspectToggle");\nconst labelsToggle = document.getElementById("labelsToggle");\nconst drawer = document.getElementById("comparisonDrawer");\nconst drawerBackdrop = document.getElementById("drawerBackdrop");\nconst exactTab = document.getElementById("exactTab");\nconst subtreeTab = document.getElementById("subtreeTab");\nconst asFilter = document.getElementById("asFilter");\nconst sexFilter = document.getElementById("sexFilter");\nconst sortRows = document.getElementById("sortRows");\nlet inspectEnabled = true;\nlet labelsEnabled = true;\nlet pinnedNode = null;\nlet comparisonNode = null;\nlet activeTab = "exact";\nfunction escapeHtml(value) {\n    return String(value ?? "")\n        .replaceAll("&", "&amp;").replaceAll("<", "&lt;")\n        .replaceAll(">", "&gt;").replaceAll(\'"\', "&quot;")\n        .replaceAll("\'", "&#039;");\n}\nfunction pills(values) {\n    if (!values || values.length === 0) return \'<span class="placeholder">None</span>\';\n    return values.map(value => `<span class="pill">${escapeHtml(value)}</span>`).join("");\n}\nfunction toolBlock(title, meta, isDirect) {\n    return `\n        <div class="tool-row">\n            <div><span class="tool-name">${escapeHtml(title)}</span>${isDirect && meta.labels.length ? `<div class="section-value">${pills(meta.labels)}</div>` : ""}${isDirect && meta.sexes.length ? `<div class="section-value"><strong>Sex:</strong> ${pills(meta.sexes)}</div>` : ""}</div>\n            <div class="${isDirect ? "direct-yes" : "direct-no"}">${isDirect ? "Direct output" : "Not direct"}</div>\n        </div>`;\n}\nfunction unmappedDisclosureHtml() {\n    if (!summary.unmappedComparisonCount) return "";\n    const rows = (payload.unmapped || []).map(item => {\n        const labelText = item.labels && item.labels.length\n            ? item.labels.join("; ")\n            : "—";\n        return `<tr><td>${escapeHtml(item.id)}</td><td class="unmapped-labels">${escapeHtml(labelText)}</td><td class="unmapped-tool">${escapeHtml(item.toolStatus)}</td></tr>`;\n    }).join("");\n    return `\n        <details class="method-note sidebar-unmapped">\n            <summary>Unmapped HRApop cell-type IDs (${countFormatter.format(summary.unmappedComparisonCount)})</summary>\n            <div class="method-note-content">\n                <p>These output IDs are not present in the supplied supertree.</p>\n                <div class="table-wrap">\n                    <table>\n                        <thead><tr><th>Cell-type ID</th><th>HRApop label</th><th>Output by</th></tr></thead>\n                        <tbody>${rows}</tbody>\n                    </table>\n                </div>\n            </div>\n        </details>`;\n}\nfunction renderNodeDetails(node) {\n    const data = node.data();\n    const color = statusColors[data.status];\n    const parentText = data.parentLabels && data.parentLabels.length\n        ? data.parentLabels.map((label, index) => `${escapeHtml(label)} (${escapeHtml(data.parentIds[index])})`).join("<br>")\n        : "Root";\n    details.innerHTML = `\n        <h2>${escapeHtml(data.label)}</h2>\n        <div class="node-id">${escapeHtml(data.id)}</div>\n        <div class="section"><span class="pill status-pill" style="background:${color}">${escapeHtml(statusText[data.status])}</span></div>\n        <div class="section"><div class="section-title">Primary ontology path</div><div class="section-value">${escapeHtml(data.pathText)}</div></div>\n        <div class="section">\n            <div class="section-title">Hierarchy position</div>\n            <div class="section-value"><strong>Node type:</strong> ${data.isLeaf ? "Leaf" : `Non-leaf · ${data.descendantCount} descendants`}</div>\n            <div class="section-value"><strong>Depth:</strong> ${data.depth}</div>\n            <div class="section-value"><strong>Immediate parent${data.parentIds && data.parentIds.length === 1 ? "" : "s"}:</strong><br>${parentText}</div>\n        </div>\n        <div class="section">\n            <div class="section-title">Hierarchy provenance</div>\n            <div class="section-value"><strong>Used anywhere in hierarchy paths from:</strong><br>${pills(data.sources)}</div>\n            <div class="section-value"><strong>Listed as the terminal cell type by:</strong><br>${pills(data.terminalSources)}</div>\n        </div>\n        <div class="section">\n            <div class="section-title">Tool outputs</div>\n            ${toolBlock(lungTool, data.lungMeta, data.inLung)}\n            ${toolBlock(panTool, data.panMeta, data.inPan)}\n        </div>\n        <div class="section">\n            <div class="section-title">Directly predicted CTs in this subtree</div>\n            <div class="section-value"><strong>${escapeHtml(lungTool)}:</strong> ${data.subtreeLungCount}</div>\n            <div class="section-value"><strong>${escapeHtml(panTool)}:</strong> ${data.subtreePanCount}</div>\n            <div class="section-value"><strong>Exact shared:</strong> ${data.subtreeSharedCount}</div>\n            <div class="section-value"><strong>Tool-specific:</strong> ${data.subtreeDifferenceCount}</div>\n        </div>\n        <div class="section"><button class="open-comparison" id="openComparison">Open comparison tables</button></div>\n        ${unmappedDisclosureHtml()}`;\n    document.getElementById("openComparison").addEventListener("click", () => openComparison(node));\n}\nfunction resetDetails() {\n    details.innerHTML = `<h2>Cell type details</h2><p class="placeholder">Hover over a node to emphasize its path and descendant subtree. Click a node to keep its details here and open AS × sex comparison tables.</p>${unmappedDisclosureHtml()}`;\n}\nfunction highlightContext(node) {\n    graph.elements().removeClass("path-node path-edge subtree-node subtree-edge faded");\n    const pathSet = new Set(node.data("pathIds"));\n    const pathEdgeSet = new Set(node.data("pathEdgeIds") || []);\n    const descendantNodeIds = new Set(node.successors("node").map(item => item.id()));\n    const descendantEdgeIds = new Set(node.successors("edge").map(item => item.id()));\n    graph.nodes().forEach(candidate => {\n        if (pathSet.has(candidate.id())) candidate.addClass("path-node");\n        else if (descendantNodeIds.has(candidate.id())) candidate.addClass("subtree-node");\n        else candidate.addClass("faded");\n    });\n    graph.edges().forEach(edge => {\n        if (pathEdgeSet.has(edge.id())) edge.addClass("path-edge");\n        else if (descendantEdgeIds.has(edge.id())) edge.addClass("subtree-edge");\n        else edge.addClass("faded");\n    });\n}\nfunction clearHighlight() {\n    if (pinnedNode) { highlightContext(pinnedNode); return; }\n    graph.elements().removeClass("path-node path-edge subtree-node subtree-edge faded");\n}\nfunction tooltipHtml(node) {\n    const data = node.data();\n    return `<div class="title">${escapeHtml(data.label)}</div><div class="id">${escapeHtml(data.id)}</div><div><strong>Status:</strong> ${escapeHtml(statusText[data.status])}</div><div><strong>Subtree:</strong> ${escapeHtml(lungTool)} ${data.subtreeLungCount}, ${escapeHtml(panTool)} ${data.subtreePanCount}, shared ${data.subtreeSharedCount}</div><div class="path"><strong>Primary path:</strong> ${escapeHtml(data.pathText)}<br><strong>Descendants:</strong> ${data.descendantCount}</div>`;\n}\nfunction moveTooltip(event) {\n    const padding = 14;\n    let x = event.originalEvent.clientX + 16;\n    let y = event.originalEvent.clientY + 16;\n    tooltip.style.display = "block";\n    const rect = tooltip.getBoundingClientRect();\n    if (x + rect.width > window.innerWidth - padding) x = event.originalEvent.clientX - rect.width - 16;\n    if (y + rect.height > window.innerHeight - padding) y = event.originalEvent.clientY - rect.height - 16;\n    tooltip.style.left = `${Math.max(padding, x)}px`;\n    tooltip.style.top = `${Math.max(padding, y)}px`;\n}\ngraph.on("mouseover", "node", event => {\n    if (!inspectEnabled) return;\n    const node = event.target;\n    tooltip.innerHTML = tooltipHtml(node);\n    moveTooltip(event);\n    highlightContext(node);\n});\ngraph.on("mousemove", "node", event => { if (inspectEnabled) moveTooltip(event); });\ngraph.on("mouseout", "node", () => { tooltip.style.display = "none"; clearHighlight(); });\ngraph.on("tap", "node", event => {\n    pinnedNode = event.target;\n    renderNodeDetails(pinnedNode);\n    highlightContext(pinnedNode);\n    if (drawer.classList.contains("open")) openComparison(pinnedNode, false);\n});\ngraph.on("tap", event => {\n    if (event.target === graph) {\n        pinnedNode = null;\n        graph.$(":selected").unselect();\n        clearHighlight();\n        resetDetails();\n    }\n});\ngraph.on("dbltap", "node", event => {\n    const node = event.target;\n    graph.animate({ center: { eles: node }, zoom: Math.min(2, Math.max(.9, graph.zoom() * 1.45)), duration: 350 });\n});\nfunction setLabels() {\n    const showAll = labelsEnabled && graph.zoom() >= .62;\n    graph.batch(() => graph.nodes().forEach(node => {\n        const shouldShow = labelsEnabled && (showAll || node.data("isCompared") || node.selected());\n        node.data("displayLabel", shouldShow ? node.data("label") : "");\n    }));\n}\ngraph.on("zoom", setLabels);\nfunction showToast(message) {\n    const toast = document.getElementById("toast");\n    toast.textContent = message; toast.classList.add("show");\n    window.clearTimeout(showToast.timer);\n    showToast.timer = window.setTimeout(() => toast.classList.remove("show"), 1700);\n}\nfunction search() {\n    const query = searchInput.value.trim().toLowerCase();\n    if (!query) return;\n    const matches = graph.nodes().filter(node => node.id().toLowerCase().includes(query) || String(node.data("label") || "").toLowerCase().includes(query));\n    if (!matches.length) { showToast("No matching node found"); return; }\n    const node = matches[0];\n    node.select(); pinnedNode = node; renderNodeDetails(node); highlightContext(node);\n    graph.animate({ center: { eles: node }, zoom: 1.45, duration: 400 });\n    if (matches.length > 1) showToast(`Showing first of ${matches.length} matches`);\n}\nfunction median(values) {\n    if (!values.length) return null;\n    const sorted = [...values].sort((a,b) => a-b);\n    const middle = Math.floor(sorted.length / 2);\n    return sorted.length % 2 ? sorted[middle] : (sorted[middle-1] + sorted[middle]) / 2;\n}\nconst countFormatter = new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 });\nfunction formatCount(value) { return value == null ? \'<span class="na">N/A</span>\' : countFormatter.format(value); }\nfunction formatPercentage(value) { return value == null ? \'<span class="na">N/A</span>\' : `${(value * 100).toFixed(2)}%`; }\nfunction formatPp(value) { return value == null ? \'<span class="na">N/A</span>\' : `${(value * 100).toFixed(2)} pp`; }\nfunction setSexOptions(rows) {\n    const current = sexFilter.value;\n    const sexes = [...new Set(rows.map(row => row.sex))].sort((a,b) => a.localeCompare(b));\n    sexFilter.innerHTML = \'<option value="all">All sexes</option>\' + sexes.map(sex => `<option value="${escapeHtml(sex)}">${escapeHtml(sex)}</option>`).join("");\n    if (sexes.includes(current)) sexFilter.value = current;\n}\nfunction activeRows() {\n    if (!comparisonNode) return [];\n    const comparison = payload.comparisons[comparisonNode.id()] || { exactRows: [], subtreeRows: [] };\n    return activeTab === "subtree" ? comparison.subtreeRows : comparison.exactRows;\n}\nfunction filteredSortedRows() {\n    const query = asFilter.value.trim().toLowerCase();\n    const sex = sexFilter.value;\n    const rows = activeRows().filter(row => (!query || row.asLabel.toLowerCase().includes(query) || row.asId.toLowerCase().includes(query)) && (sex === "all" || row.sex === sex));\n    const sortMode = sortRows.value;\n    return rows.sort((a,b) => {\n        if (sortMode === "as") return a.asLabel.localeCompare(b.asLabel) || a.sex.localeCompare(b.sex);\n        const key = sortMode === "count-diff" ? "absCountDifference" : "absPercentageDifference";\n        const av = a[key], bv = b[key];\n        if (av == null && bv == null) return a.asLabel.localeCompare(b.asLabel);\n        if (av == null) return 1;\n        if (bv == null) return -1;\n        return bv - av || a.asLabel.localeCompare(b.asLabel);\n    });\n}\nfunction renderComparisonTables() {\n    if (!comparisonNode) return;\n    const data = comparisonNode.data();\n    const rows = filteredSortedRows();\n    const prefix = activeTab === "subtree" ? "Subtree" : "Exact label";\n    document.getElementById("countHeading").textContent = `${prefix} — estimated cell count`;\n    document.getElementById("percentageHeading").textContent = `${prefix} — share of annotated cells`;\n    document.getElementById("countRows").innerHTML = rows.map(row => `<tr><td title="${escapeHtml(row.asId)}">${escapeHtml(row.asLabel)}</td><td>${escapeHtml(row.sex)}</td><td class="tool-lung">${formatCount(row.lungCount)}</td><td class="tool-pan">${formatCount(row.panCount)}</td><td class="diff-cell">${formatCount(row.absCountDifference)}</td></tr>`).join("") || \'<tr><td colspan="5" class="placeholder">No matching rows</td></tr>\';\n    document.getElementById("percentageRows").innerHTML = rows.map(row => `<tr><td title="${escapeHtml(row.asId)}">${escapeHtml(row.asLabel)}</td><td>${escapeHtml(row.sex)}</td><td class="tool-lung">${formatPercentage(row.lungPercentage)}</td><td class="tool-pan">${formatPercentage(row.panPercentage)}</td><td class="diff-cell">${formatPp(row.absPercentageDifference)}</td></tr>`).join("") || \'<tr><td colspan="5" class="placeholder">No matching rows</td></tr>\';\n    const comparable = rows.filter(row => row.lungAvailable && row.panAvailable);\n    document.getElementById("metricGroups").textContent = countFormatter.format(comparable.length);\n    const medianCount = median(comparable.map(row => row.absCountDifference).filter(value => value != null));\n    const medianShare = median(comparable.map(row => row.absPercentageDifference).filter(value => value != null));\n    document.getElementById("metricCount").innerHTML = formatCount(medianCount);\n    document.getElementById("metricShare").innerHTML = formatPp(medianShare);\n    document.getElementById("drawerSubtitle").textContent = activeTab === "subtree" ? `${data.id} · selected node plus ${data.descendantCount} descendants` : `${data.id} · exact ontology-linked label`;\n}\nfunction setActiveTab(tab) {\n    if (!comparisonNode) return;\n    if (tab === "subtree" && comparisonNode.data("isLeaf")) tab = "exact";\n    activeTab = tab;\n    exactTab.classList.toggle("active", tab === "exact");\n    subtreeTab.classList.toggle("active", tab === "subtree");\n    renderComparisonTables();\n}\nfunction openComparison(node, resetTab = true) {\n    comparisonNode = node;\n    const data = node.data();\n    document.getElementById("drawerTitle").textContent = data.label;\n    subtreeTab.hidden = data.isLeaf;\n    if (resetTab || (activeTab === "subtree" && data.isLeaf)) activeTab = "exact";\n    asFilter.value = "";\n    setSexOptions(activeRows());\n    drawer.classList.add("open");\n    drawerBackdrop.classList.add("open");\n    drawer.setAttribute("aria-hidden", "false");\n    setActiveTab(activeTab);\n}\nfunction closeComparison() {\n    drawer.classList.remove("open");\n    drawerBackdrop.classList.remove("open");\n    drawer.setAttribute("aria-hidden", "true");\n}\nexactTab.addEventListener("click", () => { setActiveTab("exact"); setSexOptions(activeRows()); renderComparisonTables(); });\nsubtreeTab.addEventListener("click", () => { setActiveTab("subtree"); setSexOptions(activeRows()); renderComparisonTables(); });\nasFilter.addEventListener("input", renderComparisonTables);\nsexFilter.addEventListener("change", renderComparisonTables);\nsortRows.addEventListener("change", renderComparisonTables);\ndocument.getElementById("drawerClose").addEventListener("click", closeComparison);\ndrawerBackdrop.addEventListener("click", closeComparison);\ndocument.addEventListener("keydown", event => { if (event.key === "Escape") closeComparison(); });\ndocument.getElementById("searchButton").addEventListener("click", search);\nsearchInput.addEventListener("keydown", event => { if (event.key === "Enter") search(); });\ndocument.getElementById("fitButton").addEventListener("click", () => graph.fit(graph.elements(), 70));\ndocument.getElementById("zoomIn").addEventListener("click", () => graph.zoom({ level: graph.zoom() * 1.25, renderedPosition: { x: graph.width()/2, y: graph.height()/2 }}));\ndocument.getElementById("zoomOut").addEventListener("click", () => graph.zoom({ level: graph.zoom() / 1.25, renderedPosition: { x: graph.width()/2, y: graph.height()/2 }}));\ninspectToggle.addEventListener("click", () => {\n    inspectEnabled = !inspectEnabled;\n    inspectToggle.classList.toggle("active", inspectEnabled);\n    if (!inspectEnabled) { tooltip.style.display = "none"; clearHighlight(); }\n});\nlabelsToggle.addEventListener("click", () => {\n    labelsEnabled = !labelsEnabled;\n    labelsToggle.classList.toggle("active", labelsEnabled);\n    setLabels();\n});\ndocument.getElementById("summary").innerHTML = `<strong>${summary.lungCount}</strong> ${escapeHtml(lungTool)} CTs · <strong>${summary.panCount}</strong> ${escapeHtml(panTool)} CTs · <strong>${summary.sharedCount}</strong> exact shared · <strong>${summary.unmappedComparisonCount}</strong> outside supertree`;\nresetDetails();\nsetLabels();\ngraph.fit(graph.elements(), 70);\n})();\n</script>\n</body>\n</html>\'\'\'\n\n\ndef render_html(\n    payload: dict[str, Any],\n    organ: str,\n    lung_tool: str,\n    pan_tool: str,\n) -> str:\n    graph_json = json.dumps(\n        payload,\n        ensure_ascii=False,\n        separators=(",", ":"),\n    ).replace("</", "<\\\\/")\n\n    replacements = {\n        "__PAYLOAD_JSON__": graph_json,\n        "__ORGAN_TITLE__": html.escape(organ.title()),\n        "__LUNG_TOOL_DISPLAY__": html.escape(display_tool_name(lung_tool)),\n        "__PAN_TOOL_DISPLAY__": html.escape(display_tool_name(pan_tool)),\n        "__LUNG_TOOL_JS__": json.dumps(display_tool_name(lung_tool)),\n        "__PAN_TOOL_JS__": json.dumps(display_tool_name(pan_tool)),\n    }\n\n    output = HTML_TEMPLATE\n    for old, new in replacements.items():\n        output = output.replace(old, new)\n    return output\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(\n        description=(\n            "Build the Task 2 Cytoscape HTML comparing HRApop v1.1 "\n            "lung Azimuth and Pan-human Azimuth outputs."\n        )\n    )\n    parser.add_argument(\n        "--supertree",\n        type=Path,\n        default=DEFAULT_SUPERTREE,\n        help="Reference supertree CSV/TSV. Default: data/ctann-v9.csv",\n    )\n    parser.add_argument(\n        "--hrapop",\n        type=Path,\n        default=DEFAULT_HRAPOP,\n        help=(\n            "HRApop population CSV. Default: "\n            "data/cell-types-in-anatomical-structurescts-per-as.csv"\n        ),\n    )\n    parser.add_argument(\n        "--output",\n        type=Path,\n        default=DEFAULT_OUTPUT,\n        help=(\n            "Output HTML. Default: output_htmls/"\n            "hrapop-v1.1-lung-azimuth-pan-human-comparison.html"\n        ),\n    )\n    parser.add_argument("--organ", default="lung")\n    parser.add_argument("--lung-tool", default="azimuth")\n    parser.add_argument("--pan-tool", default="pan-human-azimuth")\n    parser.add_argument("--modality", default="sc_transcriptomics")\n    parser.add_argument(\n        "--validation-tolerance",\n        type=float,\n        default=1e-9,\n        help="Tolerance used for population-percentage validation.",\n    )\n    return parser.parse_args()\n\n\ndef main() -> None:\n    args = parse_args()\n\n    print(f"Supertree input: {args.supertree.resolve()}")\n    print(f"HRApop input:   {args.hrapop.resolve()}")\n    print(f"HTML output:    {args.output.resolve()}")\n\n    if not args.supertree.exists():\n        raise FileNotFoundError(f"Supertree file not found: {args.supertree}")\n    if not args.hrapop.exists():\n        raise FileNotFoundError(f"HRApop file not found: {args.hrapop}")\n\n    tree = read_supertree(args.supertree)\n    hra = read_hrapop(\n        args.hrapop,\n        organ=args.organ,\n        lung_tool=args.lung_tool,\n        pan_tool=args.pan_tool,\n        modality=args.modality,\n    )\n    payload = build_graph_payload(\n        tree,\n        hra,\n        validation_tolerance=args.validation_tolerance,\n    )\n    output_html = render_html(\n        payload,\n        organ=args.organ,\n        lung_tool=args.lung_tool,\n        pan_tool=args.pan_tool,\n    )\n\n    args.output.parent.mkdir(parents=True, exist_ok=True)\n    args.output.write_text(output_html, encoding="utf-8")\n\n    summary = payload["summary"]\n    validation = summary["validation"]\n    print(f"Saved: {args.output.resolve()}")\n    print(\n        "Supertree: "\n        f"{summary[\'treeNodeCount\']} nodes, "\n        f"{summary[\'treeEdgeCount\']} edges, "\n        f"{summary[\'multiParentNodeCount\']} multi-parent nodes"\n    )\n    print(\n        f"{display_tool_name(args.lung_tool)}: {summary[\'lungCount\']} CT IDs; "\n        f"{display_tool_name(args.pan_tool)}: {summary[\'panCount\']} CT IDs"\n    )\n    print(\n        f"Shared: {summary[\'sharedCount\']}; "\n        f"{display_tool_name(args.lung_tool)}-only: {summary[\'lungOnlyCount\']}; "\n        f"{display_tool_name(args.pan_tool)}-only: {summary[\'panOnlyCount\']}; "\n        f"unmapped: {summary[\'unmappedComparisonCount\']}"\n    )\n    print(\n        "Percentage validation passed: "\n        f"{validation[\'exactCaseCount\']} exact cases and "\n        f"{validation[\'subtreeCaseCount\']} subtree cases."\n    )\n    print(\n        "Note: the generated HTML loads Cytoscape.js from jsDelivr when opened."\n    )\n\n\nif __name__ == "__main__":\n    main()'

HLCA_BUILDER_SOURCE = 'from __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\nfrom collections import Counter, defaultdict, deque\nfrom pathlib import Path\nfrom typing import Any, Iterable\n\nCYTOSCAPE_CDN = (\n    "https://cdn.jsdelivr.net/npm/cytoscape@3.33.1/dist/cytoscape.min.js"\n)\n\nBUILD_VERSION = "1.0"\nSCRIPT_DIR = Path(__file__).resolve().parent\nDEFAULT_TREE = SCRIPT_DIR / "data" / "ctann-v9.csv"\nDEFAULT_OUTPUT = (\n    SCRIPT_DIR\n    / "output_htmls"\n    / "hlca-azimuth-pan-human-exact-node-comparison.html"\n)\n\nMAX_PATH_LEVEL = 12\nCOLUMN_DX = 292.5\nROW_DY = 8.5\nLEAF_STEP = 3.0\nROOT_GAP = 2.0\n\nCOLORS = {\n    "neutral": "#8A8F98",\n    "azimuth_only": "#E53935",\n    "pan_only": "#1565C0",\n    "shared": "#7B1FA2",\n}\n\n# The builder accepts the aggregate comparison format used by the prior\n# HLCA exact-node view. Header aliases are supported.\nCOLUMN_ALIASES: dict[str, tuple[str, ...]] = {\n    "sex": (\n        "sex",\n    ),\n    "ann_finest_level": (\n        "ann_finest_level",\n        "author_label",\n        "author label",\n        "original_label",\n        "original label",\n    ),\n    "clid": (\n        "clid",\n        "cell_ontology_id",\n        "cell ontology id",\n        "cell_id",\n        "predicted_clid",\n        "supertree_clid",\n    ),\n    "mapping_status": (\n        "mapping_status",\n        "mapping status",\n        "status",\n    ),\n    "author_cohort_size": (\n        "author_cohort_size",\n        "author cohort size",\n        "cohort_size",\n        "cohort size",\n        "total_cells_in_cohort",\n        "total cells in cohort",\n    ),\n    "azimuth_count": (\n        "azimuth_count",\n        "azimuth count",\n        "lung_azimuth_count",\n        "lung azimuth count",\n    ),\n    "pan_human_count": (\n        "pan_human_count",\n        "pan human count",\n        "pan_human_azimuth_count",\n        "pan human azimuth count",\n        "pan-human count",\n    ),\n    "both_same_cell_count": (\n        "both_same_cell_count",\n        "both same cell count",\n        "both_count",\n        "both count",\n        "same_cell_count",\n    ),\n    "azimuth_only_count": (\n        "azimuth_only_count",\n        "azimuth only count",\n    ),\n    "pan_human_only_count": (\n        "pan_human_only_count",\n        "pan human only count",\n        "pan-human only count",\n    ),\n    "union_count": (\n        "union_count",\n        "union count",\n    ),\n}\n\nPREFERRED_COMPARISON_FILENAMES = (\n    "hlca-azimuth-pan-human-comparison.csv",\n    "hlca-azimuth-pan-human-comparison.tsv",\n    "hlca-azimuth-pan-human-by-sex-author-label-clid.csv",\n    "hlca-azimuth-pan-human-by-sex-author-label-clid.tsv",\n    "hlca-exact-node-comparison.csv",\n    "hlca-exact-node-comparison.tsv",\n    "lung-azimuth-comparison-aggregated.csv",\n    "lung-azimuth-comparison-aggregated.tsv",\n)\n\n\ndef normalize_ontology_id(value: str | None) -> str:\n    """Normalize common OBO URI, underscore, and CURIE identifiers."""\n    raw = (value or "").strip()\n    if not raw:\n        return ""\n\n    for prefix in (\n        "https://purl.obolibrary.org/obo/",\n        "http://purl.obolibrary.org/obo/",\n    ):\n        if raw.startswith(prefix):\n            raw = raw[len(prefix) :]\n            break\n\n    match = re.fullmatch(\n        r"([A-Za-z][A-Za-z0-9-]*)[_:]([A-Za-z0-9_.-]+)",\n        raw,\n    )\n    if match:\n        return f"{match.group(1).upper()}:{match.group(2)}"\n\n    return raw\n\n\ndef normalize_header(value: str | None) -> str:\n    return re.sub(r"[^a-z0-9]+", " ", (value or "").strip().casefold()).strip()\n\n\ndef detect_delimiter(path: Path) -> str:\n    if path.suffix.lower() in {".tsv", ".tab"}:\n        return "\\t"\n\n    with path.open("r", encoding="utf-8-sig", newline="") as handle:\n        sample = handle.read(65536)\n\n    try:\n        return csv.Sniffer().sniff(sample, delimiters=",\\t;").delimiter\n    except csv.Error:\n        return ","\n\n\ndef read_header(path: Path) -> tuple[list[str], str]:\n    delimiter = detect_delimiter(path)\n    with path.open(newline="", encoding="utf-8-sig") as handle:\n        reader = csv.reader(handle, delimiter=delimiter)\n        try:\n            header = next(reader)\n        except StopIteration:\n            return [], delimiter\n    return header, delimiter\n\n\ndef resolve_column_map(fieldnames: Iterable[str]) -> dict[str, str]:\n    normalized_to_actual = {\n        normalize_header(name): name\n        for name in fieldnames\n        if name is not None\n    }\n\n    result: dict[str, str] = {}\n    for canonical, aliases in COLUMN_ALIASES.items():\n        for alias in aliases:\n            actual = normalized_to_actual.get(normalize_header(alias))\n            if actual:\n                result[canonical] = actual\n                break\n    return result\n\n\ndef has_comparison_header(path: Path) -> bool:\n    try:\n        header, _ = read_header(path)\n    except (OSError, UnicodeError, csv.Error):\n        return False\n\n    columns = resolve_column_map(header)\n    minimum = {\n        "sex",\n        "ann_finest_level",\n        "clid",\n        "author_cohort_size",\n        "azimuth_count",\n        "pan_human_count",\n        "both_same_cell_count",\n    }\n    return minimum <= set(columns)\n\n\ndef discover_comparison_path(data_dir: Path) -> Path:\n    for filename in PREFERRED_COMPARISON_FILENAMES:\n        candidate = data_dir / filename\n        if candidate.exists() and has_comparison_header(candidate):\n            return candidate\n\n    candidates: list[Path] = []\n    for pattern in ("*.csv", "*.tsv", "*.tab"):\n        candidates.extend(sorted(data_dir.glob(pattern)))\n\n    matches = [\n        path\n        for path in candidates\n        if path.name != DEFAULT_TREE.name and has_comparison_header(path)\n    ]\n\n    if not matches:\n        raise FileNotFoundError(\n            "Could not automatically locate the HLCA aggregate comparison "\n            f"file in {data_dir}. Expected columns include sex, "\n            "ann_finest_level, clid, author_cohort_size, azimuth_count, "\n            "pan_human_count, and both_same_cell_count. Supply its path "\n            "with --comparison."\n        )\n\n    if len(matches) > 1:\n        names = "\\n  - ".join(str(path) for path in matches)\n        raise ValueError(\n            "More than one file in the data directory matches the HLCA "\n            "comparison schema. Supply one explicitly with --comparison:\\n"\n            f"  - {names}"\n        )\n\n    return matches[0]\n\n\ndef parse_nonnegative_int(\n    value: str | None,\n    *,\n    column: str,\n    row_number: int,\n    allow_blank: bool = False,\n) -> int:\n    raw = (value or "").strip()\n    if not raw:\n        if allow_blank:\n            return 0\n        raise ValueError(\n            f"Blank numeric value in column {column!r} at input row "\n            f"{row_number}."\n        )\n\n    try:\n        number = float(raw.replace(",", ""))\n    except ValueError as error:\n        raise ValueError(\n            f"Invalid numeric value {raw!r} in column {column!r} at "\n            f"input row {row_number}."\n        ) from error\n\n    if not number.is_integer() or number < 0:\n        raise ValueError(\n            f"Expected a nonnegative integer in column {column!r} at "\n            f"input row {row_number}, found {raw!r}."\n        )\n\n    return int(number)\n\n\ndef infer_mapping_status(clid: str, supplied: str) -> tuple[str, str]:\n    raw = clid.strip()\n    upper = raw.upper()\n\n    if not raw:\n        return "blank_id", ""\n\n    if upper in {"NA", "N/A", "NONE", "NULL", "MISSING"}:\n        return "method_prediction_absent", "NA"\n\n    normalized = normalize_ontology_id(raw)\n    if normalized.startswith("CL:"):\n        return "mapped_clid", normalized\n\n    supplied_key = supplied.strip().casefold()\n    if supplied_key in {\n        "method_prediction_absent",\n        "method prediction absent",\n        "absent",\n    }:\n        return "method_prediction_absent", "NA"\n\n    return "unmapped_non_cl_id", normalized\n\n\ndef read_comparison(\n    path: Path,\n    *,\n    validate_counts: bool,\n) -> dict[str, Any]:\n    delimiter = detect_delimiter(path)\n\n    with path.open(newline="", encoding="utf-8-sig") as handle:\n        reader = csv.DictReader(handle, delimiter=delimiter)\n        fieldnames = reader.fieldnames or []\n        column_map = resolve_column_map(fieldnames)\n\n        required = {\n            "sex",\n            "ann_finest_level",\n            "clid",\n            "author_cohort_size",\n            "azimuth_count",\n            "pan_human_count",\n            "both_same_cell_count",\n        }\n        missing = required - set(column_map)\n        if missing:\n            raise ValueError(\n                f"Missing required comparison columns in {path}: "\n                f"{sorted(missing)}. Available columns: {fieldnames}"\n            )\n\n        raw_rows = list(reader)\n\n    grouped: dict[\n        tuple[str, str, str, str],\n        dict[str, Any],\n    ] = {}\n\n    cohort_sizes: dict[tuple[str, str], int] = {}\n    validation_errors: list[str] = []\n\n    for row_number, raw_row in enumerate(raw_rows, start=2):\n        def get(canonical: str) -> str:\n            actual = column_map.get(canonical)\n            return (raw_row.get(actual) or "").strip() if actual else ""\n\n        sex = get("sex")\n        author_label = get("ann_finest_level")\n        supplied_status = get("mapping_status")\n        mapping_status, clid = infer_mapping_status(\n            get("clid"),\n            supplied_status,\n        )\n\n        cohort_size = parse_nonnegative_int(\n            get("author_cohort_size"),\n            column="author_cohort_size",\n            row_number=row_number,\n        )\n        azimuth = parse_nonnegative_int(\n            get("azimuth_count"),\n            column="azimuth_count",\n            row_number=row_number,\n        )\n        pan = parse_nonnegative_int(\n            get("pan_human_count"),\n            column="pan_human_count",\n            row_number=row_number,\n        )\n        both = parse_nonnegative_int(\n            get("both_same_cell_count"),\n            column="both_same_cell_count",\n            row_number=row_number,\n        )\n\n        if both > min(azimuth, pan):\n            validation_errors.append(\n                f"row {row_number}: both_same_cell_count={both} exceeds "\n                f"min(azimuth_count={azimuth}, pan_human_count={pan})"\n            )\n\n        expected_azimuth_only = azimuth - both\n        expected_pan_only = pan - both\n        expected_union = azimuth + pan - both\n\n        if "azimuth_only_count" in column_map:\n            azimuth_only = parse_nonnegative_int(\n                get("azimuth_only_count"),\n                column="azimuth_only_count",\n                row_number=row_number,\n            )\n        else:\n            azimuth_only = expected_azimuth_only\n\n        if "pan_human_only_count" in column_map:\n            pan_only = parse_nonnegative_int(\n                get("pan_human_only_count"),\n                column="pan_human_only_count",\n                row_number=row_number,\n            )\n        else:\n            pan_only = expected_pan_only\n\n        if "union_count" in column_map:\n            union = parse_nonnegative_int(\n                get("union_count"),\n                column="union_count",\n                row_number=row_number,\n            )\n        else:\n            union = expected_union\n\n        if validate_counts:\n            if azimuth_only != expected_azimuth_only:\n                validation_errors.append(\n                    f"row {row_number}: azimuth_only_count={azimuth_only}, "\n                    f"expected {expected_azimuth_only}"\n                )\n            if pan_only != expected_pan_only:\n                validation_errors.append(\n                    f"row {row_number}: pan_human_only_count={pan_only}, "\n                    f"expected {expected_pan_only}"\n                )\n            if union != expected_union:\n                validation_errors.append(\n                    f"row {row_number}: union_count={union}, "\n                    f"expected {expected_union}"\n                )\n\n        if not sex:\n            sex = "(blank)"\n        if not author_label:\n            author_label = "(blank)"\n\n        cohort_key = (sex, author_label)\n        prior_cohort_size = cohort_sizes.get(cohort_key)\n        if (\n            prior_cohort_size is not None\n            and prior_cohort_size != cohort_size\n        ):\n            validation_errors.append(\n                f"row {row_number}: cohort {cohort_key!r} has "\n                f"author_cohort_size={cohort_size}; previously "\n                f"{prior_cohort_size}"\n            )\n        cohort_sizes[cohort_key] = cohort_size\n\n        group_key = (\n            sex,\n            author_label,\n            clid,\n            mapping_status,\n        )\n\n        if group_key not in grouped:\n            grouped[group_key] = {\n                "sex": sex,\n                "ann_finest_level": author_label,\n                "clid": clid,\n                "mapping_status": mapping_status,\n                "author_cohort_size": cohort_size,\n                "azimuth_count": 0,\n                "pan_human_count": 0,\n                "both_same_cell_count": 0,\n                "azimuth_only_count": 0,\n                "pan_human_only_count": 0,\n                "union_count": 0,\n            }\n\n        item = grouped[group_key]\n        item["azimuth_count"] += azimuth\n        item["pan_human_count"] += pan\n        item["both_same_cell_count"] += both\n        item["azimuth_only_count"] += azimuth_only\n        item["pan_human_only_count"] += pan_only\n        item["union_count"] += union\n\n    if validation_errors:\n        preview = "\\n  - ".join(validation_errors[:20])\n        suffix = (\n            f"\\n  ... and {len(validation_errors) - 20} more"\n            if len(validation_errors) > 20\n            else ""\n        )\n        raise ValueError(\n            "Comparison validation failed:\\n"\n            f"  - {preview}{suffix}\\n"\n            "Use --skip-count-validation only after confirming that the "\n            "input intentionally uses different definitions."\n        )\n\n    rows = sorted(\n        grouped.values(),\n        key=lambda row: (\n            row["sex"].casefold(),\n            row["ann_finest_level"].casefold(),\n            row["mapping_status"],\n            row["clid"],\n        ),\n    )\n\n    return {\n        "rows": rows,\n        "cohort_sizes": cohort_sizes,\n        "input_row_count": len(raw_rows),\n        "aggregated_row_count": len(rows),\n    }\n\n\ndef read_supertree(path: Path) -> dict[str, Any]:\n    delimiter = detect_delimiter(path)\n\n    with path.open(newline="", encoding="utf-8-sig") as handle:\n        reader = csv.DictReader(handle, delimiter=delimiter)\n        fieldnames = set(reader.fieldnames or [])\n        required = {"CT/1 - Sources", "AS/1/ID", "AS/1/LABEL"}\n        missing = required - fieldnames\n        if missing:\n            raise ValueError(\n                f"Missing required supertree columns in {path}: "\n                f"{sorted(missing)}"\n            )\n        rows = list(reader)\n\n    labels: dict[str, str] = {}\n    label_variants: dict[str, set[str]] = defaultdict(set)\n    node_sources: dict[str, set[str]] = defaultdict(set)\n    terminal_sources: dict[str, set[str]] = defaultdict(set)\n    parents: dict[str, set[str]] = defaultdict(set)\n    children: dict[str, set[str]] = defaultdict(set)\n    edge_counts: Counter[tuple[str, str]] = Counter()\n\n    for row in rows:\n        source = (row.get("CT/1 - Sources") or "").strip() or "(blank)"\n        path_nodes: list[tuple[str, str]] = []\n\n        for level in range(1, MAX_PATH_LEVEL + 1):\n            node_id = normalize_ontology_id(row.get(f"AS/{level}/ID"))\n            node_label = (row.get(f"AS/{level}/LABEL") or "").strip()\n            if node_id:\n                path_nodes.append((node_id, node_label or node_id))\n\n        if not path_nodes:\n            continue\n\n        terminal_sources[path_nodes[-1][0]].add(source)\n        previous: str | None = None\n\n        for node_id, node_label in path_nodes:\n            labels[node_id] = node_label\n            label_variants[node_id].add(node_label)\n            node_sources[node_id].add(source)\n\n            if previous and previous != node_id:\n                parents[node_id].add(previous)\n                children[previous].add(node_id)\n                edge_counts[(previous, node_id)] += 1\n            previous = node_id\n\n    all_nodes = set(labels)\n    if not all_nodes:\n        raise ValueError(f"No supertree nodes were found in {path}.")\n\n    roots = sorted(\n        [\n            node\n            for node in all_nodes\n            if not parents.get(node)\n        ],\n        key=lambda node: (labels.get(node, ""), node),\n    )\n    if not roots:\n        roots = [min(all_nodes)]\n\n    depth: dict[str, int] = {}\n    queue: deque[str] = deque()\n    for root in roots:\n        depth[root] = 0\n        queue.append(root)\n\n    while queue:\n        node = queue.popleft()\n        for child in sorted(\n            children.get(node, set()),\n            key=lambda value: (\n                -edge_counts[(node, value)],\n                labels.get(value, ""),\n                value,\n            ),\n        ):\n            candidate = depth[node] + 1\n            if child not in depth or candidate < depth[child]:\n                depth[child] = candidate\n                queue.append(child)\n\n    for node in all_nodes:\n        depth.setdefault(node, 0)\n\n    primary_parent: dict[str, str] = {}\n    for node in all_nodes:\n        node_parents = parents.get(node, set())\n        if not node_parents:\n            continue\n        primary_parent[node] = sorted(\n            node_parents,\n            key=lambda parent: (\n                -edge_counts[(parent, node)],\n                depth.get(parent, 999),\n                labels.get(parent, ""),\n                parent,\n            ),\n        )[0]\n\n    primary_children: dict[str, list[str]] = defaultdict(list)\n    for child, parent in primary_parent.items():\n        primary_children[parent].append(child)\n\n    for parent in primary_children:\n        primary_children[parent].sort(\n            key=lambda child: (\n                depth.get(child, 999),\n                -len(children.get(child, set())),\n                labels.get(child, ""),\n                child,\n            )\n        )\n\n    y_position: dict[str, float] = {}\n    cursor = 0.0\n    active_stack: set[str] = set()\n\n    def assign_y(node: str) -> None:\n        nonlocal cursor\n        if node in y_position:\n            return\n        if node in active_stack:\n            raise ValueError(\n                "A cycle was encountered in the primary-parent layout at "\n                f"{node}."\n            )\n\n        active_stack.add(node)\n        child_list = primary_children.get(node, [])\n        if not child_list:\n            y_position[node] = cursor\n            cursor += LEAF_STEP\n        else:\n            for child in child_list:\n                assign_y(child)\n            y_position[node] = sum(\n                y_position[child] for child in child_list\n            ) / len(child_list)\n        active_stack.remove(node)\n\n    for root_index, root in enumerate(roots):\n        assign_y(root)\n        if root_index < len(roots) - 1:\n            cursor += ROOT_GAP\n\n    for node in sorted(\n        all_nodes,\n        key=lambda value: (\n            depth.get(value, 999),\n            labels.get(value, ""),\n            value,\n        ),\n    ):\n        if node not in y_position:\n            y_position[node] = cursor\n            cursor += LEAF_STEP\n\n    def primary_path(node_id: str) -> list[str]:\n        result = [node_id]\n        seen = {node_id}\n        current = node_id\n        while current in primary_parent:\n            current = primary_parent[current]\n            if current in seen:\n                break\n            seen.add(current)\n            result.append(current)\n        result.reverse()\n        return result\n\n    descendant_cache: dict[str, set[str]] = {}\n\n    def descendants(node_id: str) -> set[str]:\n        if node_id in descendant_cache:\n            return descendant_cache[node_id]\n\n        result: set[str] = set()\n        stack = list(children.get(node_id, set()))\n        while stack:\n            child = stack.pop()\n            if child in result:\n                continue\n            result.add(child)\n            stack.extend(children.get(child, set()))\n        descendant_cache[node_id] = result\n        return result\n\n    return {\n        "labels": labels,\n        "label_variants": label_variants,\n        "node_sources": node_sources,\n        "terminal_sources": terminal_sources,\n        "parents": parents,\n        "children": children,\n        "edge_counts": edge_counts,\n        "roots": roots,\n        "depth": depth,\n        "primary_parent": primary_parent,\n        "y_position": y_position,\n        "primary_path": primary_path,\n        "descendants": descendants,\n        "nodes": all_nodes,\n    }\n\n\ndef status_from_counts(azimuth: int, pan: int) -> str:\n    if azimuth > 0 and pan > 0:\n        return "shared"\n    if azimuth > 0:\n        return "azimuth_only"\n    if pan > 0:\n        return "pan_only"\n    return "neutral"\n\n\ndef aggregate_rows(rows: list[dict[str, Any]]) -> dict[str, Any]:\n    cohort_sizes: dict[tuple[str, str], int] = {}\n    azimuth = 0\n    pan = 0\n    both = 0\n    azimuth_only = 0\n    pan_only = 0\n    union = 0\n\n    for row in rows:\n        if row["azimuth_count"] <= 0 and row["pan_human_count"] <= 0:\n            continue\n\n        cohort_key = (row["sex"], row["ann_finest_level"])\n        cohort_sizes[cohort_key] = row["author_cohort_size"]\n        azimuth += row["azimuth_count"]\n        pan += row["pan_human_count"]\n        both += row["both_same_cell_count"]\n        azimuth_only += row["azimuth_only_count"]\n        pan_only += row["pan_human_only_count"]\n        union += row["union_count"]\n\n    status = status_from_counts(azimuth, pan)\n\n    return {\n        "azimuth": azimuth,\n        "pan": pan,\n        "both": both,\n        "azimuthOnly": azimuth_only,\n        "panOnly": pan_only,\n        "union": union,\n        "cohortCount": len(cohort_sizes),\n        "cohortCellCount": sum(cohort_sizes.values()),\n        "status": status,\n        "fillColor": COLORS[status],\n    }\n\n\ndef group_disclosure_rows(\n    rows: list[dict[str, Any]],\n) -> list[dict[str, Any]]:\n    grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)\n    for row in rows:\n        grouped[row["clid"]].append(row)\n\n    return [\n        {\n            "clid": clid,\n            "aggregate": aggregate_rows(group_rows),\n            "rows": group_rows,\n        }\n        for clid, group_rows in sorted(\n            grouped.items(),\n            key=lambda item: item[0],\n        )\n    ]\n\n\ndef build_payload(\n    tree: dict[str, Any],\n    comparison: dict[str, Any],\n    *,\n    paired_dataset_count: int,\n) -> dict[str, Any]:\n    rows: list[dict[str, Any]] = comparison["rows"]\n    all_nodes: set[str] = tree["nodes"]\n    labels: dict[str, str] = tree["labels"]\n    parents: dict[str, set[str]] = tree["parents"]\n    children: dict[str, set[str]] = tree["children"]\n    depth: dict[str, int] = tree["depth"]\n    primary_parent: dict[str, str] = tree["primary_parent"]\n    y_position: dict[str, float] = tree["y_position"]\n    primary_path = tree["primary_path"]\n    descendants = tree["descendants"]\n\n    mapped_rows = [\n        row\n        for row in rows\n        if row["mapping_status"] == "mapped_clid"\n    ]\n    rows_by_clid: dict[str, list[dict[str, Any]]] = defaultdict(list)\n    for row in mapped_rows:\n        rows_by_clid[row["clid"]].append(row)\n\n    global_aggregates = {\n        clid: aggregate_rows(group_rows)\n        for clid, group_rows in rows_by_clid.items()\n    }\n\n    comparison_clids = {\n        clid\n        for clid, aggregate in global_aggregates.items()\n        if aggregate["union"] > 0\n    }\n    comparison_tree_clids = comparison_clids & all_nodes\n\n    nodes: list[dict[str, Any]] = []\n    for node_id in sorted(\n        all_nodes,\n        key=lambda value: (\n            depth.get(value, 999),\n            labels.get(value, ""),\n            value,\n        ),\n    ):\n        aggregate = global_aggregates.get(node_id)\n        status = (\n            aggregate["status"]\n            if aggregate and aggregate["union"] > 0\n            else "neutral"\n        )\n        path_ids = primary_path(node_id)\n        path_labels = [\n            labels.get(path_id, path_id)\n            for path_id in path_ids\n        ]\n        parent_ids = sorted(\n            parents.get(node_id, set()),\n            key=lambda value: (\n                labels.get(value, ""),\n                value,\n            ),\n        )\n        child_ids = sorted(\n            children.get(node_id, set()),\n            key=lambda value: (\n                labels.get(value, ""),\n                value,\n            ),\n        )\n\n        nodes.append(\n            {\n                "data": {\n                    "id": node_id,\n                    "label": labels.get(node_id, node_id),\n                    "displayLabel": labels.get(node_id, node_id),\n                    "labelVariants": sorted(\n                        tree["label_variants"].get(node_id, set()),\n                        key=str.casefold,\n                    ),\n                    "isComparisonNode": node_id in comparison_tree_clids,\n                    "status": status,\n                    "fillColor": COLORS[status],\n                    "depth": depth.get(node_id, 0),\n                    "parentId": primary_parent.get(node_id, ""),\n                    "parentLabel": labels.get(\n                        primary_parent.get(node_id, ""),\n                        "",\n                    ),\n                    "parentIds": parent_ids,\n                    "parentLabels": [\n                        labels.get(value, value)\n                        for value in parent_ids\n                    ],\n                    "childIds": child_ids,\n                    "childLabels": [\n                        labels.get(value, value)\n                        for value in child_ids\n                    ],\n                    "childCount": len(child_ids),\n                    "descendantCount": len(descendants(node_id)),\n                    "pathIds": path_ids,\n                    "pathLabels": path_labels,\n                    "pathText": " → ".join(path_labels),\n                    "sources": sorted(\n                        tree["node_sources"].get(node_id, set()),\n                        key=str.casefold,\n                    ),\n                    "terminalSources": sorted(\n                        tree["terminal_sources"].get(node_id, set()),\n                        key=str.casefold,\n                    ),\n                },\n                "position": {\n                    "x": depth.get(node_id, 0) * COLUMN_DX,\n                    "y": y_position[node_id] * ROW_DY,\n                },\n            }\n        )\n\n    edges: list[dict[str, Any]] = []\n    for edge_index, (parent_id, child_id) in enumerate(\n        sorted(\n            tree["edge_counts"],\n            key=lambda edge: (\n                depth.get(edge[0], 999),\n                labels.get(edge[0], ""),\n                labels.get(edge[1], ""),\n                edge[0],\n                edge[1],\n            ),\n        )\n    ):\n        edges.append(\n            {\n                "data": {\n                    "id": f"edge-{edge_index}",\n                    "source": parent_id,\n                    "target": child_id,\n                    "isPrimary": (\n                        primary_parent.get(child_id) == parent_id\n                    ),\n                    "sourceRowCount": tree["edge_counts"][\n                        (parent_id, child_id)\n                    ],\n                }\n            }\n        )\n\n    outside_rows = [\n        row\n        for row in mapped_rows\n        if row["clid"] not in all_nodes\n    ]\n    non_cl_rows = [\n        row\n        for row in rows\n        if row["mapping_status"] == "unmapped_non_cl_id"\n    ]\n    absent_rows = [\n        row\n        for row in rows\n        if row["mapping_status"] == "method_prediction_absent"\n    ]\n    blank_rows = [\n        row\n        for row in rows\n        if row["mapping_status"] == "blank_id"\n    ]\n\n    cohort_sizes: dict[tuple[str, str], int] = {}\n    for row in rows:\n        cohort_sizes[\n            (row["sex"], row["ann_finest_level"])\n        ] = row["author_cohort_size"]\n\n    initial_status_counts = Counter(\n        global_aggregates[clid]["status"]\n        for clid in comparison_tree_clids\n    )\n\n    valid_clids = set(rows_by_clid)\n    outside_clids = valid_clids - all_nodes\n    non_cl_ids = {\n        row["clid"]\n        for row in non_cl_rows\n        if row["clid"]\n    }\n\n    payload = {\n        "nodes": nodes,\n        "edges": edges,\n        "comparisonRows": rows,\n        "sexes": sorted(\n            {row["sex"] for row in rows},\n            key=str.casefold,\n        ),\n        "authorLabels": sorted(\n            {row["ann_finest_level"] for row in rows},\n            key=str.casefold,\n        ),\n        "outsideTree": group_disclosure_rows(outside_rows),\n        "nonCl": group_disclosure_rows(non_cl_rows),\n        "absentRows": absent_rows,\n        "blankRows": blank_rows,\n        "summary": {\n            "treeNodeCount": len(all_nodes),\n            "treeEdgeCount": len(edges),\n            "treeRootCount": len(tree["roots"]),\n            "treeMultiParentNodeCount": sum(\n                1\n                for node in all_nodes\n                if len(parents.get(node, set())) > 1\n            ),\n            "inputComparisonRowCount": comparison["input_row_count"],\n            "comparisonRowCount": len(rows),\n            "mappedRowCount": len(mapped_rows),\n            "comparisonClidCount": len(valid_clids),\n            "mappedToTreeClidCount": len(valid_clids & all_nodes),\n            "outsideTreeClidCount": len(outside_clids),\n            "nonClIdentifierCount": len(non_cl_ids),\n            "nonClCellCount": sum(\n                row["union_count"]\n                for row in non_cl_rows\n            ),\n            "absentRowCount": len(absent_rows),\n            "absentCellCount": sum(\n                row["union_count"]\n                for row in absent_rows\n            ),\n            "blankRowCount": len(blank_rows),\n            "cohortCount": len(cohort_sizes),\n            "cohortCellCount": sum(cohort_sizes.values()),\n            "pairedHlcaDatasetCount": paired_dataset_count,\n            "initialStatusCounts": {\n                "pan_only": initial_status_counts["pan_only"],\n                "shared": initial_status_counts["shared"],\n                "azimuth_only": initial_status_counts["azimuth_only"],\n            },\n        },\n    }\n    return payload\n\n\ndef safe_json_for_script(value: Any) -> str:\n    text = json.dumps(\n        value,\n        ensure_ascii=False,\n        separators=(",", ":"),\n    )\n    return (\n        text.replace("<", "\\\\u003c")\n        .replace(">", "\\\\u003e")\n        .replace("&", "\\\\u0026")\n        .replace("\\u2028", "\\\\u2028")\n        .replace("\\u2029", "\\\\u2029")\n    )\n\n\n\nHTML_TEMPLATE = r\'\'\'\n<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1" />\n<title>HLCA Exact-Node View — Lung Azimuth Comparison</title>\n<style>\n:root {\n    --bg: #eef2f7;\n    --panel: #ffffff;\n    --border: #d7dde7;\n    --text: #18212f;\n    --muted: #647084;\n    --accent: #155eef;\n    --red: #E53935;\n    --blue: #1565C0;\n    --purple: #7B1FA2;\n    --gray: #8A8F98;\n    --green: #16A34A;\n    --details-width: 410px;\n    --toolbar-height: 82px;\n}\n* { box-sizing: border-box; }\nhtml, body { height: 100%; margin: 0; overflow: hidden; }\nbody {\n    font-family: Inter, ui-sans-serif, system-ui, -apple-system,\n        BlinkMacSystemFont, "Segoe UI", sans-serif;\n    color: var(--text);\n    background: var(--bg);\n}\nbutton, input, select { font: inherit; }\n#app {\n    height: 100%;\n    display: grid;\n    grid-template-rows: var(--toolbar-height) 1fr;\n}\nheader {\n    min-height: var(--toolbar-height);\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 9px 14px;\n    background: var(--panel);\n    border-bottom: 1px solid var(--border);\n    z-index: 10;\n}\n.brand { min-width: 238px; }\n.brand h1 { margin: 0 0 3px; font-size: 18px; line-height: 1.2; }\n.brand p { margin: 0; color: var(--muted); font-size: 12px; }\n.search-wrap { flex: 1; min-width: 180px; max-width: 390px; position: relative; }\n#search {\n    width: 100%; height: 40px; padding: 0 42px 0 13px;\n    border: 1px solid var(--border); border-radius: 10px;\n    outline: none; background: #fbfcfe;\n}\n#search:focus, .filter-select:focus {\n    border-color: #8ca9fb;\n    box-shadow: 0 0 0 3px rgba(21, 94, 239, 0.12);\n}\n#searchButton {\n    position: absolute; top: 4px; right: 4px; width: 34px; height: 32px;\n    border: 0; border-radius: 8px; background: transparent; cursor: pointer;\n}\n.filter-group { display: flex; align-items: end; gap: 8px; }\n.filter-field { display: grid; gap: 3px; }\n.filter-field label {\n    color: var(--muted); font-size: 10px; font-weight: 760;\n    text-transform: uppercase; letter-spacing: .045em;\n}\n.filter-select {\n    height: 40px; border: 1px solid var(--border); border-radius: 9px;\n    background: #fff; color: var(--text); padding: 0 28px 0 9px;\n    outline: none;\n}\n#sexFilter { width: 112px; }\n#authorFilter { width: 230px; max-width: 26vw; }\n.controls { display: flex; align-items: center; gap: 6px; margin-left: auto; }\n.control {\n    height: 38px; border: 1px solid var(--border); border-radius: 9px;\n    background: #fff; color: #253246; cursor: pointer; padding: 0 10px;\n}\n.control:hover { background: #f4f7fb; }\n.control.active { color: #1049b8; border-color: #a6baf2; background: #edf2ff; }\nmain {\n    min-height: 0;\n    display: grid;\n    grid-template-columns: 1fr var(--details-width);\n}\n#graphWrap {\n    position: relative; overflow: hidden; min-width: 0;\n    background: radial-gradient(circle at 40% 35%, #fff 0, #f7f9fc 44%, #edf1f6 100%);\n}\n#cy { position: absolute; inset: 0; }\n#details {\n    background: var(--panel); border-left: 1px solid var(--border);\n    padding: 18px; overflow: auto;\n}\n#details h2 { font-size: 18px; margin: 0 0 4px; overflow-wrap: anywhere; }\n.node-id {\n    font: 12px ui-monospace, SFMono-Regular, Menlo, monospace;\n    color: var(--muted); margin-bottom: 12px; overflow-wrap: anywhere;\n}\n.placeholder { color: var(--muted); font-size: 14px; line-height: 1.55; }\n.section { border-top: 1px solid #edf0f4; padding: 11px 0; }\n.section:first-of-type { border-top: 0; }\n.section-title {\n    text-transform: uppercase; letter-spacing: 0.055em; font-size: 11px;\n    font-weight: 750; color: var(--muted); margin-bottom: 6px;\n}\n.section-value { font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }\n.pill {\n    display: inline-flex; border: 1px solid #dce3ed; border-radius: 999px;\n    background: #f8fafc; padding: 4px 8px; margin: 3px 4px 0 0; font-size: 12px;\n}\n.status-pill { color: #fff; border: 0; font-weight: 700; }\n.exact-pill { color: #1049b8; border-color: #b8c8f5; background: #edf2ff; font-weight: 720; }\n.metric-grid {\n    display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 8px; margin: 8px 0 2px;\n}\n.side-metric { border: 1px solid var(--border); border-radius: 9px; padding: 8px 9px; }\n.side-metric-label { color: var(--muted); font-size: 10px; text-transform: uppercase; letter-spacing: .04em; }\n.side-metric-value { margin-top: 3px; font-size: 15px; font-weight: 760; }\n.side-metric-sub { color: var(--muted); font-size: 10px; line-height: 1.35; margin-top: 4px; }\n.open-comparison {\n    width: 100%; min-height: 42px; border: 0; border-radius: 9px;\n    background: var(--accent); color: white; font-weight: 760; cursor: pointer;\n    padding: 10px 14px;\n}\n.open-comparison:hover { background: #0d4ed1; }\n.open-comparison:disabled { cursor: not-allowed; opacity: .45; }\n.summary {\n    position: absolute; top: 13px; left: 14px; z-index: 4; max-width: 560px;\n    background: rgba(255,255,255,.96); border: 1px solid var(--border);\n    border-radius: 10px; padding: 8px 10px;\n    box-shadow: 0 3px 14px rgba(20,30,45,.08); font-size: 12px;\n}\n.summary strong { font-weight: 760; }\n.legend {\n    position: absolute;\n    left: 50%;\n    bottom: 14px;\n    transform: translateX(-50%);\n    width: 90%;\n    z-index: 4;\n    background: rgba(255,255,255,.96);\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 10px 14px;\n    box-shadow: 0 3px 14px rgba(20,30,45,.08);\n    font-size: 12px;\n    transition: width .18s ease, left .18s ease, right .18s ease,\n        transform .18s ease, padding .18s ease;\n}\n.legend-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n}\n.legend-title {\n    font-weight: 760;\n    margin-bottom: 2px;\n}\n.legend-toggle {\n    flex: none;\n    min-height: 30px;\n    border: 1px solid var(--border);\n    border-radius: 8px;\n    background: #fff;\n    color: #253246;\n    cursor: pointer;\n    padding: 4px 10px;\n    font-size: 11px;\n    font-weight: 720;\n}\n.legend-toggle:hover { background: #f4f7fb; }\n.legend-toggle:focus-visible {\n    outline: 3px solid rgba(21, 94, 239, .18);\n    outline-offset: 2px;\n}\n.legend-content {\n    display: grid;\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n    column-gap: 18px;\n    row-gap: 4px;\n    margin-top: 4px;\n}\n.legend.collapsed {\n    left: auto;\n    right: 14px;\n    width: auto;\n    min-width: 220px;\n    transform: none;\n    padding: 8px 10px;\n}\n.legend.collapsed .legend-content { display: none; }\n.legend-row {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    margin: 3px 0;\n    min-width: 0;\n}\n.legend-note {\n    grid-column: 1 / -1;\n}\n.legend-subtitle {\n    grid-column: 1 / -1;\n}\n.dot { width: 12px; height: 12px; border-radius: 50%; flex: none; }\n.ring-key {\n    position: relative; width: 28px; height: 28px; border-radius: 50%;\n    border: 5px solid var(--green); flex: none;\n}\n.ring-key::before {\n    content: ""; position: absolute; inset: 3px; border-radius: 50%;\n    background: var(--purple);\n}\n.legend-note.legend-note { color: var(--muted); max-width: none; line-height: 1.35; margin-top: 6px; }\n.legend-subtitle {\n    grid-column: 1 / -1;\n    font-weight: 740;\n    margin-top: 5px;\n    margin-bottom: 2px;\n    padding-top: 7px;\n    border-top: 1px solid #e7ebf1;\n}\n.projection-key { width: 14px; height: 14px; border-radius: 50%; flex: none; background: var(--purple); }\n.projection-key.direct { opacity: 1; }\n.projection-key.ancestor { opacity: .45; }\n.projection-key.unrelated { opacity: .11; }\n.line-key {\n    width: 30px;\n    height: 0;\n    border-top: 3px solid #111827;\n    flex: none;\n}\n.line-key.dotted {\n    border-top-style: dotted;\n    border-top-color: #657084;\n}\n#tooltip {\n    position: fixed; z-index: 999; display: none; max-width: 410px;\n    background: rgba(17,24,39,.97); color: #fff; border-radius: 9px;\n    padding: 10px 11px; font-size: 12px; line-height: 1.48;\n    pointer-events: none; box-shadow: 0 8px 28px rgba(0,0,0,.22);\n}\n#tooltip .title { font-weight: 760; font-size: 13px; }\n#tooltip .id { color: #cbd5e1; font-family: ui-monospace, monospace; margin: 2px 0 7px; }\n#tooltip .path { color: #dbe4f0; margin-top: 7px; }\n#tooltip .scope { color: #bfdbfe; margin-bottom: 7px; }\n#tooltip .interpretation { margin-top: 8px; padding-top: 7px; border-top: 1px solid rgba(255,255,255,.18); color: #dbe4f0; }\n#toast {\n    position: fixed; left: 50%; bottom: 22px; transform: translateX(-50%) translateY(20px);\n    opacity: 0; pointer-events: none; background: #111827; color: #fff;\n    padding: 9px 13px; border-radius: 8px; font-size: 13px; z-index: 1200;\n    transition: .18s ease;\n}\n#toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n.drawer-backdrop {\n    position: fixed; inset: 0; background: rgba(15,23,42,.28); z-index: 1000;\n    opacity: 0; pointer-events: none; transition: opacity .18s ease;\n}\n.drawer-backdrop.open { opacity: 1; pointer-events: auto; }\n#comparisonDrawer {\n    position: fixed; z-index: 1001; left: 3vw; right: 3vw; bottom: 0;\n    height: min(80vh, 820px); background: #fff;\n    border: 1px solid var(--border); border-bottom: 0;\n    border-radius: 16px 16px 0 0;\n    box-shadow: 0 -12px 38px rgba(15,23,42,.18);\n    transform: translateY(105%); transition: transform .22s ease;\n    display: grid; grid-template-rows: auto auto 1fr;\n    overflow: hidden;\n}\n#comparisonDrawer.open { transform: translateY(0); }\n.drawer-header {\n    display: flex; align-items: start; gap: 14px; padding: 14px 18px 11px;\n    border-bottom: 1px solid var(--border);\n}\n.drawer-title-wrap { min-width: 0; flex: 1; }\n.drawer-title { margin: 0; font-size: 18px; overflow-wrap: anywhere; }\n.drawer-subtitle { margin-top: 3px; font-size: 12px; color: var(--muted); }\n.drawer-close {\n    width: 36px; height: 36px; border: 1px solid var(--border);\n    border-radius: 9px; background: #fff; cursor: pointer; font-size: 20px;\n}\n.drawer-controls {\n    display: flex; align-items: center; flex-wrap: wrap; gap: 9px;\n    padding: 10px 18px; border-bottom: 1px solid var(--border); background: #fbfcfe;\n}\n.drawer-scope { color: var(--muted); font-size: 12px; margin-left: auto; }\n.drawer-body { overflow: auto; padding: 14px 18px 24px; }\n.metric-strip {\n    display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 10px;\n    margin-bottom: 14px;\n}\n.metric-card { border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px; }\n.metric-label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .04em; }\n.metric-value { margin-top: 4px; font-size: 18px; font-weight: 780; }\n.metric-sub { color: var(--muted); font-size: 10px; line-height: 1.35; margin-top: 4px; }\n.table-heading { display: flex; align-items: baseline; gap: 8px; margin-bottom: 7px; }\n.table-heading h3 { margin: 0; font-size: 15px; }\n.table-heading span { color: var(--muted); font-size: 12px; }\n.table-wrap {\n    max-height: 420px; overflow: auto; border: 1px solid var(--border);\n    border-radius: 10px; background: white;\n}\ntable { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12px; }\nth, td { padding: 8px 10px; border-bottom: 1px solid #edf0f4; text-align: right; white-space: nowrap; }\nth {\n    position: sticky; top: 0; z-index: 2; background: #f7f9fc;\n    color: #46546b; font-size: 11px; text-transform: uppercase; letter-spacing: .025em;\n}\nth:first-child, td:first-child, th:nth-child(2), td:nth-child(2) { text-align: left; }\ntr:last-child td { border-bottom: 0; }\n.tool-lung { background: rgba(229,57,53,.05); }\n.tool-pan { background: rgba(21,101,192,.05); }\n.method-note {\n    margin-top: 18px; border: 1px solid var(--border); border-radius: 10px;\n    background: #fbfcfe; padding: 0 12px;\n}\n.method-note summary { cursor: pointer; padding: 10px 0; font-weight: 720; font-size: 13px; }\n.method-note-content { padding: 0 0 11px; color: #48566d; font-size: 12px; line-height: 1.55; }\n.method-note-content p { margin: 5px 0; }\n.formula { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; color: #24324a; }\n.disclosure { margin-top: 8px; border: 1px solid var(--border); border-radius: 9px; background: #fbfcfe; }\n.disclosure summary { cursor: pointer; padding: 9px 10px; font-size: 12px; font-weight: 720; }\n.disclosure-body { padding: 0 10px 10px; font-size: 12px; color: #48566d; line-height: 1.5; }\n.disclosure-list { margin: 6px 0 0 18px; padding: 0; }\n@media (max-width: 1180px) {\n    :root { --details-width: 360px; }\n    .brand { min-width: 190px; }\n    #authorFilter { width: 185px; }\n    .control { padding: 0 8px; }\n}\n@media (max-width: 920px) {\n    header { flex-wrap: wrap; align-content: center; }\n    :root { --toolbar-height: 132px; --details-width: 330px; }\n    .brand { min-width: 225px; }\n    .filter-group { order: 4; width: 100%; }\n    #authorFilter { max-width: none; width: min(420px, 58vw); }\n    .metric-strip { grid-template-columns: repeat(2, minmax(0,1fr)); }\n    #comparisonDrawer { left: 1vw; right: 1vw; }\n}\n</style>\n</head>\n<body>\n<div id="app">\n<header>\n    <div class="brand">\n        <h1>HLCA Exact-Node View</h1>\n        <p>Cell-level comparison across 47 paired lung partitions with author-label projection</p>\n    </div>\n    <div class="search-wrap">\n        <input id="search" type="search" placeholder="Search cell type or ontology ID" />\n        <button id="searchButton" title="Search">⌕</button>\n    </div>\n    <div class="filter-group" aria-label="Comparison filters">\n        <div class="filter-field">\n            <label for="sexFilter">Sex</label>\n            <select class="filter-select" id="sexFilter">\n                <option value="all">All</option>\n            </select>\n        </div>\n        <div class="filter-field">\n            <label for="authorFilter">Author label</label>\n            <select class="filter-select" id="authorFilter">\n                <option value="all">All</option>\n            </select>\n        </div>\n    </div>\n    <div class="controls">\n        <button class="control" id="fitButton" title="Fit graph">Fit</button>\n        <button class="control" id="zoomOut" title="Zoom out">−</button>\n        <button class="control" id="zoomIn" title="Zoom in">+</button>\n        <button class="control active" id="inspectToggle" title="Enable or disable hover inspection">Inspect</button>\n        <button class="control active" id="labelsToggle" title="Show or hide labels">Labels</button>\n    </div>\n</header>\n<main>\n    <section id="graphWrap">\n        <div id="cy"></div>\n        <div class="summary" id="summary"></div>\n        <div class="legend" id="legend">\n            <div class="legend-header">\n                <div class="legend-title">Node fill — current filter scope</div>\n                <button\n                    class="legend-toggle"\n                    id="legendToggle"\n                    type="button"\n                    aria-expanded="true"\n                    aria-controls="legendContent"\n                >Minimize</button>\n            </div>\n            <div class="legend-content" id="legendContent">\n                <div class="legend-row"><span class="dot" style="background:var(--red)"></span>Azimuth only</div>\n                <div class="legend-row"><span class="dot" style="background:var(--blue)"></span>Pan-human only</div>\n                <div class="legend-row"><span class="dot" style="background:var(--purple)"></span>Exact CT ID in both</div>\n                <div class="legend-row"><span class="dot" style="background:var(--gray)"></span>No direct output in current scope</div>\n                <div class="legend-row"><span class="ring-key"></span>Green ring — exact CLID occurs in the comparison results from 47 paired HLCA lung dataset partitions</div>\n                <div class="legend-note">The ring identifies comparison membership and does not encode a count. Green-ringed nodes are enlarged; node fill changes with the Sex and Author label filters.</div>\n                <div class="legend-subtitle">Author-label projection</div>\n                <div class="legend-row"><span class="projection-key direct"></span>Full opacity — exact CLID destination for the selected author label</div>\n                <div class="legend-row"><span class="projection-key ancestor"></span>Medium opacity — ancestor retained for hierarchy context</div>\n                <div class="legend-row"><span class="projection-key unrelated"></span>Faded — unrelated to the selected author label</div>\n                <div class="legend-note">Projection focus activates only when a specific Author label is selected.</div>\n                <div class="legend-subtitle">Hierarchy hover</div>\n                <div class="legend-row"><span class="line-key"></span>Solid — primary path from the hovered node to a root</div>\n                <div class="legend-row"><span class="line-key dotted"></span>Dotted — all descendant branches below the hovered node</div>\n            </div>\n        </div>\n    </section>\n    <aside id="details"></aside>\n</main>\n</div>\n<div id="tooltip"></div>\n<div id="toast"></div>\n<div class="drawer-backdrop" id="drawerBackdrop"></div>\n<section id="comparisonDrawer" aria-hidden="true">\n    <div class="drawer-header">\n        <div class="drawer-title-wrap">\n            <h2 class="drawer-title" id="drawerTitle">Exact-node comparison</h2>\n            <div class="drawer-subtitle" id="drawerSubtitle"></div>\n        </div>\n        <button class="drawer-close" id="drawerClose" aria-label="Close comparison table">×</button>\n    </div>\n    <div class="drawer-controls">\n        <div><strong>Exact-node counts summed across matching cohorts</strong></div>\n        <div class="drawer-scope" id="drawerScope"></div>\n    </div>\n    <div class="drawer-body">\n        <div class="metric-strip">\n            <div class="metric-card"><div class="metric-label">Active cohorts</div><div class="metric-value" id="metricCohorts">—</div><div class="metric-sub">Distinct sex + author-label cohorts matching the active filters.</div></div>\n            <div class="metric-card"><div class="metric-label">Total cells in active cohort</div><div class="metric-value" id="metricCohortCells">—</div><div class="metric-sub">All author-annotated cells matching the active Sex and Author label filters, counting each cohort once. This is the denominator for percentages.</div></div>\n            <div class="metric-card"><div class="metric-label">Azimuth total</div><div class="metric-value" id="metricAzimuth">—</div><div class="metric-sub">Cells Azimuth assigned to this exact CLID across the active cohorts.</div></div>\n            <div class="metric-card"><div class="metric-label">Pan-human total</div><div class="metric-value" id="metricPan">—</div><div class="metric-sub">Cells pan-human Azimuth assigned to this exact CLID across the active cohorts.</div></div>\n            <div class="metric-card"><div class="metric-label">Both same cells</div><div class="metric-value" id="metricBoth">—</div><div class="metric-sub">The same individual cells were assigned to this exact CLID by both methods.</div></div>\n            <div class="metric-card"><div class="metric-label">Azimuth only</div><div class="metric-value" id="metricAzimuthOnly">—</div><div class="metric-sub">Cells assigned here by Azimuth but not to this exact CLID by pan-human.</div></div>\n            <div class="metric-card"><div class="metric-label">Pan-human only</div><div class="metric-value" id="metricPanOnly">—</div><div class="metric-sub">Cells assigned here by pan-human but not to this exact CLID by Azimuth.</div></div>\n            <div class="metric-card"><div class="metric-label">Union</div><div class="metric-value" id="metricUnion">—</div><div class="metric-sub">Unique cells assigned to this exact CLID by either method; both-agreed cells are counted once.</div></div>\n        </div>\n        <section>\n            <div class="table-heading"><h3>Exact CLID rows</h3><span>count and percentage of each author cohort</span></div>\n            <div class="table-wrap">\n                <table>\n                    <thead><tr>\n                        <th>Sex</th><th>Author label</th><th>Cohort size</th>\n                        <th class="tool-lung">Azimuth</th><th class="tool-pan">Pan-human</th>\n                        <th>Both same cells</th><th>Azimuth only</th><th>Pan-human only</th><th>Union</th>\n                    </tr></thead>\n                    <tbody id="comparisonRows"></tbody>\n                </table>\n            </div>\n        </section>\n        <details class="method-note">\n            <summary>How to interpret these counts</summary>\n            <div class="method-note-content">\n                <p>The KPI cards sum exact-CLID rows after applying the Sex and Author label filters. Each count is paired with its percentage of all cells in the active cohort. They are exact-node values, not subtree values.</p>\n                <p><strong>Total cells in active cohort:</strong> sum of <span class="formula">author_cohort_size</span> across all distinct cohorts matching the active Sex and Author label filters, counting each cohort once. It includes cells whether or not either method assigned them to this CLID and is the denominator used for all percentages.</p>\n                <p><strong>Azimuth / Pan-human:</strong> cells each method assigned to this exact CLID; percentages use total cells in the active cohort as the denominator.</p>\n                <p><strong>Both same cells:</strong> the same individual cells were assigned to this exact CLID by both methods; the percentage uses the same active-cohort denominator.</p>\n                <p><strong>Azimuth only / Pan-human only:</strong> cells assigned here by one method but not to this exact CLID by the other method.</p>\n                <p><strong>Union:</strong> unique cells assigned to this exact CLID by either method.</p>\n            </div>\n        </details>\n    </div>\n</section>\n<script src="https://cdn.jsdelivr.net/npm/cytoscape@3.33.1/dist/cytoscape.min.js"></script>\n<script>\n(() => {\n"use strict";\nconst payload = __PAYLOAD_JSON__;\nconst COLORS = {\n    neutral: "#8A8F98",\n    azimuth_only: "#E53935",\n    pan_only: "#1565C0",\n    shared: "#7B1FA2"\n};\nconst STATUS_LABELS = {\n    neutral: "No direct output in current scope",\n    azimuth_only: "Azimuth only",\n    pan_only: "Pan-human only",\n    shared: "Exact CT ID in both"\n};\nconst state = {\n    sex: "all",\n    author: "all",\n    inspect: true,\n    labels: true,\n    selectedId: null,\n};\n\nconst byId = new Map(payload.nodes.map(node => [node.data.id, node]));\nconst allMappedRows = payload.comparisonRows.filter(row => row.mapping_status === "mapped_clid");\nconst rowsByClid = new Map();\nfor (const row of allMappedRows) {\n    if (!rowsByClid.has(row.clid)) rowsByClid.set(row.clid, []);\n    rowsByClid.get(row.clid).push(row);\n}\n\nlet projectionFocus = {\n    enabled: false,\n    active: new Set(),\n    ancestors: new Set(),\n    pathEdges: new Set(),\n    outsideTree: new Set(),\n    statusCounts: { shared: 0, azimuth_only: 0, pan_only: 0 }\n};\n\nfunction projectionEdgeKey(source, target) {\n    return `${source}\\u0000${target}`;\n}\n\nfunction computeProjectionFocus() {\n    const active = new Set();\n    const ancestors = new Set();\n    const pathEdges = new Set();\n    const outsideTree = new Set();\n    const statusCounts = { shared: 0, azimuth_only: 0, pan_only: 0 };\n\n    if (state.author === "all") {\n        return { enabled: false, active, ancestors, pathEdges, outsideTree, statusCounts };\n    }\n\n    const selectedClids = new Set(\n        allMappedRows\n            .filter(row => matchesFilters(row) && (row.azimuth_count > 0 || row.pan_human_count > 0))\n            .map(row => row.clid)\n    );\n\n    for (const clid of selectedClids) {\n        if (!byId.has(clid)) {\n            outsideTree.add(clid);\n            continue;\n        }\n        active.add(clid);\n    }\n\n    for (const clid of active) {\n        const base = byId.get(clid);\n        const pathIds = base?.data?.pathIds || [];\n        for (const pathId of pathIds) ancestors.add(pathId);\n        for (let index = 1; index < pathIds.length; index++) {\n            pathEdges.add(projectionEdgeKey(pathIds[index - 1], pathIds[index]));\n        }\n        const status = aggregateClid(clid).status;\n        if (statusCounts[status] !== undefined) statusCounts[status] += 1;\n    }\n\n    for (const clid of active) ancestors.delete(clid);\n\n    return { enabled: true, active, ancestors, pathEdges, outsideTree, statusCounts };\n}\n\nfunction projectionRole(clid) {\n    if (!projectionFocus.enabled) return "none";\n    if (projectionFocus.active.has(clid)) return "destination";\n    if (projectionFocus.ancestors.has(clid)) return "ancestor";\n    return "unrelated";\n}\n\nfunction projectionScopeSentence() {\n    if (state.author === "all") return "";\n    if (state.sex === "all") {\n        return `Counts sum the female and male source cohorts for “${state.author}” where available.`;\n    }\n    return `Counts use only the ${state.sex.toLowerCase()} source cohort for “${state.author}”.`;\n}\n\nfunction escapeHtml(value) {\n    return String(value ?? "")\n        .replaceAll("&", "&amp;")\n        .replaceAll("<", "&lt;")\n        .replaceAll(">", "&gt;")\n        .replaceAll(\'"\', "&quot;")\n        .replaceAll("\'", "&#039;");\n}\nfunction fmtInt(value) { return Number(value || 0).toLocaleString("en-US"); }\nfunction fmtPct(value, denominator) {\n    const numerator = Number(value || 0);\n    const total = Number(denominator || 0);\n    if (!total) return "0.00%";\n    return `${(numerator / total * 100).toFixed(2)}%`;\n}\nfunction fmtCountPct(value, denominator) {\n    return `${fmtInt(value)} (${fmtPct(value, denominator)})`;\n}\nfunction scopeText() {\n    const sex = state.sex === "all" ? "All sexes" : state.sex;\n    const author = state.author === "all" ? "All author labels" : state.author;\n    return `${sex} · ${author}`;\n}\nfunction matchesFilters(row) {\n    return (state.sex === "all" || row.sex === state.sex)\n        && (state.author === "all" || row.ann_finest_level === state.author);\n}\nfunction filteredRowsForClid(clid) {\n    return (rowsByClid.get(clid) || []).filter(matchesFilters);\n}\nfunction aggregate(rows) {\n    const cohortSizes = new Map();\n    let azimuth = 0, pan = 0, both = 0, azimuthOnly = 0, panOnly = 0, union = 0;\n    for (const row of rows) {\n        if (row.azimuth_count <= 0 && row.pan_human_count <= 0) continue;\n        const cohortKey = `${row.sex}\\u0000${row.ann_finest_level}`;\n        const previousSize = cohortSizes.get(cohortKey);\n        if (previousSize !== undefined && previousSize !== row.author_cohort_size) {\n            throw new Error(`Inconsistent author cohort size for ${cohortKey}`);\n        }\n        cohortSizes.set(cohortKey, row.author_cohort_size);\n        azimuth += row.azimuth_count;\n        pan += row.pan_human_count;\n        both += row.both_same_cell_count;\n        azimuthOnly += row.azimuth_only_count;\n        panOnly += row.pan_human_only_count;\n        union += row.union_count;\n    }\n    let status = "neutral";\n    if (azimuth > 0 && pan > 0) status = "shared";\n    else if (azimuth > 0) status = "azimuth_only";\n    else if (pan > 0) status = "pan_only";\n    const activeScope = selectedScopeSummary();\n    return {\n        cohortCount: cohortSizes.size,\n        cohortCellCount: [...cohortSizes.values()].reduce((sum, value) => sum + value, 0),\n        activeCohortCount: activeScope.cohortCount,\n        activeCohortCellCount: activeScope.cohortCells,\n        azimuth, pan, both, azimuthOnly, panOnly, union,\n        azimuthPct: activeScope.cohortCells ? azimuth / activeScope.cohortCells * 100 : 0,\n        panPct: activeScope.cohortCells ? pan / activeScope.cohortCells * 100 : 0,\n        bothPct: activeScope.cohortCells ? both / activeScope.cohortCells * 100 : 0,\n        azimuthOnlyPct: activeScope.cohortCells ? azimuthOnly / activeScope.cohortCells * 100 : 0,\n        panOnlyPct: activeScope.cohortCells ? panOnly / activeScope.cohortCells * 100 : 0,\n        unionPct: activeScope.cohortCells ? union / activeScope.cohortCells * 100 : 0,\n        status, fillColor: COLORS[status]\n    };\n}\nfunction aggregateClid(clid) { return aggregate(filteredRowsForClid(clid)); }\nfunction selectedScopeSummary() {\n    const rows = payload.comparisonRows.filter(matchesFilters);\n    const cohorts = new Map();\n    for (const row of rows) {\n        cohorts.set(`${row.sex}\\u0000${row.ann_finest_level}`, row.author_cohort_size);\n    }\n    const mappedClids = new Set(\n        rows.filter(row => row.mapping_status === "mapped_clid"\n            && (row.azimuth_count > 0 || row.pan_human_count > 0))\n            .map(row => row.clid)\n    );\n    return {\n        cohortCount: cohorts.size,\n        cohortCells: [...cohorts.values()].reduce((a, b) => a + b, 0),\n        mappedClids: mappedClids.size\n    };\n}\n\nconst elements = [];\nfor (const node of payload.nodes) {\n    if (node.data.isComparisonNode) {\n        elements.push({\n            data: { id: `comparison-ring::${node.data.id}`, logicalId: node.data.id },\n            position: node.position,\n            classes: "comparisonRing"\n        });\n    }\n    elements.push({ ...node, classes: node.data.isComparisonNode ? "core comparisonCore" : "core normalCore" });\n}\nelements.push(...payload.edges);\n\nconst cy = cytoscape({\n    container: document.getElementById("cy"),\n    elements,\n    layout: { name: "preset", fit: true, padding: 50 },\n    minZoom: 0.025,\n    maxZoom: 5,\n    wheelSensitivity: 0.16,\n    selectionType: "single",\n    style: [\n        {\n            selector: "node.core",\n            style: {\n                "background-color": "data(fillColor)",\n                "label": "data(displayLabel)",\n                "font-size": 9,\n                "color": "#111827",\n                "text-valign": "bottom",\n                "text-halign": "center",\n                "text-margin-y": 5,\n                "text-wrap": "wrap",\n                "text-max-width": 150,\n                "overlay-opacity": 0,\n                "z-index-compare": "manual",\n                "z-index": 30\n            }\n        },\n        { selector: "node.normalCore", style: { "width": 14, "height": 14 } },\n        { selector: "node.comparisonCore", style: { "width": 28, "height": 28 } },\n        {\n            selector: "node.comparisonRing",\n            style: {\n                "width": 40, "height": 40,\n                "background-color": "#16A34A",\n                "border-width": 0,\n                "events": "no",\n                "overlay-opacity": 0,\n                "z-index-compare": "manual",\n                "z-index": 10\n            }\n        },\n        {\n            selector: "edge",\n            style: {\n                "width": 1.05,\n                "line-color": "#8A94A3",\n                "opacity": 0.48,\n                "curve-style": "straight",\n                "overlay-opacity": 0,\n                "z-index-compare": "manual",\n                "z-index": 1\n            }\n        },\n        {\n            selector: ".projectionDestination",\n            style: { "opacity": 1, "text-opacity": 1 }\n        },\n        {\n            selector: ".projectionAncestor",\n            style: { "opacity": 0.45, "text-opacity": 0.55 }\n        },\n        {\n            selector: ".projectionMuted",\n            style: { "opacity": 0.10, "text-opacity": 0.10 }\n        },\n        {\n            selector: "edge.projectionEdge",\n            style: { "line-color": "#6B7280", "width": 1.35, "opacity": 0.42 }\n        },\n        {\n            selector: "edge.projectionMutedEdge",\n            style: { "opacity": 0.045 }\n        },\n        {\n            selector: "node.core:selected",\n            style: {\n                "border-width": 3,\n                "border-color": "#111827",\n                "border-opacity": 0.85,\n                "opacity": 1,\n                "text-opacity": 1\n            }\n        },\n        {\n            selector: ".pathNode",\n            style: { "border-width": 3, "border-color": "#F59E0B", "border-opacity": 1, "opacity": 1, "text-opacity": 1 }\n        },\n        {\n            selector: ".pathEdge",\n            style: { "line-color": "#F59E0B", "width": 3.2, "opacity": 0.95 }\n        },\n        {\n            selector: ".hoverRootNode",\n            style: {\n                "border-width": 3,\n                "border-color": "#111827",\n                "border-opacity": 1,\n                "opacity": 1,\n                "text-opacity": 1\n            }\n        },\n        {\n            selector: ".hoverSubtreeNode",\n            style: {\n                "border-width": 2,\n                "border-style": "dotted",\n                "border-color": "#657084",\n                "border-opacity": 0.9,\n                "opacity": 1,\n                "text-opacity": 1\n            }\n        },\n        {\n            selector: "edge.hoverRootEdge",\n            style: {\n                "line-style": "solid",\n                "line-color": "#111827",\n                "width": 3.2,\n                "opacity": 1,\n                "z-index": 45\n            }\n        },\n        {\n            selector: "edge.hoverSubtreeEdge",\n            style: {\n                "line-style": "dotted",\n                "line-color": "#657084",\n                "width": 3.2,\n                "opacity": 0.95,\n                "z-index": 40\n            }\n        },\n        {\n            selector: ".searchMatch",\n            style: { "border-width": 4, "border-color": "#0EA5E9", "border-opacity": 1, "opacity": 1, "text-opacity": 1 }\n        }\n    ]\n});\n\nconst details = document.getElementById("details");\nconst tooltip = document.getElementById("tooltip");\nconst summary = document.getElementById("summary");\nconst toast = document.getElementById("toast");\nconst sexFilter = document.getElementById("sexFilter");\nconst authorFilter = document.getElementById("authorFilter");\nconst drawer = document.getElementById("comparisonDrawer");\nconst drawerBackdrop = document.getElementById("drawerBackdrop");\n\nfunction populateFilters() {\n    for (const sex of payload.sexes) {\n        const option = document.createElement("option");\n        option.value = sex; option.textContent = sex; sexFilter.appendChild(option);\n    }\n    for (const label of payload.authorLabels) {\n        const option = document.createElement("option");\n        option.value = label; option.textContent = label; authorFilter.appendChild(option);\n    }\n}\n\nfunction updateNodeVisuals() {\n    projectionFocus = computeProjectionFocus();\n\n    cy.batch(() => {\n        cy.nodes().removeClass("projectionDestination projectionAncestor projectionMuted");\n        cy.edges().removeClass("projectionEdge projectionMutedEdge");\n\n        for (const [clid] of rowsByClid) {\n            const core = cy.getElementById(clid);\n            if (!core || core.empty()) continue;\n            const metrics = aggregateClid(clid);\n            core.data("status", metrics.status);\n            core.data("fillColor", metrics.fillColor);\n            core.style("background-color", metrics.fillColor);\n        }\n\n        if (projectionFocus.enabled) {\n            for (const node of cy.nodes(".core")) {\n                const role = projectionRole(node.id());\n                const className = role === "destination"\n                    ? "projectionDestination"\n                    : role === "ancestor"\n                        ? "projectionAncestor"\n                        : "projectionMuted";\n                node.addClass(className);\n\n                const ring = cy.getElementById(`comparison-ring::${node.id()}`);\n                if (ring && !ring.empty()) ring.addClass(className);\n            }\n\n            for (const edge of cy.edges()) {\n                const key = projectionEdgeKey(edge.source().id(), edge.target().id());\n                edge.addClass(projectionFocus.pathEdges.has(key) ? "projectionEdge" : "projectionMutedEdge");\n            }\n        }\n    });\n\n    updateSummary();\n    if (state.selectedId) renderDetails(state.selectedId);\n    if (drawer.classList.contains("open") && state.selectedId) renderDrawer(state.selectedId);\n}\n\nfunction updateSummary() {\n    const selected = selectedScopeSummary();\n    if (!projectionFocus.enabled) {\n        summary.innerHTML = `<strong>${escapeHtml(scopeText())}</strong> · `\n            + `${fmtInt(selected.cohortCount)} cohort${selected.cohortCount === 1 ? "" : "s"} · `\n            + `${fmtInt(selected.mappedClids)} mapped CLIDs with direct assignments`;\n        return;\n    }\n\n    const status = projectionFocus.statusCounts;\n    const sexText = state.sex === "all" ? "All sexes" : state.sex;\n    const outsideText = projectionFocus.outsideTree.size\n        ? ` · ${fmtInt(projectionFocus.outsideTree.size)} additional CLID${projectionFocus.outsideTree.size === 1 ? "" : "s"} outside the tree`\n        : "";\n    summary.innerHTML = `<strong>Projected author label: ${escapeHtml(state.author)}</strong><br>`\n        + `${escapeHtml(sexText)} · ${fmtInt(selected.cohortCount)} source cohort${selected.cohortCount === 1 ? "" : "s"} · `\n        + `${fmtInt(projectionFocus.active.size)} exact CLID destination${projectionFocus.active.size === 1 ? "" : "s"} on the tree`\n        + outsideText\n        + `<br>${fmtInt(status.shared)} both · ${fmtInt(status.azimuth_only)} Azimuth only · ${fmtInt(status.pan_only)} pan-human only`;\n}\n\nfunction showToast(message) {\n    toast.textContent = message;\n    toast.classList.add("show");\n    window.clearTimeout(showToast.timer);\n    showToast.timer = window.setTimeout(() => toast.classList.remove("show"), 1700);\n}\n\nfunction clearPath() {\n    cy.elements().removeClass("pathNode pathEdge searchMatch");\n}\nfunction highlightPath(node) {\n    clearPath();\n    const ids = node.data("pathIds") || [];\n    for (const id of ids) cy.getElementById(id).addClass("pathNode");\n    for (let i = 1; i < ids.length; i++) {\n        cy.edges(`[source = "${ids[i - 1]}"][target = "${ids[i]}"]`).addClass("pathEdge");\n    }\n}\nfunction clearHoverTrace() {\n    cy.elements().removeClass(\n        "hoverRootNode hoverSubtreeNode hoverRootEdge hoverSubtreeEdge"\n    );\n}\nfunction applyHoverTrace(node) {\n    clearHoverTrace();\n\n    const rootPathIds = node.data("pathIds") || [];\n    for (const id of rootPathIds) {\n        cy.getElementById(id).addClass("hoverRootNode");\n    }\n    for (let index = 1; index < rootPathIds.length; index++) {\n        cy.edges(\n            `[source = "${rootPathIds[index - 1]}"][target = "${rootPathIds[index]}"]`\n        ).addClass("hoverRootEdge");\n    }\n\n    const queue = [node.id()];\n    const visited = new Set([node.id()]);\n\n    while (queue.length) {\n        const sourceId = queue.shift();\n        const sourceData = byId.get(sourceId)?.data;\n        for (const childId of sourceData?.childIds || []) {\n            cy.edges(\n                `[source = "${sourceId}"][target = "${childId}"]`\n            ).addClass("hoverSubtreeEdge");\n\n            if (!visited.has(childId)) {\n                visited.add(childId);\n                queue.push(childId);\n            }\n        }\n    }\n\n    visited.delete(node.id());\n    for (const descendantId of visited) {\n        cy.getElementById(descendantId).addClass("hoverSubtreeNode");\n    }\n}\n\nfunction disclosureHtml() {\n    const outsideItems = payload.outsideTree.map(item =>\n        `<li><span class="formula">${escapeHtml(item.clid)}</span> — ${fmtInt(item.aggregate.union)} union assignments across ${fmtInt(item.aggregate.cohortCount)} cohorts</li>`\n    ).join("") || "<li>None</li>";\n    const nonClItems = payload.nonCl.map(item =>\n        `<li><span class="formula">${escapeHtml(item.clid)}</span> — ${fmtInt(item.aggregate.union)} assignments across ${fmtInt(item.aggregate.cohortCount)} cohorts</li>`\n    ).join("") || "<li>None</li>";\n    return `\n        <details class="disclosure">\n            <summary>Outside-supertree mapped CLIDs (${fmtInt(payload.summary.outsideTreeClidCount)})</summary>\n            <div class="disclosure-body"><ul class="disclosure-list">${outsideItems}</ul></div>\n        </details>\n        <details class="disclosure">\n            <summary>Non-CL identifiers (${fmtInt(payload.summary.nonClCellCount)} cells)</summary>\n            <div class="disclosure-body"><ul class="disclosure-list">${nonClItems}</ul></div>\n        </details>\n        <details class="disclosure">\n            <summary>Absent method records represented as NA (${fmtInt(payload.summary.absentCellCount)} cells)</summary>\n            <div class="disclosure-body">These cells are retained in the validation accounting but do not create ontology nodes. The NA category is displayed only as a completeness disclosure.</div>\n        </details>`;\n}\n\nfunction renderPlaceholder() {\n    details.innerHTML = `\n        <h2>Exact-node comparison</h2>\n        <div class="node-id">Select a Cell Ontology node</div>\n        <div class="placeholder">A green ring marks an exact CLID that occurs in the comparison results from 47 paired HLCA lung dataset partitions. The ring only indicates comparison membership; it does not encode magnitude. Green-ringed nodes are enlarged. Node fill shows which method assigns that exact CLID in the current filter scope. Selecting a specific Author label projects that source cohort across its exact CLID destinations: destination nodes remain fully visible, their ancestors remain as hierarchy context, and unrelated nodes fade. Hover or click for exact-node counts.</div>\n        <div class="section">\n            <div class="section-title">Validated input</div>\n            <div class="section-value">\n                ${fmtInt(payload.summary.comparisonRowCount)} aggregate rows ·\n                ${fmtInt(payload.summary.cohortCount)} author cohorts ·\n                ${fmtInt(payload.summary.comparisonClidCount)} valid CLIDs\n            </div>\n        </div>\n        <div class="section">\n            <div class="section-title">Comparison nodes on tree</div>\n            <div class="section-value">\n                ${fmtInt(payload.summary.mappedToTreeClidCount)} comparison CLIDs are shown on the tree;\n                ${fmtInt(payload.summary.outsideTreeClidCount)} valid CLIDs are outside this hierarchy.\n            </div>\n        </div>\n        ${disclosureHtml()}`;\n}\n\nfunction metricCard(label, value, sub = "") {\n    return `<div class="side-metric"><div class="side-metric-label">${escapeHtml(label)}</div><div class="side-metric-value">${escapeHtml(value)}</div>${sub ? `<div class="side-metric-sub">${escapeHtml(sub)}</div>` : ""}</div>`;\n}\n\nfunction renderDetails(clid) {\n    const base = byId.get(clid);\n    if (!base) return;\n    state.selectedId = clid;\n    const metrics = aggregateClid(clid);\n    const statusLabel = STATUS_LABELS[metrics.status];\n    const statusColor = COLORS[metrics.status];\n    const comparisonNode = Boolean(base.data.isComparisonNode);\n    const role = projectionRole(clid);\n    const projectionSection = projectionFocus.enabled ? `\n        <div class="section">\n            <div class="section-title">Author-label projection</div>\n            ${role === "destination" ? `\n                <div class="section-value"><strong>Source:</strong> ${escapeHtml(state.author)} → <strong>Destination:</strong> ${escapeHtml(base.data.label)}</div>\n                <div class="section-value" style="margin-top:6px">The selected author cohort is the source population. This exact Cell Ontology node is one destination predicted for cells from that cohort. ${escapeHtml(projectionScopeSentence())} Descendants are not included.</div>` : role === "ancestor" ? `\n                <div class="section-value"><strong>Hierarchy context</strong></div>\n                <div class="section-value" style="margin-top:6px">This node is shown at medium opacity because it connects the root to one or more exact CLID destinations for the selected author label. It is not itself a direct destination in the current scope.</div>` : `\n                <div class="section-value"><strong>No direct projection here</strong></div>\n                <div class="section-value" style="margin-top:6px">No cells from the selected author-label scope were assigned to this exact CLID by either method. The node remains visible only to preserve the full supertree context.</div>`}\n        </div>` : "";\n    details.innerHTML = `\n        <h2>${escapeHtml(base.data.label)}</h2>\n        <div class="node-id">${escapeHtml(clid)}</div>\n        <span class="pill exact-pill">Exact node only</span>\n        <span class="pill status-pill" style="background:${statusColor}">${escapeHtml(statusLabel)}</span>\n        <div class="section">\n            <div class="section-title">Current filter scope</div>\n            <div class="section-value">${escapeHtml(scopeText())}</div>\n        </div>\n        ${projectionSection}\n        <div class="section">\n            <div class="section-title">${projectionFocus.enabled ? "Projected exact-node totals" : "Exact-node totals across cohorts"}</div>\n            ${comparisonNode ? `\n                <div class="metric-grid">\n                    ${metricCard("Active cohorts", fmtInt(metrics.activeCohortCount), "Distinct sex + author-label cohorts matching the current filters.")}\n                    ${metricCard("Total cells in active cohort", fmtInt(metrics.activeCohortCellCount), "All author-annotated cells matching the active filters, counted once per cohort; denominator for every percentage.")}\n                    ${metricCard("Azimuth", fmtCountPct(metrics.azimuth, metrics.activeCohortCellCount), "Exact-node assignments and their share of the active cohort.")}\n                    ${metricCard("Pan-human", fmtCountPct(metrics.pan, metrics.activeCohortCellCount), "Exact-node assignments and their share of the active cohort.")}\n                    ${metricCard("Both same cells", fmtCountPct(metrics.both, metrics.activeCohortCellCount), "Same individual cells assigned here by both methods.")}\n                    ${metricCard("Azimuth only", fmtCountPct(metrics.azimuthOnly, metrics.activeCohortCellCount), "Assigned here by Azimuth but not by pan-human.")}\n                    ${metricCard("Pan-human only", fmtCountPct(metrics.panOnly, metrics.activeCohortCellCount), "Assigned here by pan-human but not by Azimuth.")}\n                    ${metricCard("Union", fmtCountPct(metrics.union, metrics.activeCohortCellCount), "Unique cells assigned here by either method; shared cells count once.")}\n                </div>\n                <div class="section-value" style="margin-top:8px">${projectionFocus.enabled ? `These counts show how cells originally labeled <strong>“${escapeHtml(state.author)}”</strong> by the dataset authors were assigned to this exact Cell Ontology term. ${escapeHtml(projectionScopeSentence())}` : `Counts are summed across matching <span class="formula">sex + author label</span> cohorts in the current filters.`} Values refer to this exact CLID only, not descendants. “Total cells in active cohort” is the denominator used for all percentages shown here.</div>` : `<div class="section-value">This CLID is not present in the comparison CSV.</div>`}\n        </div>\n        <div class="section">\n            <div class="section-title">Hierarchy</div>\n            <div class="section-value"><strong>Parents:</strong> ${escapeHtml((base.data.parentLabels || []).length ? base.data.parentLabels.join(", ") : "Root")}</div>\n            <div class="section-value"><strong>Primary layout parent:</strong> ${escapeHtml(base.data.parentLabel || "Root")}</div>\n            <div class="section-value"><strong>Children:</strong> ${fmtInt(base.data.childCount)}</div>\n            <div class="section-value"><strong>Descendants:</strong> ${fmtInt(base.data.descendantCount)}</div>\n        </div>\n        <div class="section">\n            <div class="section-title">Root-to-node path</div>\n            <div class="section-value">${escapeHtml(base.data.pathText)}</div>\n        </div>\n        ${comparisonNode ? `<button class="open-comparison" id="openComparison" ${metrics.cohortCount ? "" : "disabled"}>Open exact-node cohort table</button>` : ""}\n        ${disclosureHtml()}`;\n    const button = document.getElementById("openComparison");\n    if (button) button.addEventListener("click", () => openDrawer(clid));\n}\n\nfunction tooltipHtml(clid) {\n    const base = byId.get(clid);\n    const metrics = aggregateClid(clid);\n    const comparisonNode = Boolean(base.data.isComparisonNode);\n    const role = projectionRole(clid);\n    let body = `<div class="title">${escapeHtml(base.data.label)}</div><div class="id">${escapeHtml(clid)}</div><div class="scope">${escapeHtml(scopeText())}</div>`;\n\n    if (projectionFocus.enabled && role === "ancestor") {\n        body += `<div><strong>Hierarchy context</strong></div>`\n            + `<div>This node is kept at medium opacity because it lies on a root-to-destination path for the selected author label <strong>“${escapeHtml(state.author)}”</strong>. No cells from that source cohort were assigned directly to this exact CLID in the current scope.</div>`;\n    } else if (projectionFocus.enabled && role === "unrelated") {\n        body += `<div><strong>No direct projection here</strong></div>`\n            + `<div>No cells originally labeled <strong>“${escapeHtml(state.author)}”</strong> were assigned to this exact CLID by either method under the current Sex filter. The node is faded to preserve focus while keeping the whole hierarchy visible.</div>`;\n        if (comparisonNode) {\n            body += `<div class="interpretation">The green ring is global: this CLID occurs somewhere in the full comparison of 47 paired HLCA lung dataset partitions, even though it is unrelated to the current author-label projection.</div>`;\n        }\n    } else if (comparisonNode && metrics.cohortCount) {\n        body += `<div><strong>${escapeHtml(STATUS_LABELS[metrics.status])}</strong></div>`\n            + `<div>Active cohorts: ${fmtInt(metrics.activeCohortCount)}</div>`\n            + `<div>Total cells in active cohort: ${fmtInt(metrics.activeCohortCellCount)}</div>`\n            + `<div>Azimuth: ${fmtCountPct(metrics.azimuth, metrics.activeCohortCellCount)}</div>`\n            + `<div>Pan-human: ${fmtCountPct(metrics.pan, metrics.activeCohortCellCount)}</div>`\n            + `<div>Both same cells: ${fmtCountPct(metrics.both, metrics.activeCohortCellCount)}</div>`\n            + `<div>Azimuth only: ${fmtCountPct(metrics.azimuthOnly, metrics.activeCohortCellCount)}</div>`\n            + `<div>Pan-human only: ${fmtCountPct(metrics.panOnly, metrics.activeCohortCellCount)}</div>`\n            + `<div>Union: ${fmtCountPct(metrics.union, metrics.activeCohortCellCount)}</div>`;\n\n        if (projectionFocus.enabled) {\n            body += `<div class="interpretation"><strong>How to read this projection:</strong> these counts show how cells originally labeled <strong>“${escapeHtml(state.author)}”</strong> by the dataset authors were assigned to this exact Cell Ontology term. ${escapeHtml(projectionScopeSentence())} Azimuth and pan-human are exact-node assignments; “Both same cells” are the same individual cells assigned here by both methods, and “Union” counts unique cells assigned here by either method. Descendants are not included.</div>`;\n        } else {\n            body += `<div class="interpretation"><strong>How to read:</strong> a cohort is one sex + author-label group in which either method assigned at least one cell to this exact CLID. “Total cells in active cohort” counts every author-annotated cell matching the active filters once per cohort and is the denominator for the displayed percentages. Azimuth and pan-human totals are exact-CLID assignments. “Both same cells” are the same individual cells assigned here by both methods, while “Union” counts unique cells assigned here by either method.</div>`;\n        }\n    } else if (comparisonNode) {\n        body += `<div>The green ring means this CLID is represented somewhere in the 47-partition comparison, but no exact-node rows match the current filters.</div>`;\n    } else {\n        body += `<div>Not present in the comparison CSV.</div>`;\n    }\n    body += `<div class="path">${escapeHtml(base.data.pathText)}</div>`;\n    return body;\n}\n\nfunction positionTooltip(event) {\n    const pad = 14;\n    let x = event.originalEvent.clientX + 14;\n    let y = event.originalEvent.clientY + 14;\n    const rect = tooltip.getBoundingClientRect();\n    if (x + rect.width + pad > window.innerWidth) x = event.originalEvent.clientX - rect.width - 14;\n    if (y + rect.height + pad > window.innerHeight) y = event.originalEvent.clientY - rect.height - 14;\n    tooltip.style.left = `${Math.max(pad, x)}px`;\n    tooltip.style.top = `${Math.max(pad, y)}px`;\n}\n\nfunction openDrawer(clid) {\n    state.selectedId = clid;\n    renderDrawer(clid);\n    drawer.classList.add("open");\n    drawerBackdrop.classList.add("open");\n    drawer.setAttribute("aria-hidden", "false");\n}\nfunction closeDrawer() {\n    drawer.classList.remove("open");\n    drawerBackdrop.classList.remove("open");\n    drawer.setAttribute("aria-hidden", "true");\n}\nfunction renderDrawer(clid) {\n    const base = byId.get(clid);\n    const rows = filteredRowsForClid(clid).sort((a, b) =>\n        a.ann_finest_level.localeCompare(b.ann_finest_level) || a.sex.localeCompare(b.sex)\n    );\n    const metrics = aggregate(rows);\n    document.getElementById("drawerTitle").textContent = base.data.label;\n    document.getElementById("drawerSubtitle").textContent = projectionFocus.enabled\n        ? `${clid} · ${state.author} → ${base.data.label} · Exact node only`\n        : `${clid} · Exact node only`;\n    document.getElementById("drawerScope").textContent = scopeText();\n    document.getElementById("metricCohorts").textContent = fmtInt(metrics.activeCohortCount);\n    document.getElementById("metricCohortCells").textContent = fmtInt(metrics.activeCohortCellCount);\n    document.getElementById("metricAzimuth").textContent = fmtCountPct(metrics.azimuth, metrics.activeCohortCellCount);\n    document.getElementById("metricPan").textContent = fmtCountPct(metrics.pan, metrics.activeCohortCellCount);\n    document.getElementById("metricBoth").textContent = fmtCountPct(metrics.both, metrics.activeCohortCellCount);\n    document.getElementById("metricAzimuthOnly").textContent = fmtCountPct(metrics.azimuthOnly, metrics.activeCohortCellCount);\n    document.getElementById("metricPanOnly").textContent = fmtCountPct(metrics.panOnly, metrics.activeCohortCellCount);\n    document.getElementById("metricUnion").textContent = fmtCountPct(metrics.union, metrics.activeCohortCellCount);\n    document.getElementById("comparisonRows").innerHTML = rows.length ? rows.map(row => `\n        <tr>\n            <td>${escapeHtml(row.sex)}</td>\n            <td>${escapeHtml(row.ann_finest_level)}</td>\n            <td>${fmtInt(row.author_cohort_size)}</td>\n            <td class="tool-lung">${fmtCountPct(row.azimuth_count, row.author_cohort_size)}</td>\n            <td class="tool-pan">${fmtCountPct(row.pan_human_count, row.author_cohort_size)}</td>\n            <td>${fmtCountPct(row.both_same_cell_count, row.author_cohort_size)}</td>\n            <td>${fmtCountPct(row.azimuth_only_count, row.author_cohort_size)}</td>\n            <td>${fmtCountPct(row.pan_human_only_count, row.author_cohort_size)}</td>\n            <td>${fmtCountPct(row.union_count, row.author_cohort_size)}</td>\n        </tr>`).join("") : `<tr><td colspan="9" style="text-align:left;color:#647084">No rows match the current filters.</td></tr>`;\n}\n\ncy.on("mouseover", "node.core", event => {\n    if (!state.inspect) return;\n    applyHoverTrace(event.target);\n    tooltip.innerHTML = tooltipHtml(event.target.id());\n    tooltip.style.display = "block";\n    positionTooltip(event);\n});\ncy.on("mousemove", "node.core", event => {\n    if (state.inspect && tooltip.style.display === "block") positionTooltip(event);\n});\ncy.on("mouseout", "node.core", () => {\n    tooltip.style.display = "none";\n    clearHoverTrace();\n});\ncy.on("tap", "node.core", event => {\n    const node = event.target;\n    state.selectedId = node.id();\n    highlightPath(node);\n    renderDetails(node.id());\n});\ncy.on("tap", event => {\n    if (event.target === cy) {\n        clearPath();\n        state.selectedId = null;\n        renderPlaceholder();\n    }\n});\n\nfunction runSearch() {\n    const query = document.getElementById("search").value.trim().toLowerCase();\n    cy.elements().removeClass("searchMatch");\n    if (!query) return;\n    const matches = cy.nodes(".core").filter(node =>\n        node.id().toLowerCase().includes(query)\n        || String(node.data("label") || "").toLowerCase().includes(query)\n    );\n    if (!matches.length) { showToast("No matching cell type or ontology ID"); return; }\n    matches.addClass("searchMatch");\n    cy.animate({ fit: { eles: matches, padding: 100 }, duration: 320 });\n    if (matches.length === 1) {\n        const node = matches[0]; node.select(); highlightPath(node); renderDetails(node.id()); state.selectedId = node.id();\n    } else showToast(`${matches.length} matching nodes`);\n}\n\ndocument.getElementById("searchButton").addEventListener("click", runSearch);\ndocument.getElementById("search").addEventListener("keydown", event => { if (event.key === "Enter") runSearch(); });\ndocument.getElementById("fitButton").addEventListener("click", () => cy.animate({ fit: { eles: cy.elements(), padding: 45 }, duration: 300 }));\ndocument.getElementById("zoomIn").addEventListener("click", () => cy.zoom({ level: cy.zoom() * 1.22, renderedPosition: { x: cy.width()/2, y: cy.height()/2 } }));\ndocument.getElementById("zoomOut").addEventListener("click", () => cy.zoom({ level: cy.zoom() / 1.22, renderedPosition: { x: cy.width()/2, y: cy.height()/2 } }));\ndocument.getElementById("inspectToggle").addEventListener("click", event => {\n    state.inspect = !state.inspect; event.currentTarget.classList.toggle("active", state.inspect);\n    if (!state.inspect) {\n        tooltip.style.display = "none";\n        clearHoverTrace();\n    }\n});\ndocument.getElementById("labelsToggle").addEventListener("click", event => {\n    state.labels = !state.labels; event.currentTarget.classList.toggle("active", state.labels);\n    cy.style().selector("node.core").style("label", state.labels ? "data(displayLabel)" : "").update();\n});\nsexFilter.addEventListener("change", () => { state.sex = sexFilter.value; updateNodeVisuals(); });\nauthorFilter.addEventListener("change", () => { state.author = authorFilter.value; updateNodeVisuals(); });\ndocument.getElementById("drawerClose").addEventListener("click", closeDrawer);\ndrawerBackdrop.addEventListener("click", closeDrawer);\nconst legend = document.getElementById("legend");\nconst legendToggle = document.getElementById("legendToggle");\nlegendToggle.addEventListener("click", () => {\n    const collapsed = legend.classList.toggle("collapsed");\n    legendToggle.textContent = collapsed ? "Expand" : "Minimize";\n    legendToggle.setAttribute("aria-expanded", String(!collapsed));\n    legendToggle.setAttribute(\n        "aria-label",\n        collapsed ? "Expand legend" : "Minimize legend"\n    );\n});\ndocument.addEventListener("keydown", event => { if (event.key === "Escape") closeDrawer(); });\npopulateFilters();\nrenderPlaceholder();\nupdateNodeVisuals();\nwindow.setTimeout(() => cy.fit(cy.elements(), 45), 60);\n})();\n</script>\n</body>\n</html>\n\n\'\'\'\n\n\n\ndef render_html(payload: dict[str, Any]) -> str:\n    payload_json = safe_json_for_script(payload)\n    return HTML_TEMPLATE.replace("__PAYLOAD_JSON__", payload_json)\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(\n        description=(\n            "Build the HLCA exact-node organ-specific Azimuth versus "\n            "pan-human Azimuth comparison on the CTann v9 supertree."\n        )\n    )\n    parser.add_argument(\n        "--tree",\n        type=Path,\n        default=DEFAULT_TREE,\n        help="Supertree CSV/TSV. Default: data/ctann-v9.csv",\n    )\n    parser.add_argument(\n        "--comparison",\n        type=Path,\n        default=None,\n        help=(\n            "Aggregate HLCA comparison CSV/TSV. When omitted, the script "\n            "searches the data directory for a file with the required "\n            "comparison columns."\n        ),\n    )\n    parser.add_argument(\n        "--output",\n        type=Path,\n        default=DEFAULT_OUTPUT,\n        help=(\n            "Output HTML. Default: output_htmls/"\n            "hlca-azimuth-pan-human-exact-node-comparison.html"\n        ),\n    )\n    parser.add_argument(\n        "--paired-dataset-count",\n        type=int,\n        default=47,\n        help="Number of paired HLCA dataset partitions described in the UI.",\n    )\n    parser.add_argument(\n        "--skip-count-validation",\n        action="store_true",\n        help=(\n            "Skip formula checks for method-only and union columns. "\n            "Cohort-size consistency is still checked."\n        ),\n    )\n    return parser.parse_args()\n\n\ndef main() -> None:\n    args = parse_args()\n\n    tree_path = args.tree.expanduser().resolve()\n    if not tree_path.exists():\n        raise FileNotFoundError(\n            f"Supertree input not found: {tree_path}"\n        )\n\n    comparison_path = (\n        args.comparison.expanduser().resolve()\n        if args.comparison is not None\n        else discover_comparison_path(tree_path.parent).resolve()\n    )\n    if not comparison_path.exists():\n        raise FileNotFoundError(\n            f"HLCA comparison input not found: {comparison_path}"\n        )\n\n    output_path = args.output.expanduser().resolve()\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n\n    print(f"Builder version: {BUILD_VERSION}")\n    print(f"Supertree input: {tree_path}")\n    print(f"HLCA comparison input: {comparison_path}")\n    print(f"Output HTML: {output_path}")\n\n    tree = read_supertree(tree_path)\n    comparison = read_comparison(\n        comparison_path,\n        validate_counts=not args.skip_count_validation,\n    )\n    payload = build_payload(\n        tree,\n        comparison,\n        paired_dataset_count=args.paired_dataset_count,\n    )\n\n    output_path.write_text(\n        render_html(payload),\n        encoding="utf-8",\n    )\n\n    summary = payload["summary"]\n    print(\n        "Built "\n        f"{summary[\'treeNodeCount\']:,} nodes and "\n        f"{summary[\'treeEdgeCount\']:,} edges."\n    )\n    print(\n        "Comparison: "\n        f"{summary[\'comparisonRowCount\']:,} aggregate rows, "\n        f"{summary[\'cohortCount\']:,} sex × author-label cohorts, "\n        f"{summary[\'mappedToTreeClidCount\']:,} CLIDs on the tree, "\n        f"{summary[\'outsideTreeClidCount\']:,} CLIDs outside the tree."\n    )\n    print(f"Wrote: {output_path}")\n\n\nif __name__ == "__main__":\n    main()\n'


def load_embedded_builder(name: str, source: str) -> types.ModuleType:
    """Execute one embedded builder in its own module namespace."""
    module = types.ModuleType(name)
    module.__file__ = str(Path(__file__).resolve())
    module.__package__ = None
    exec(compile(source, f"<{name}>", "exec"), module.__dict__)
    return module


def safe_json_for_script(value: Any) -> str:
    """Serialize JSON so embedded HTML cannot terminate the outer script."""
    text = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return (
        text.replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
        .replace("\u2028", "\\u2028")
        .replace("\u2029", "\\u2029")
    )


